// Generated by scripts/gen-l10n.mjs (gdetail n2, vi) — 不要手改;改翻譯請改 scripts/out/l10n/vi/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["vi"]=Object.assign(window.GRAMMAR_DETAIL_L10N["vi"]||{},{"n2-8":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜からには」nghĩa là <b>「Đã ～ thì phải ～」</b>. Vế trước là một việc đã quyết định, đã xảy ra, không thể thay đổi. Vế sau nói «vậy thì mình nhất định phải…». Giống như tiếng Việt hay nói «Đã làm thì làm cho tới nơi tới chốn», tiếng Nhật sẽ là: <span class='gd-jp'>やるからには、一番を目指す。</span>（Đã làm thì nhắm tới vị trí số một）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Hay đi với động từ nhất. Điểm quan trọng là vế trước dùng 「た」 hay thể nguyên dạng (thể từ điển), vì nghĩa sẽ khác nhau:<br><b>Việc đã làm rồi</b>: thể た＋からには　<span class='gd-pair'><span class='gd-jp'>引き受けた</span> → <span class='gd-jp'>引き受けたからには</span></span>（đã nhận lời rồi thì…）<br><b>Việc đã quyết định làm nhưng chưa làm</b>: thể từ điển＋からには　<span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するからには</span></span>（đã đi du học thì…）<br><b>Danh từ, tính từ な</b>: ở giữa phải thêm 「である」　<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロであるからには</span></span>（đã là dân chuyên nghiệp thì…）</div><div class='gd-h'>Vế sau nói gì?</div><div class='gd-sec'>Sau からには luôn là «vì vậy mình nên có thái độ gì», chứ không chỉ kể một sự việc đã xảy ra. Có bốn kiểu hay gặp nhất:</div><div class='gd-sec'><span class='gd-tag'>Quyết tâm</span>Mình nhất định sẽ làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したからには、必ず守る。</span>（Đã hứa rồi thì nhất định sẽ giữ lời）</div><div class='gd-sec'><span class='gd-tag'>Nghĩa vụ</span>Hay đi với 「なければならない」「べきだ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に出るからには、毎日練習しなければならない。</span>（Đã tham gia thi đấu thì phải luyện tập mỗi ngày）</div><div class='gd-sec'><span class='gd-tag'>Yêu cầu đối phương</span>Hay đi với 「てください」.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に住むからには、ゴミの出し方はちゃんと覚えてください。</span>（Đã sống ở Nhật thì bạn hãy nhớ cho kỹ cách đổ rác nhé）</div><div class='gd-sec'><span class='gd-tag'>Phán đoán đương nhiên</span>Hay đi với 「はずだ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼がやると言ったからには、ちゃんとやるはずだ。</span>（Đã nói là sẽ làm thì chắc chắn anh ấy sẽ làm đàng hoàng）</div><div class='gd-h'>Những câu hay nghe nhất</div><div class='gd-sec'>Mấy câu này gần như là cách nói cố định, bạn cứ nhớ nguyên câu nhé:</div><div class='gd-ex-line'>・<span class='gd-jp'>やるからには、本気でやろう。</span>（Đã làm thì làm cho nghiêm túc đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>こうなったからには、もうやるしかない。</span>（Đã đến nước này thì chỉ còn cách liều mà làm thôi）</div><div class='gd-ex-line'>・<span class='gd-jp'>自分で決めたからには、最後までがんばる。</span>（Đã tự mình quyết định thì sẽ cố gắng đến cùng）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau không thể chỉ kể một việc đã xảy ra.<br>×<span class='gd-jp'>日本に来たからには、寿司を食べた。</span><br>○<span class='gd-jp'>日本に来たからには、本場の寿司を食べたい。</span>（Đã đến Nhật thì muốn ăn sushi chính gốc）<br>・Danh từ không nối trực tiếp được: không nói プロからには mà phải nói <span class='gd-jp'>プロであるからには</span>.<br>・Đừng dùng lẫn thể た và thể nguyên dạng: <span class='gd-jp'>結婚したからには</span> là đã kết hôn rồi, còn <span class='gd-jp'>結婚するからには</span> là đã quyết định sẽ kết hôn.<br>・Mẫu này mang quyết tâm «mình sẽ gánh việc này», nên sắc thái rất nặng. Nếu chỉ nêu lý do đơn thuần, ví dụ «trời mưa nên mang ô», thì dùng 「から」 là đủ, không cần からには.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>からこそ</b>（n2-9）＝<b>chính vì ～ nên ～</b>, nhấn mạnh «lý do chính là cái này».<br><b>からには</b>＝<b>đã ～ thì phải ～</b>, trọng tâm là «tiếp theo mình nên làm gì».<br>Cùng nói về công việc yêu thích:<br>・<span class='gd-jp'>好きな仕事を選んだからには、簡単にはやめない。</span>（Đã chọn công việc mình thích thì sẽ không dễ dàng bỏ cuộc）<br>・<span class='gd-jp'>好きな仕事だからこそ、毎日がんばれる。</span>（Chính vì là công việc mình thích nên mới có thể cố gắng mỗi ngày）</div><div class='gd-sec'><b>上は</b>（n2-32）＝nghĩa gần như giống からには, nhưng cứng và trang trọng hơn, hay dùng trong văn viết hoặc hoàn cảnh chính thức. Ngoài ra 「以上（は）」 mà bạn hay nghe cũng có nghĩa rất gần.<br>・<span class='gd-jp'>引き受けたからには、最後までやります。</span>（Đã nhận rồi thì tôi sẽ làm đến cùng: dùng được trong nói chuyện hằng ngày）<br>・<span class='gd-jp'>引き受けた上は、最後までやり遂げる所存です。</span>（Đã nhận lời, tôi xin nguyện làm trọn đến cùng: dùng trong hoàn cảnh trang trọng）</div><div class='gd-warn'>Mẹo nhỏ để chọn: «Đã ～ thì phải ～» dùng からには; «Chính vì ～ nên mới ～» dùng からこそ; cũng là «đã», nếu muốn nói trang trọng hơn thì đổi thành 上は.</div>","n2-25":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜どころか」nghĩa là <b>«Đâu có ～, thậm chí còn…», «Nói gì đến ～, đến … còn không…»</b>. Trước tiên nêu điều A mà ai cũng nghĩ, rồi cho bạn biết thực tế khác xa A, thường là <b>hoàn toàn ngược lại</b>. Ví dụ bạn tưởng nghỉ lễ sẽ được nghỉ ngơi, kết quả là «nghỉ ngơi gì đâu, còn mệt hơn đi làm».</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ: thể từ điển＋どころか　<span class='gd-pair'><span class='gd-jp'>やせる</span> → <span class='gd-jp'>やせるどころか</span></span><br>Tính từ い: nối trực tiếp　<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いどころか</span></span><br>Tính từ な, danh từ: nối trực tiếp, <b>không thêm だ</b>　<span class='gd-pair'><span class='gd-jp'>簡単</span> → <span class='gd-jp'>簡単どころか</span></span><span class='gd-pair'><span class='gd-jp'>旅行</span> → <span class='gd-jp'>旅行どころか</span></span></div><div class='gd-h'>Những kiểu hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Ngược lại hoàn toàn</span>A không những không xảy ra mà còn đi theo hướng ngược lại. Vế sau hay có <span class='gd-jp'>逆に</span>、<span class='gd-jp'>かえって</span>、<span class='gd-jp'>もっと</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエットしているのに、やせるどころか太ってしまった。</span>（Mình đang ăn kiêng rõ ràng thế mà gầy đi đâu không thấy, còn béo thêm）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んだのに、よくなるどころか、もっと悪くなった。</span>（Uống thuốc rồi mà không những không khá hơn, còn nặng hơn）</div><div class='gd-sec'><span class='gd-tag'>Nói gì A, đến B cũng không</span>A là việc khó hơn, B là việc cơ bản hơn. Đến B còn không làm được thì A càng khỏi nói. Vế sau hay có 「も」「さえ」＋phủ định.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、旅行どころか、週末に休むこともできない。</span>（Bận đến mức nói gì đi du lịch, đến nghỉ ngơi cuối tuần cũng không được）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は漢字どころか、ひらがなも読めない。</span>（Anh ấy nói gì chữ Hán, đến chữ Hiragana cũng không đọc được）</div><div class='gd-sec'><span class='gd-tag'>Đâu chỉ A</span>Thực tế còn quá hơn A nhiều, cùng hướng nhưng vượt xa.</div><div class='gd-ex-line'>・<span class='gd-jp'>1万円どころか、5万円もかかった。</span>（Đâu chỉ một vạn yên, tốn tới năm vạn luôn）</div><div class='gd-sec'><span class='gd-tag'>それどころか</span>Đặt ở đầu câu để đáp lại lời đối phương: «Đâu có, thực ra ngược lại…». Rất hay dùng trong hội thoại.</div><div class='gd-ex-line'>・<span class='gd-jp'>「迷惑だった？」「それどころか、すごく助かったよ。」</span>（«Có làm phiền bạn không?» «Đâu có, ngược lại bạn giúp mình nhiều lắm.»）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ và tính từ な đừng thêm だ: nói <span class='gd-jp'>簡単どころか</span>, không nói 簡単だどころか.<br>・Đừng đặt ngược thứ tự trong «Nói gì A, đến B cũng…»: A là việc <b>khó hơn</b>, B là việc <b>cơ bản hơn</b>. Câu đúng là 「漢字どころか、ひらがなも読めない」; nếu nói ngược 「ひらがなどころか、漢字も読めない」 thì nghĩa sẽ rất kỳ.<br>・Khi A và B đều là điều tốt và bạn chỉ muốn «bổ sung thêm», không dùng どころか được: «Quán này ngon, mà còn rẻ» không thể nói 美味しいどころか安い, phải dùng <span class='gd-jp'>ばかりか</span> hoặc <span class='gd-jp'>だけでなく</span>.<br>・どころか mang cảm xúc «ngoài dự đoán, hơi sững sờ», hợp với kết quả bất ngờ. Với những việc bình thường thì đừng cố áp vào.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là ngày mưa:<br><b>ばかりか</b>＝A <b>đúng</b>, rồi cộng thêm B: <span class='gd-jp'>雨ばかりか、雷まで鳴りだした。</span>（Không chỉ mưa, đến sấm cũng nổ luôn）<br><b>どころか</b>＝A <b>bị bác bỏ</b>, thực tế ngược lại: <span class='gd-jp'>雨がやむどころか、どんどん強くなっている。</span>（Mưa đâu có tạnh, còn càng lúc càng to）<br><b>どころじゃない</b>＝bây giờ <b>hoàn toàn không còn sức</b> làm A: <span class='gd-jp'>雨がひどくて、花見どころじゃない。</span>（Mưa to thế này thì ngắm hoa gì nổi）</div><div class='gd-warn'>Mẹo nhỏ để chọn: «Không chỉ A mà còn B» là ばかりか; «Đâu phải A, ngược hẳn lại» là どころか; «Bây giờ làm gì có thời gian/tâm trạng làm A» là どころじゃない.</div>","n2-2":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「辭書形＋ばかりだ」nghĩa là <b>“chỉ ngày càng ~”, “có tăng không giảm”, “ngày một tệ hơn”</b>. Sự việc cứ đi mãi theo một hướng, không thấy dấu hiệu khá lên hay quay lại. Người nói thường có chút bất lực hoặc lo lắng.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Ngày càng tệ</span>Cách dùng phổ biến nhất. Than về giá cả, kinh tế, sức khỏe, khối lượng công việc... đều rất hay nghe.</div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がるばかりだ。</span>（Giá cả chỉ tăng chứ không giảm）</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなるばかりだった。</span>（Bệnh của bố ngày một nặng hơn）</div><div class='gd-sec'><span class='gd-tag'>Đặt giữa câu</span>Đổi thành「ばかりで」, phía sau nối thêm một chuyện nữa khiến người ta càng bất lực.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は増えるばかりで、給料は全然上がらない。</span>（Công việc chỉ tăng chứ không giảm, vậy mà lương thì chẳng tăng chút nào）</div><div class='gd-sec'><span class='gd-tag'>Thỉnh thoảng dùng cho hướng tốt</span>Có, nhưng ít hơn, và phần lớn là miêu tả xu hướng một cách khách quan.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店の人気は高まるばかりだ。</span>（Quán này ngày càng được yêu thích）</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ dạng từ điển (dạng gốc bạn tra trong từ điển) ＋ばかりだ. Phía trước nhất định phải là <b>động từ chỉ sự thay đổi</b>, như <span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>上がる</span>、<span class='gd-jp'>広がる</span>、<span class='gd-jp'>悪化する</span>.<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えるばかりだ</span></span><br>Tính từ thì phải thêm「なる」để thành “trở nên ~” trước, rồi mới nối ばかりだ:<br><span class='gd-pair'><span class='gd-jp'>悪い</span> → <span class='gd-jp'>悪くなる</span> → <span class='gd-jp'>悪くなるばかりだ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便になる</span> → <span class='gd-jp'>不便になるばかりだ</span></span><br>Khi nói chuyện đã xảy ra trong quá khứ thì dùng <b>ばかりだった</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nếu phía trước không phải động từ chỉ sự thay đổi thì nghĩa sẽ lệch, thành “chỉ cứ ~ mãi”: <span class='gd-jp'>彼女はただ泣くばかりだった。</span>（Cô ấy chỉ biết khóc mãi）Đây không phải nghĩa “ngày càng”.<br>・「<span class='gd-jp'>あとは</span>～ばかりだ」nghĩa là “chỉ còn thiếu ~ nữa thôi”: <span class='gd-jp'>準備はできた。あとは出発するばかりだ。</span>（Chuẩn bị xong hết rồi, chỉ còn xuất phát nữa thôi）<br>・Danh từ＋ばかり nghĩa là “toàn là ~”: <span class='gd-jp'>甘い物ばかり食べている。</span>（Toàn ăn đồ ngọt）Cái này khác hẳn với nghĩa “ngày càng” ở đây.<br>・Không dùng mẫu này để nói về sự tiến bộ của bản thân. Muốn nói “tiếng Nhật ngày càng giỏi” thì nói <span class='gd-jp'>日本語がどんどん上手になっている</span> sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>Cùng là ばかり, nhưng dạng đứng trước khác nhau thì nghĩa hoàn toàn khác:</b></div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりだ。</span>（Tôi vừa mới đến Nhật: dạng た＋ばかり＝vừa mới ~）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日ゲームをしてばかりいる。</span>（Ngày nào cũng chỉ chơi game: dạng て＋ばかりいる＝cứ ~ suốt）</div><div class='gd-ex-line'>・<span class='gd-jp'>帰国してから、日本語は忘れるばかりだ。</span>（Từ khi về nước, tiếng Nhật chỉ càng ngày càng quên: dạng từ điển＋ばかりだ＝ngày càng ~）</div><div class='gd-sec'><b>So với「～つつある」:</b> cả hai đều nói về sự thay đổi, nhưng sắc thái khác nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は回復しつつある。</span>（Kinh tế đang dần phục hồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は悪くなるばかりだ。</span>（Kinh tế chỉ ngày càng tệ đi）</div><div class='gd-sec'>つつある chỉ bình tĩnh miêu tả “sự thay đổi đang diễn ra”, thiên về văn viết, dùng được cho cả việc tốt lẫn xấu; còn ばかりだ nhấn mạnh “không dừng lại được, chỉ đi về một phía”, kèm cảm giác bất lực.<br>Ngoài ra còn có <span class='gd-jp'>～一方だ</span>, nghĩa gần như giống ばかりだ và thường thay thế được cho nhau: <span class='gd-jp'>人口は減る一方だ。</span>（Dân số chỉ giảm chứ không tăng）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nhìn phần đứng trước ばかり — dạng た là “vừa mới ~”, dạng て là “cứ ~ suốt”, còn dạng từ điển cộng động từ chỉ sự thay đổi thì là “ngày càng ~”.</div>","n2-5":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たとたん（に）」nghĩa là <b>“vừa mới ~ thì đột nhiên ~”</b>. Ví dụ bạn vừa mở cửa thì con mèo lao ra; vừa đứng dậy thì thấy chóng mặt. Hành động phía trước vừa làm xong, thì phía sau <b>xảy ra một chuyện bạn không ngờ tới</b>.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Động từ chia sang dạng た (dạng quá khứ「～た」), rồi thêm とたん. Có thể thêm hoặc không thêm「に」, nghĩa như nhau.<br><span class='gd-pair'><span class='gd-jp'>開ける</span> → <span class='gd-jp'>開けたとたん</span></span><span class='gd-pair'><span class='gd-jp'>出る</span> → <span class='gd-jp'>出たとたん</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだとたんに</span></span><br>Phía trước thường là hành động hoàn thành trong chớp mắt, như mở cửa, ra khỏi nhà, đứng dậy, nhìn thấy.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Chuyện đột ngột xảy ra bên ngoài</span>Người khác, động vật, thời tiết bỗng có động tĩnh.</div><div class='gd-ex-line'>・<span class='gd-jp'>家を出たとたん、雨が降り出した。</span>（Vừa ra khỏi nhà thì trời bắt đầu mưa）</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けたとたん、虫が入ってきた。</span>（Vừa mở cửa sổ ra thì côn trùng bay vào）</div><div class='gd-sec'><span class='gd-tag'>Cơ thể, cảm xúc không kiểm soát được</span>Phản ứng xảy ra ngay trên người mình cũng dùng được, miễn là bạn không cố ý làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>立ち上がったとたん、めまいがした。</span>（Vừa đứng dậy thì thấy chóng mặt）</div><div class='gd-ex-line'>・<span class='gd-jp'>母の声を聞いたとたん、涙が出てきた。</span>（Vừa nghe thấy giọng mẹ thì nước mắt trào ra）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước nhất định phải là dạng た: nói <span class='gd-jp'>開けたとたん</span>, không được nói「開けるとたん」.<br>・Phía sau là chuyện <b>đã xảy ra, ngoài dự đoán</b>, nên cuối câu thường là thì quá khứ.<br>・Phía sau không được dùng ý chí, lời rủ rê hay mệnh lệnh như “tôi sẽ ~”, “cùng ~ nhé”, “hãy ~”. 「家に着いたとたん、電話してください」là câu sai.<br>・Phía sau cũng không được là <b>hành động do chính bạn cố ý làm</b>. 「家に帰ったとたん、シャワーを浴びた」nghe không tự nhiên, vì tắm là việc bạn tự quyết định làm. Lúc này hãy đổi thành <span class='gd-jp'>家に帰ってすぐ、シャワーを浴びた。</span>（Vừa về đến nhà là đi tắm ngay）</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>〜次第</b> cũng hay được dịch là “vừa ~ là ~”, nhưng cách dùng thì ngược lại. Hãy xem cùng một tình huống:<br><span class='gd-jp'>駅に着いたとたん、電車が行ってしまった。</span>（Tôi vừa đến ga thì tàu chạy mất）<br>→ Đã xảy ra, không ngờ tới, dùng とたん.<br><span class='gd-jp'>駅に着き次第、連絡します。</span>（Vừa đến ga là tôi sẽ liên lạc với bạn ngay）<br>→ Chưa xảy ra, là việc <b>tôi định làm</b>, dùng 次第.<br>次第 nối với dạng ます bỏ ます (<span class='gd-pair'><span class='gd-jp'>着きます</span> → <span class='gd-jp'>着き次第</span></span>), và thường dùng trong công việc, hoàn cảnh trang trọng.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu phía sau là “chuyện đột nhiên xuất hiện, mình không kiểm soát được” thì dùng とたん; nếu phía sau là “việc mình sẽ làm tiếp theo” thì dùng 次第.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「とたん」cũng có thể đặt ở đầu câu, viết thành「その途端」, nghĩa là “ngay vào khoảnh khắc đó”:<br><span class='gd-jp'>ドアを開けた。その途端、猫が飛び出した。</span>（Tôi mở cửa. Ngay khoảnh khắc đó, con mèo lao ra）</div>","n2-37":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜かねる」giống câu nhân viên chăm sóc khách hàng hay nói: <b>“Phần này chúng tôi xin phép không thể xử lý ạ”</b>, hay cụm <b>“rất tiếc không thể đáp ứng”</b> trong công văn. Nghĩa đen là “muốn làm cũng khó làm”, nhưng thực ra là <b>từ chối rất lịch sự</b>, hoặc cho thấy mình đang khó xử.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Từ chối lịch sự</span>Nhân viên cửa hàng, chăm sóc khách hàng và công ty khi giao tiếp với bên ngoài dùng nhiều nhất. Nó làm câu “không được” nghe mềm hơn hẳn.</div><div class='gd-ex-line'>・<span class='gd-jp'>返品はお受けいたしかねます。</span>（Xin lỗi, chúng tôi không nhận đổi trả hàng）</div><div class='gd-ex-line'>・<span class='gd-jp'>その件についてはお答えしかねます。</span>（Về việc đó, tôi xin phép không thể trả lời）</div><div class='gd-ex-line'>・<span class='gd-jp'>申し訳ございませんが、私ではわかりかねます。</span>（Xin lỗi, phần này tôi không rõ lắm）</div><div class='gd-sec'><span class='gd-tag'>Trong lòng không thể chấp nhận</span>Về lập trường hoặc cảm xúc thì không vượt qua được, không thể gật đầu.</div><div class='gd-ex-line'>・<span class='gd-jp'>その意見には賛成しかねます。</span>（Ý kiến đó tôi không thể tán thành）</div><div class='gd-sec'><span class='gd-tag'>Chưa quyết định được</span><span class='gd-jp'>決めかねる</span>là cách nói cố định rất hay gặp, nghĩa là “phân vân, không quyết định được”.</div><div class='gd-ex-line'>・<span class='gd-jp'>どちらにするか決めかねている。</span>（Vẫn đang phân vân không biết chọn cái nào）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đầu tiên chia động từ về dạng ます, bỏ「ます」đi rồi thêm「かねる」.<br><span class='gd-pair'><span class='gd-jp'>答えます</span> → <span class='gd-jp'>答えかねる</span></span><span class='gd-pair'><span class='gd-jp'>わかります</span> → <span class='gd-jp'>わかりかねる</span></span><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しかねる</span></span><br>Muốn lịch sự hơn nữa thì đổi する thành thể khiêm nhường いたす：<span class='gd-pair'><span class='gd-jp'>いたします</span> → <span class='gd-jp'>いたしかねます</span></span><br>Thực tế bạn sẽ nghe nhiều nhất là dạng lịch sự <b>「〜かねます」</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không dùng khi nói về năng lực, làm không nổi</b>. “Nặng quá không xách nổi” phải nói là <span class='gd-jp'>重くて持てない</span>, không nói được 重くて持ちかねる. かねる dùng cho quy định, lập trường, tâm trạng kiểu “không tiện, không muốn”.<br>・<span class='gd-jp'>わかりかねます</span>nhìn không có phủ định nhưng nghĩa lại là “tôi không rõ”, đừng nghe nhầm thành “tôi biết”.<br>・<b>かねます và かねません có nghĩa trái ngược nhau</b>：<span class='gd-jp'>お答えしかねます</span>là “không thể trả lời”; <span class='gd-jp'>起こりかねません</span>là “rất có thể sẽ xảy ra”. Chỉ khác mỗi chữ ん, đừng lẫn nhé.<br>・Giọng văn rất trang trọng, nói với bạn bè sẽ nghe lạ. Với bạn bè, chỉ cần nói <span class='gd-jp'>ちょっと無理</span> là đủ.<br>・Có hai cách nói quen dùng bạn cần học riêng: <span class='gd-jp'>見るに見かねて手伝った</span>（không đành lòng nhìn nữa nên đã giúp）、<span class='gd-jp'>お待ちかねの新商品</span>（sản phẩm mới mà mọi người mong đợi từ lâu）. Hai cách này không phải là từ chối.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là tình huống khách yêu cầu trả hàng:<br><b>できない</b>＝nói thẳng là không được, hơi cứng: <span class='gd-jp'>返品はできません。</span>（Không thể trả hàng）<br><b>かねる</b>＝từ chối khéo léo, lịch sự: <span class='gd-jp'>返品はお受けいたしかねます。</span>（Rất tiếc chúng tôi không thể nhận trả hàng）<br><b>がたい</b>không dùng để từ chối ai, mà để diễn tả một việc “khiến người ta rất khó ~”: <span class='gd-jp'>信じがたい話だ。</span>（Đúng là chuyện khó tin）<br><b>かねない</b>＝lo rằng việc xấu có thể xảy ra: <span class='gd-jp'>このままでは事故になりかねない。</span>（Cứ thế này rất có thể sẽ xảy ra tai nạn）</div><div class='gd-warn'>Mẹo phán đoán nhanh: lịch sự từ chối yêu cầu của đối phương thì dùng かねる; diễn tả việc khó tin, khó chấp nhận thì dùng がたい; lo “biết đâu sẽ ~” thì dùng かねない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bài tiếp theo là「〜かねない」, hình thức gần như giống hệt nhưng nghĩa lại ngược lại, rất hợp để học cùng nhau.</div>","n2-54":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜につれて」tương đương tiếng Việt <b>“càng ~ thì càng ~”, “cùng với ~ thì dần dần ~”</b>. Việc ở vế trước từ từ thay đổi, việc ở vế sau cũng từ từ thay đổi theo. Giống như “trời càng lạnh, người uống đồ nóng càng đông”, hai việc cùng biến đổi với nhau.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Dạng từ điển (dạng nguyên gốc tra được trong từ điển) thêm につれて trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>時間が経つ</span> → <span class='gd-jp'>時間が経つにつれて</span></span>（theo thời gian trôi qua）<br><span class='gd-pair'><span class='gd-jp'>慣れる</span> → <span class='gd-jp'>慣れるにつれて</span></span>（càng quen dần）</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>Thêm につれて trực tiếp, nhưng bản thân danh từ phải mang nghĩa “biến đổi”, như <span class='gd-jp'>成長</span>、<span class='gd-jp'>進化</span>、<span class='gd-jp'>変化</span>、<span class='gd-jp'>高齢化</span>.<br><span class='gd-pair'><span class='gd-jp'>成長</span> → <span class='gd-jp'>成長につれて</span></span>（cùng với sự trưởng thành）</div><div class='gd-sec'>Trong văn viết cũng hay gặp dạng ngắn hơn「<span class='gd-jp'>につれ</span>」, nghĩa giống nhau.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'>Khi cả hai việc đều <b>thay đổi từng chút một</b>. Vế sau thường đi với「<span class='gd-jp'>〜てきた</span>」「<span class='gd-jp'>〜ていく</span>」「<span class='gd-jp'>〜くなる</span>」để thể hiện cảm giác “dần dần”.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の生活に慣れるにつれて、毎日が楽しくなってきた。</span>（Càng quen với cuộc sống ở Nhật, mỗi ngày càng trở nên vui hơn）</div><div class='gd-ex-line'>・<span class='gd-jp'>年を取るにつれて、体力が落ちてきた。</span>（Tuổi càng cao, thể lực càng yếu đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの成長につれて、家が狭く感じるようになった。</span>（Con càng lớn, tôi càng thấy nhà chật dần）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Việc kết thúc trong tích tắc thì không dùng được</b>. “Tốt nghiệp”, “chuyển nhà”, “kết hôn” chỉ xảy ra một lần, nên không nói được <span class='gd-jp'>卒業するにつれて</span>. Vế trước nhất định phải là sự thay đổi diễn ra từ từ.<br>・<b>Vế sau không được là “tôi sẽ ~” hay “hãy ~”</b>. Vế sau phải là sự thay đổi tự nhiên xảy ra theo, không thể nối với dự định của bản thân hay lời nhờ người khác làm gì. Ví dụ câu “Khi tiếng Nhật tốt lên, chúng mình nói chuyện nhiều hơn nhé” thì không dùng được につれて.<br>・<b>Danh từ không đặt tùy tiện</b>. <span class='gd-jp'>雨につれて</span>không được, vì bản thân “mưa” không phải là một sự biến đổi; phải nói <span class='gd-jp'>雨が強くなるにつれて</span>（mưa càng lúc càng to）.<br>・Tiếng Việt dùng “cùng với”, “theo” rất rộng, nhưng につれて chỉ dùng khi “hai bên cùng thay đổi từ từ, đồng bộ với nhau”. Đừng thấy “cùng với” là áp vào ngay.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>に伴って</b>: nghĩa rất gần, nhưng trang trọng hơn, báo chí và thông báo hay dùng; hơn nữa vế trước có thể là <b>việc chỉ xảy ra một lần</b>.<br>・<span class='gd-jp'>人口が増えるにつれて、ゴミの問題が深刻になった。</span>（Dân số càng tăng, vấn đề rác thải càng nghiêm trọng）<br>・<span class='gd-jp'>人口が増えるに伴って、ゴミの問題が深刻になった。</span>（Như câu trên, giọng trang trọng hơn）<br>Hai câu đều dùng được. Nhưng với việc xảy ra một lần như chuyển nhà:<br>・<span class='gd-jp'>引っ越しに伴って、住所が変わります。</span>（Do chuyển nhà, địa chỉ sẽ thay đổi）<br>Ở đây thì không dùng được につれて.</div><div class='gd-sec'><b>に応じて</b>: “tùy theo ~ mà khác nhau”, trọng tâm là quan hệ tương ứng, không phải thay đổi theo thời gian.<br>・<span class='gd-jp'>年齢に応じて、料金が違います。</span>（Phí khác nhau tùy theo độ tuổi）<br>Câu này là người ở các độ tuổi khác nhau thì giá khác nhau, chứ không phải một người lớn dần lên rồi giá đổi theo, nên không dùng được につれて.</div><div class='gd-warn'>Mẹo phán đoán nhanh: nếu nói được “càng ~ thì dần dần ~” thì dùng につれて; trang trọng hơn, hoặc vế trước là sự việc xảy ra một lần thì dùng に伴って; nếu nghĩa là “tùy theo ~ mà khác nhau” thì dùng に応じて.</div>","n2-26":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ばかりか」「〜ばかりでなく」tương đương với <b>「không chỉ ~ mà còn ~」「không những ~ mà ngay cả ~ cũng」</b> trong tiếng Việt. Bạn nêu một việc trước, rồi <b>cộng thêm</b> một việc nữa lên trên. Trong giao tiếp hằng ngày, người ta hay nói「〜だけじゃなくて」hơn. ばかりか và ばかりでなく nghe trang trọng hơn, hay gặp trong văn viết, báo chí và bài diễn thuyết.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Cộng thêm điều tốt</span>Ưu điểm nối tiếp ưu điểm.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いばかりでなく、味もいい。</span>（Quán này không chỉ rẻ mà vị cũng ngon）</div><div class='gd-ex-line'>・<span class='gd-jp'>その歌は子どもばかりか、大人にも人気がある。</span>（Bài hát đó không chỉ trẻ em mà cả người lớn cũng thích）</div><div class='gd-sec'><span class='gd-tag'>Cộng thêm điều xấu</span>Đã tệ rồi mà còn có chuyện tệ hơn. ばかりか đặc biệt hay dùng trong những lúc kiểu “vậy mà còn ~”, mang chút ngạc nhiên hoặc bất mãn.</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻したばかりか、資料も忘れてきた。</span>（Không những đến muộn mà còn quên mang tài liệu）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は謝らないばかりか、文句まで言ってきた。</span>（Anh ta không những không xin lỗi mà còn quay lại phàn nàn）</div><div class='gd-sec'>Vế sau thường đi với <b>「も」「まで」「さえ」</b>, nghĩa là “đến cả ~ cũng”, nhờ vậy cảm giác “cộng thêm” rõ hơn.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối trực tiếp　<span class='gd-pair'><span class='gd-jp'>遅刻した</span> → <span class='gd-jp'>遅刻したばかりか</span></span><br><b>Tính từ い</b>: nối trực tiếp　<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いばかりか</span></span><br><b>Tính từ な</b>: thêm「な」　<span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利なばかりか</span></span><br><b>Danh từ</b>: nối trực tiếp, không thêm だ　<span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもばかりか</span></span><br>（Trong văn viết trang trọng hơn, tính từ な và danh từ cũng có thể nối bằng「である」, ví dụ <span class='gd-jp'>学生であるばかりでなく</span>）<br>Cách nối của ばかりでなく hoàn toàn giống vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は交通が便利なばかりか、家賃も安い。</span>（Thị trấn này không chỉ giao thông thuận tiện mà tiền thuê nhà cũng rẻ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ không thêm だ: nói <span class='gd-jp'>日本語ばかりか</span>, không nói「日本語だばかりか」; tính từ な thì nhớ thêm な: <span class='gd-jp'>きれいなばかりか</span>.<br>・<b>Sau ばかりか không được dùng câu yêu cầu hay quyết tâm</b> kiểu “hãy ~”, “làm ~ cho tôi”, “tôi sẽ ~”. Lúc này hãy đổi sang ばかりでなく (hoặc だけでなく): <span class='gd-jp'>肉ばかりでなく、野菜も食べなさい。</span>（Đừng chỉ ăn thịt, rau cũng phải ăn nữa）Nói「肉ばかりか、野菜も食べなさい」thì nghe không tự nhiên.<br>・Đừng nhầm với「ばかり」đứng một mình: <span class='gd-jp'>日本語ばかり勉強している</span> nghĩa là “<b>chỉ</b> học tiếng Nhật”, còn <span class='gd-jp'>日本語ばかりか英語も勉強している</span> nghĩa là “<b>không chỉ</b> tiếng Nhật mà còn học cả tiếng Anh”. Thêm một chữ か là nghĩa khác hẳn đấy.</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'><b>どころか</b> cũng hay được dịch là “không những ~”, nhưng cách dùng khác. Mấu chốt là <b>việc ở vế trước có thành lập hay không</b>.<br><b>ばかりか</b>: vế trước đúng, vế sau cộng thêm.<br><span class='gd-jp'>彼は英語ばかりか、フランス語も話せる。</span>（Anh ấy không chỉ nói được tiếng Anh mà cả tiếng Pháp: tiếng Anh thì nói được）<br><b>どころか</b>: việc ở vế trước còn chưa tới nơi, thậm chí còn kém xa.<br><span class='gd-jp'>彼はフランス語どころか、英語も話せない。</span>（Tiếng Pháp thì khỏi nói, đến tiếng Anh anh ấy cũng không nói được: tiếng Pháp thì không nói được）<br><span class='gd-jp'>やせるどころか、太ってしまった。</span>（Không những không gầy đi mà còn béo ra）</div><div class='gd-sec'><b>のみならず</b> có nghĩa gần giống ばかりか và ばかりでなく, chỉ là mang tính văn viết, cứng hơn, thường xuất hiện trong bài viết hoặc dịp trang trọng.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: việc ở vế trước “có thật”, rồi cộng thêm một việc nữa thì dùng ばかりか, ばかりでなく; việc ở vế trước “hoàn toàn không có”, hoặc kết quả ngược hẳn thì dùng どころか. Nếu vế sau là bảo người khác làm gì thì chọn ばかりでなく.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cùng họ “không chỉ ~” còn có <span class='gd-jp'>〜のみならず</span>, <span class='gd-jp'>〜はもちろん</span>, <span class='gd-jp'>〜上に</span>, <span class='gd-jp'>〜に限らず</span>. Bạn học tiếp để so sánh sắc thái riêng của từng mẫu nhé.</div>","n2-35":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ざるを得ない」nghĩa là <b>「buộc phải ~」「đành phải ~」</b>. Trong lòng bạn thực ra không muốn lắm, nhưng hoàn cảnh đã vậy, <b>không còn lựa chọn nào khác</b>, chỉ có thể làm thế. Giống cảm giác khi bạn nói “hết cách rồi, đành cắn răng đi vậy”.</div><div class='gd-sec'>Tách ra thì dễ nhớ hơn: <span class='gd-jp'>ざる</span> là dạng phủ định “không” của cổ văn, <span class='gd-jp'>得ない</span> là “không thể”, ghép lại thành “<b>không thể không làm</b>”, tức là “buộc phải”. <span class='gd-jp'>得ない</span> đọc là <b>えない</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Bị hoàn cảnh ép</span>Vì một lý do nào đó mà bị buộc phải làm điều mình không muốn lắm.</div><div class='gd-ex-line'>・<span class='gd-jp'>台風が来るので、旅行を中止せざるを得ない。</span>（Vì bão sắp đến nên đành phải hủy chuyến du lịch）</div><div class='gd-ex-line'>・<span class='gd-jp'>人が足りないので、休みの日も出勤せざるを得なかった。</span>（Thiếu người nên ngày nghỉ cũng đành phải đi làm）</div><div class='gd-sec'><span class='gd-tag'>Buộc phải thừa nhận・buộc phải nói</span>Hay đi cùng <span class='gd-jp'>認める</span>, <span class='gd-jp'>言う</span>, nghĩa là “dù không muốn nhưng sự thật là như vậy”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の実力は認めざるを得ない。</span>（Tôi buộc phải thừa nhận thực lực của anh ấy）</div><div class='gd-ex-line'>・<span class='gd-jp'>残念ながら、この計画は失敗だったと言わざるを得ない。</span>（Rất tiếc, phải nói rằng kế hoạch này đã thất bại）</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào trước</div><div class='gd-sec'>Cách làm: chia sang thể ない trước, rồi <b>bỏ ない đi</b>, sau đó thêm ざるを得ない.</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>:<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span> → bỏ ない → <span class='gd-jp'>行かざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>従う</span> → <span class='gd-jp'>従わない</span> → <span class='gd-jp'>従わざるを得ない</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>:<br><span class='gd-pair'><span class='gd-jp'>認める</span> → <span class='gd-jp'>認めない</span> → <span class='gd-jp'>認めざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>諦める</span> → <span class='gd-jp'>諦めざるを得ない</span></span></div><div class='gd-sec'><b>Nhóm 3 (hai động từ đều là ngoại lệ, cứ học thuộc)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せざるを得ない</span></span>（không phải しざる）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ざるを得ない</span>（こざるをえない）</span></div><div class='gd-sec'>Thì quá khứ là <span class='gd-jp'>得なかった</span>, còn nói lịch sự hơn thì dùng <span class='gd-jp'>得ません</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>する</span> phải đổi thành <b>せざる</b>, viết「しざるを得ない」là sai. Kiểu “danh từ＋する” như <span class='gd-jp'>中止する</span>, <span class='gd-jp'>出勤する</span> cũng vậy, thành <span class='gd-jp'>中止せざるを得ない</span>.<br>・Động từ đuôi う như <span class='gd-jp'>言う</span>, <span class='gd-jp'>従う</span> có thể ない là <b>わ</b>: <span class='gd-jp'>言わない</span>, nên là <span class='gd-jp'>言わざる</span>, không phải「言あざる」.<br>・<span class='gd-jp'>得ない</span> đọc là <b>えない</b>, đừng đọc thành とくない hay うない.<br>・Đây là cách nói thiên về trang trọng, văn viết, thường gặp trong báo chí, báo cáo, dịp chính thức. Khi trò chuyện với bạn bè mà muốn nói “đành phải”, thường sẽ tự nhiên hơn nếu dùng kiểu <span class='gd-jp'>行くしかない</span>.<br>・Mẫu này mang sắc thái “thực ra không muốn”, nên đừng dùng cho việc bạn rất muốn làm.</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'><b>なければならない</b> = theo quy định, theo lẽ thường thì <b>phải làm</b>, không nhất thiết có cảm xúc:<br><span class='gd-jp'>明日は会議だから、早く行かなければならない。</span>（Ngày mai có họp nên phải đi sớm）<br><b>ざるを得ない</b> = vốn không muốn, nhưng <b>bị hoàn cảnh ép đến mức không còn lựa chọn</b>:<br><span class='gd-jp'>熱があるが、代わりの人がいないので、行かざるを得ない。</span>（Tuy bị sốt nhưng không có ai làm thay nên đành phải đi）</div><div class='gd-sec'><b>ずにはいられない</b> (trông rất giống, đều có ず/ざる) = trong lòng <b>không kìm được</b>, cảm xúc tự trào ra:<br><span class='gd-jp'>部長の冗談がおもしろくて、笑わずにはいられなかった。</span>（Câu đùa của trưởng phòng buồn cười quá, tôi không nhịn được cười）<br><span class='gd-jp'>部長の冗談はつまらなかったが、笑わざるを得なかった。</span>（Câu đùa của trưởng phòng nhạt nhẽo, nhưng tôi đành phải cười theo cho phải phép）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: chỉ đơn thuần “phải làm” thì dùng なければならない; “không muốn nhưng không có lựa chọn” thì dùng ざるを得ない; “không nhịn được” thì dùng ずにはいられない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu này thường đi với “đã ~ thì ~”: <span class='gd-jp'>上司の判断である以上、従わざるを得ない。</span>（Đã là phán đoán của cấp trên thì đành phải tuân theo）. Bạn có thể học tiếp các cách nói kiểu “đã ~ thì ~” như <span class='gd-jp'>〜上は</span>, <span class='gd-jp'>〜からには</span>.</div>","n2-6":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜次第」nghĩa là <b>「đợi ～ xong là lập tức ～」</b>. Giống kiểu bên chăm sóc khách hàng hay nói: \"hàng vừa đến sẽ báo ngay cho quý khách\", \"có kết quả sẽ báo ngay cho quý khách\". Đây là kiểu \"vừa ～ là ～\" <b>trang trọng, hơi mang hơi hướng công việc</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: đổi sang thể ます, bỏ ます rồi ghép thẳng với 次第.<br><span class='gd-pair'><span class='gd-jp'>届きます</span> → bỏ ます → <span class='gd-jp'>届き次第</span></span><br><span class='gd-pair'><span class='gd-jp'>終わります</span> → <span class='gd-jp'>終わり次第</span></span><span class='gd-pair'><span class='gd-jp'>わかります</span> → <span class='gd-jp'>わかり次第</span></span><span class='gd-pair'><span class='gd-jp'>見つけます</span> → <span class='gd-jp'>見つけ次第</span></span></div><div class='gd-sec'><b>Danh từ chỉ hành động có thể thêm する</b> (như <span class='gd-jp'>到着する</span>, <span class='gd-jp'>決定する</span>): thường bỏ する, rồi ghép danh từ thẳng với 次第.<br><span class='gd-pair'><span class='gd-jp'>到着する</span> → <span class='gd-jp'>到着次第</span></span><span class='gd-pair'><span class='gd-jp'>決定する</span> → <span class='gd-jp'>決定次第</span></span><br>(Bạn cũng sẽ gặp <span class='gd-jp'>到着し次第</span>, nghĩa y hệt.)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Tôi sẽ làm ngay</span>Vế trước là việc chưa xảy ra nhưng đang chờ nó xảy ra, vế sau là việc người nói định làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物が届き次第、ご連絡いたします。</span>(Bưu kiện vừa đến là tôi sẽ liên lạc với quý khách ngay)</div><div class='gd-ex-line'>・<span class='gd-jp'>詳しいことがわかり次第、お知らせします。</span>(Có thông tin chi tiết là tôi sẽ báo cho bạn ngay)</div><div class='gd-sec'><span class='gd-tag'>Nhờ đối phương làm ngay</span>Vế sau cũng có thể là yêu cầu hoặc chỉ thị.</div><div class='gd-ex-line'>・<span class='gd-jp'>到着次第、お電話ください。</span>(Đến nơi là gọi điện cho tôi nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>準備ができ次第、始めてください。</span>(Chuẩn bị xong là bắt đầu nhé)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không dùng cho việc đã xảy ra</b>: câu \"vừa đến ga thì trời mưa\" không dùng được 次第. Sau 次第 là việc \"sắp làm\", không bao giờ ở thì quá khứ.<br>・Vế sau phải là việc <b>bản thân có thể quyết định làm</b> (liên lạc, xuất phát, nhờ người khác làm), không đi với kết quả ngoài tầm kiểm soát như \"trời mưa mất\" hay \"giật mình\".<br>・Không ghép với thể từ điển: đúng là <span class='gd-jp'>届き次第</span>, không phải 届く次第.<br>・Giọng văn rất trang trọng, nói với bạn bè sẽ nghe hơi cứng. Với bạn bè, bạn chỉ cần nói <span class='gd-jp'>着いたらすぐ連絡するね</span> (đến nơi là mình báo cậu ngay nhé) là đủ.</div><div class='gd-h'>Một nghĩa khác: tùy thuộc vào ～</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋次第だ／次第で</span>「次第」còn một cách dùng phổ biến nữa, nghĩa là \"tùy vào ～\", \"phụ thuộc vào ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>成功するかどうかは、君の努力次第だ。</span>(Thành công hay không là tùy vào nỗ lực của cậu)</div><div class='gd-ex-line'>・<span class='gd-jp'>天気次第で、予定が変わるかもしれません。</span>(Tùy vào thời tiết, kế hoạch có thể thay đổi)</div><div class='gd-sec'>Cách dùng này khác hẳn nghĩa \"vừa ～ là ～\" ở trên. Nếu phía trước là <b>danh từ thông thường</b> (nỗ lực, thời tiết, tiền bạc...), thường dùng <b>次第だ／次第で</b> với nghĩa \"tùy thuộc vào\". Còn nếu là <b>danh từ hành động có thể thêm する</b> như <span class='gd-jp'>到着</span>, <span class='gd-jp'>決定</span>, và phía sau nói việc sẽ làm, thì đó là nghĩa \"vừa ～ là ～\".</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>Cùng là \"vừa về đến nhà là ～\":<br><b>次第</b> = chưa xảy ra, <b>đến lúc đó tôi sẽ làm ngay</b>: <span class='gd-jp'>家に着き次第、電話します。</span>(Tôi về đến nhà là gọi cho bạn ngay)<br><b>たとたん</b> = đã xảy ra, <b>ngay khoảnh khắc đó thì bất ngờ có chuyện không ngờ</b>: <span class='gd-jp'>家に着いたとたん、雨が降り出した。</span>(Vừa về đến nhà thì trời đột nhiên đổ mưa)</div><div class='gd-warn'>Mẹo nhỏ: \"chưa xảy ra, đợi xong là tôi làm ngay\" thì dùng 次第; \"đã xảy ra, ngay khoảnh khắc đó có chuyện bất ngờ\" thì dùng たとたん.</div>","n2-11":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ものの」nghĩa là <b>「～ thì ～ rồi, nhưng…」</b>. Ví dụ \"vé thì mua rồi, nhưng cuối cùng không đi được\": việc phía trước là thật và bạn thừa nhận, nhưng diễn biến phía sau lại khác với điều bạn nghĩ, thường mang cảm giác \"haizz, rốt cuộc không làm được\".</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm rồi nhưng không đi đến đâu</span>Cách dùng phổ biến nhất. Vế trước đã làm một việc, nhưng vế sau lại không diễn ra như mong đợi.</div><div class='gd-ex-line'>・<span class='gd-jp'>チケットを買ったものの、結局行けなかった。</span>(Vé thì mua rồi, nhưng cuối cùng vẫn không đi được)</div><div class='gd-ex-line'>・<span class='gd-jp'>ジムに入会したものの、忙しくて一度しか行っていない。</span>(Phòng gym thì đăng ký rồi, nhưng bận quá nên chỉ đi đúng một lần)</div><div class='gd-ex-line'>・<span class='gd-jp'>やると言ったものの、正直自信がない。</span>(Nói là sẽ làm thì có nói, nhưng thật lòng thì tôi không tự tin lắm)</div><div class='gd-sec'><span class='gd-tag'>Hai vế chênh nhau</span>Đặc điểm ở vế trước khiến người ta nghĩ đến một kết quả nào đó, nhưng vế sau lại không như vậy. Vế sau không nhất thiết là chuyện xấu.</div><div class='gd-ex-line'>・<span class='gd-jp'>このアパートは駅から遠いものの、家賃が安い。</span>(Căn hộ này tuy xa ga thật, nhưng tiền thuê rẻ)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ, tính từ い</b>: ghép thẳng.<br><span class='gd-pair'><span class='gd-jp'>買った</span> → <span class='gd-jp'>買ったものの</span></span><span class='gd-pair'><span class='gd-jp'>遠い</span> → <span class='gd-jp'>遠いものの</span></span><br><b>Tính từ な</b>: đổi「だ」thành「な」, hoặc đổi thành「である」.<br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単なものの</span></span><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単であるものの</span></span><br><b>Danh từ</b>: đổi「だ」thành「である」.<br><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生であるものの</span></span></div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>とはいうものの</span>\"Tuy nói vậy, nhưng…\". Có thể nối sau câu hoặc đứng riêng ở đầu câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に十年住んでいるとはいうものの、敬語はまだ苦手だ。</span>(Tuy nói là đã sống ở Nhật mười năm, kính ngữ tôi vẫn còn yếu)</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエット中だ。とはいうものの、甘いものはやめられない。</span>(Mình đang ăn kiêng. Nói vậy chứ đồ ngọt thì vẫn không bỏ được)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な không ghép thẳng với「だ」: không phải <span class='gd-jp'>静かだものの</span> mà là <span class='gd-jp'>静かなものの</span>; danh từ thì dùng <span class='gd-jp'>学生であるものの</span>.<br>・Vế sau <b>không dùng với ý định của bản thân, mệnh lệnh, yêu cầu</b>. Không nói được <span class='gd-jp'>高いものの、買おう</span> hay <span class='gd-jp'>高いものの、買ってください</span>, lúc này dùng「けど」: <span class='gd-jp'>高いけど、買おう</span>.<br>・Vế trước phải là việc <b>đã là sự thật</b>. Việc chưa xảy ra hoặc chỉ là giả định thì không dùng được.<br>・Giọng văn thiên về trang trọng, hay gặp trong văn viết, báo chí, hoàn cảnh trang trọng. Khi trò chuyện với bạn bè, nói <span class='gd-jp'>買ったけど、行けなかった</span> sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>ものの</b> = \"～ thì ～ rồi, nhưng…\", trọng tâm là <b>thừa nhận vế trước, nhưng kết quả lại chênh lệch</b>, thường mang chút tiếc nuối:<br><span class='gd-jp'>チケットを買ったものの、行けなかった。</span>(Vé thì mua rồi, nhưng không đi được)<br><b>にもかかわらず</b> = \"rõ ràng ～ vậy mà ～\", trọng tâm là <b>hai vế đối lập mạnh</b>, thường mang sự ngạc nhiên hoặc bất mãn, hay dùng để nói về người khác:<br><span class='gd-jp'>チケットを買ったにもかかわらず、彼は来なかった。</span>(Rõ ràng đã mua vé rồi, vậy mà anh ấy lại không đến)<br><b>ものなら</b> chỉ trông giống thôi, nghĩa hoàn toàn khác, là \"nếu có thể ～ thì\":<br><span class='gd-jp'>行けるものなら、行きたかった。</span>(Nếu đi được thì tôi rất muốn đi)</div><div class='gd-warn'>Mẹo nhỏ: muốn nói \"～ thì ～ rồi, nhưng…\" thì dùng ものの; muốn nói \"rõ ràng ～ vậy mà ～\" thì dùng にもかかわらず; thấy nghĩa \"nếu có thể ～\" thì là ものなら, không phải mẫu đối lập \"tuy nhiên\".</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Những mẫu có nghĩa gần giống, cũng là \"tuy ～\" còn có <span class='gd-jp'>とはいえ</span>, <span class='gd-jp'>つつも</span>, <span class='gd-jp'>ながらも</span>, bạn có thể đặt cạnh nhau để so sánh.</div>","n2-15":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にしても」nghĩa là <b>“cho dù ~ thì cũng ~”</b>. Bạn lùi một bước và thừa nhận lý do của đối phương (ừ, cho dù bạn bận), nhưng kết luận vẫn không đổi (ít nhất cũng phải báo một tiếng chứ). Cấu trúc này hay mang giọng phàn nàn hoặc chê trách kiểu “như vậy vẫn là không ổn”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối thẳng với thể thường.<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいにしても</span></span><span class='gd-pair'><span class='gd-jp'>知らなかった</span> → <span class='gd-jp'>知らなかったにしても</span></span><br><b>Danh từ, tính từ な</b>: ở thì hiện tại <b>không thêm だ</b>, nối thẳng; thì quá khứ dùng だった.<br><span class='gd-pair'><span class='gd-jp'>冗談</span> → <span class='gd-jp'>冗談にしても</span></span><span class='gd-pair'><span class='gd-jp'>大変</span> → <span class='gd-jp'>大変にしても</span></span><span class='gd-pair'><span class='gd-jp'>冗談だった</span> → <span class='gd-jp'>冗談だったにしても</span></span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Cho dù ~ cũng</span>Nhường một bước, rồi phần sau nói ý kiến hoặc sự không hài lòng của mình. Phía trước hay thêm「いくら」(dù có … đến đâu).</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら忙しいにしても、返事ぐらいはしてほしい。</span>(Dù có bận đến đâu, ít nhất cũng hãy trả lời một tiếng chứ)</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にしても、言っていいことと悪いことがある。</span>(Cho dù là đùa thì cũng có điều nên nói và điều không nên nói)</div><div class='gd-sec'><span class='gd-tag'>Bất kể ~ đều</span>Phía trước đặt các từ nghi vấn như「何、どこ、誰」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何をするにしても、健康が一番だ。</span>(Bất kể làm gì thì sức khỏe vẫn là quan trọng nhất)</div><div class='gd-sec'><span class='gd-tag'>AにしてもBにしても</span>Dù là A hay B thì kết quả đều như nhau. A và B thường là hai thứ cùng loại, hoặc hai lựa chọn trái ngược nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにしても行かないにしても、早めに連絡してください。</span>(Dù đi hay không đi, bạn cũng hãy báo cho mình sớm một chút nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>電車にしてもバスにしても、朝は混む。</span>(Dù là tàu điện hay xe buýt, buổi sáng đều đông)</div><div class='gd-sec'><span class='gd-tag'>それにしても</span>Đã thành một cụm cố định, nghĩa là “dù vậy đi nữa” hoặc “mà nói đi cũng phải nói lại”, rất hay dùng khi trò chuyện.</div><div class='gd-ex-line'>・<span class='gd-jp'>「バスが遅れたんだって。」「それにしても遅すぎるよ。」</span>(“Nghe nói xe buýt bị trễ.” “Dù vậy thì cũng trễ quá rồi đấy.”)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ không thêm だ: nói <span class='gd-jp'>冗談にしても</span>, không nói được「冗談だにしても」.<br>・Vế sau thường là <b>quan điểm của bạn</b>: chê trách, bất mãn, đề nghị, phán đoán, hay đi với「はずだ」「べきだ」「〜てほしい」「〜ない」.<br>・Trong tiếng Việt, “cho dù” có thể rất trung tính, nhưng「にしても」thường mang sắc thái “mình hiểu, nhưng vẫn không được”. Nói thẳng với người lớn tuổi hoặc cấp trên thì nghe có thể như đang trách móc.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>にしては</b> = “xét theo ~ mà lại ~”, kết quả <b>khác với dự đoán</b>:<br><span class='gd-jp'>初めてにしては上手だね。</span>(Xét là lần đầu thì giỏi đấy nhỉ)<br><b>にしても</b> = “cho dù là ~ thì cũng ~”, lý do đó <b>không thể dùng làm cớ</b>:<br><span class='gd-jp'>初めてにしても、これはひどすぎる。</span>(Cho dù là lần đầu thì cái này cũng tệ quá)</div><div class='gd-sec'><b>にしろ・にせよ</b>: ý nghĩa và cách dùng gần như giống にしても, chỉ trang trọng hơn. <b>にしても</b> mang tính khẩu ngữ nhất, còn <b>にせよ</b> thiên về văn viết và hoàn cảnh trang trọng.<br><span class='gd-jp'>いずれにしても、明日また連絡します。</span>／<span class='gd-jp'>いずれにせよ、明日また連絡します。</span>(Dù thế nào đi nữa, ngày mai mình sẽ liên lạc lại)</div><div class='gd-warn'>Mẹo phân biệt: muốn nói “cho dù ~ cũng” thì dùng にしても; muốn nói “xét theo ~ mà lại” thì dùng にしては. Chỉ khác một chữ mà nghĩa khác hẳn.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cách nói đồng nghĩa trang trọng hơn: <span class='gd-jp'>〜にしろ・〜にせよ</span>.</div>","n2-18":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ものなら」có hai nghĩa, chỉ cần <b>nhìn động từ phía trước ở thể nào</b> là phân biệt được:<br>・Phía trước là <b>thể khả năng</b> (<span class='gd-jp'>行ける</span>、<span class='gd-jp'>戻れる</span>): “<b>giá mà có thể ~ thì tốt biết mấy</b> (nhưng rất khó)”. Giống như bạn thở dài nói “giá mà làm lại được một lần nữa”.<br>・Phía trước là <b>thể ý chí</b> (〜よう、〜おう): “<b>lỡ mà ~ thì coi như xong</b>”. Giống như khi bạn cảnh cáo ai đó: “Thử đến muộn một phút xem!”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Cách dùng ①: thể khả năng + ものなら</b> (thể khả năng là dạng “có thể ~”)<br><span class='gd-pair'><span class='gd-jp'>戻る</span> → <span class='gd-jp'>戻れるものなら</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられるものなら</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できるものなら</span></span></div><div class='gd-sec'><b>Cách dùng ②: thể ý chí + ものなら</b> (thể ý chí là dạng「〜よう／〜おう」, nên bạn hay gặp「〜ようものなら」)<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言おうものなら</span></span><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れようものなら</span></span><span class='gd-pair'><span class='gd-jp'>失敗する</span> → <span class='gd-jp'>失敗しようものなら</span></span></div><div class='gd-sec'>Trong khẩu ngữ, ものなら thường được nói thành <b>もんなら</b>: <span class='gd-jp'>戻れるもんなら戻りたいよ。</span>(Nếu quay lại được thì mình cũng muốn quay lại lắm)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Mong ước kèm tiếng thở dài</span>Cách dùng ①. Trong lòng bạn biết là rất khó, gần như không thể, nhưng vẫn không nhịn được mà nói “giá mà có thể thì…”. Phía sau thường là những mong muốn như「〜たい」「〜てあげたい」.</div><div class='gd-ex-line'>・<span class='gd-jp'>戻れるものなら、高校時代に戻りたい。</span>(Nếu quay lại được, mình muốn quay về thời cấp ba)</div><div class='gd-ex-line'>・<span class='gd-jp'>代われるものなら、代わってあげたい。</span>(Giá mà có thể thay bạn được, mình muốn gánh thay bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>休めるものなら、一週間ぐらい休みたい。</span>(Nếu được nghỉ thì mình muốn nghỉ khoảng một tuần)</div><div class='gd-sec'><span class='gd-tag'>Thách thức</span>Cũng là cách dùng ①, nhưng phía sau là thể mệnh lệnh「〜てみろ」. Nghĩa là “làm được thì làm thử xem”, bạn cho rằng đối phương không làm nổi nên cố tình khiêu khích.</div><div class='gd-ex-line'>・<span class='gd-jp'>やれるものなら、やってみろ。</span>(Có giỏi thì làm thử xem)</div><div class='gd-sec'><span class='gd-tag'>Cảnh cáo</span>Cách dùng ②. Nghĩa là “hễ làm ~ là sẽ rất thảm”, hay đi với「<span class='gd-jp'>少しでも</span>」「<span class='gd-jp'>一度でも</span>」「<span class='gd-jp'>一分でも</span>」để nhấn mạnh một cách phóng đại hậu quả đáng sợ thế nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの父は、門限を一分でも過ぎようものなら、すごく怒る。</span>(Bố mình ấy à, hễ về quá giờ giới nghiêm dù chỉ một phút là nổi giận đùng đùng)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長の前でそんなことを言おうものなら、大変なことになるよ。</span>(Lỡ mà nói câu đó trước mặt trưởng phòng thì to chuyện đấy)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cách dùng ① phía trước nhất định phải dùng <b>thể khả năng</b>: phải nói <span class='gd-jp'>行けるものなら</span>, không nói 行くものなら.<br>・Cách dùng ② phía trước phải dùng <b>thể ý chí</b>: <span class='gd-jp'>言おうものなら</span>、<span class='gd-jp'>遅れようものなら</span>. Đừng trộn lẫn hai cách nối.<br>・Cách dùng ① mang cảm giác “rất khó làm được”. Nếu việc đó thực ra dễ làm, dùng nó sẽ nghe rất lạ, dùng「〜たら」thông thường là đủ.<br>・Sau cách dùng ① thường là mong muốn (〜たい) hoặc mệnh lệnh (〜てみろ), ít khi đi với câu kể thông thường.<br>・「<span class='gd-jp'>やれるものならやってみろ</span>」là câu thách thức, nói với người lớn tuổi hay cấp trên thì chắc chắn sẽ cãi nhau.<br>・Cả hai cách dùng đều có thể dịch sang tiếng Việt là “nếu ~ thì”, nhưng nghĩa khác nhau rất nhiều: thể khả năng là “rất muốn, nhưng không làm được”, còn thể ý chí là “tuyệt đối đừng làm”.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng là “muốn đi”, nhưng nói bằng <b>〜たら</b> và <b>〜ものなら</b> thì mức độ chắc chắn trong lòng bạn không giống nhau:<br><b>〜たら</b> = giả định đơn thuần, thật sự có cơ hội xảy ra: <span class='gd-jp'>時間があったら、行きたい。</span>(Nếu có thời gian thì mình muốn đi)<br><b>〜ものなら</b> = chính bạn thấy gần như không thể, chỉ nói vậy thôi: <span class='gd-jp'>行けるものなら、行きたい。</span>(Giá mà đi được thì tốt… nhưng chắc là không đi được)</div><div class='gd-warn'>Mẹo phân biệt: thấy “có cơ hội” thì dùng たら; thấy “gần như không còn hy vọng, chỉ nói cho vui” thì dùng thể khả năng + ものなら; muốn cảnh cáo người khác “dám làm là xong đời” thì dùng 〜ようものなら.</div>","n2-19":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ないことには」 nghĩa là <b>“nếu không ~ trước thì hoàn toàn không thể ~”</b>. Việc đứng trước là một <b>ngưỡng cửa</b>: chưa bước qua thì phần sau khỏi bàn. Cảm giác giống mấy câu người Việt hay nói như “chưa ăn thử sao biết ngon hay dở”, “sếp chưa gật đầu thì chẳng làm được gì”.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Chưa thử thì không biết</span>Cách dùng phổ biến nhất, phía trước gần như luôn đi với 「〜てみない」 (không thử xem).</div><div class='gd-ex-line'>・<span class='gd-jp'>食べてみないことには、おいしいかどうかわからない。</span>(Chưa ăn thử thì không biết có ngon hay không)</div><div class='gd-ex-line'>・<span class='gd-jp'>やってみないことには、何とも言えません。</span>(Chưa làm thử thật thì tôi cũng khó nói lắm)</div><div class='gd-sec'><span class='gd-tag'>Điều kiện tiên quyết</span>Việc nào đó chưa hoàn thành thì phần sau không thể tiến hành.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長がOKしないことには、この企画は進められない。</span>(Trưởng phòng chưa gật đầu thì kế hoạch này không thể triển khai)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Động từ thể ない, rồi thêm thẳng 「ことには」. Ôn lại cách chia thể ない trước nhé:<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối thành âm hàng 「あ」 cùng hàng, rồi thêm ない.<span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành か → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span>(う phải đổi thành わ)<br><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」, thêm ない.<span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ない</span></span><br><b>Nhóm 3</b>:<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span><br>Ghép lại:<span class='gd-pair'><span class='gd-jp'>確認しない</span> → <span class='gd-jp'>確認しないことには</span></span></div><div class='gd-sec'>Vài cách nói hay đi với vế sau, bạn nhớ luôn cả cụm cho tiện:<span class='gd-jp'>わからない</span>、<span class='gd-jp'>何とも言えない</span>、<span class='gd-jp'>始まらない</span>、<span class='gd-jp'>決められない</span>、<span class='gd-jp'>話にならない</span>。</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau phải là kết quả kiểu <b>“không thể, không biết, không thành”</b>. Không đi với kết quả tích cực: <span class='gd-jp'>勉強しないことには、合格できる</span> là sai.<br>・Vế sau cũng không đi với câu mệnh lệnh, nhờ vả, rủ rê: <span class='gd-jp'>確認しないことには、電話してください</span> nghe không tự nhiên.<br>・Đừng nhầm với 「<span class='gd-jp'>〜ないことはない</span>」, nghĩa là “không phải là không ~”: <span class='gd-jp'>行けないことはない</span> (không phải là không đi được). Chỉ khác một chữ mà nghĩa hoàn toàn khác.<br>・Sắc thái khá trang trọng, hay gặp trong công việc và văn viết. Khi trò chuyện với bạn bè, người ta thường nói 「<span class='gd-jp'>やってみないとわからない</span>」.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>ないことには</b> = việc chưa xảy ra, nhấn mạnh <b>“không làm trước thì khỏi bàn”</b>, vế sau chỉ đi với ý tiêu cực:<br><span class='gd-jp'>住んでみないことには、その町のよさはわからない。</span>(Chưa từng sống thật ở đó thì sẽ không biết cái hay của thành phố ấy)<br><b>てはじめて</b> = việc đã làm rồi, “làm xong thì lần đầu tiên” mới cảm nhận được, vế sau là nội dung kiểu “mới nhận ra, mới hiểu” (tốt hay xấu đều được):<br><span class='gd-jp'>住んでみてはじめて、その町のよさがわかった。</span>(Sống thật ở đó rồi mới biết cái hay của thành phố ấy)<br><b>ないと／なければ</b> = cách nói “nếu không ~” thông dụng nhất, vế sau ít bị giới hạn hơn, có thể là cảnh báo, kết quả, phán đoán… (nhưng sau 「<span class='gd-jp'>〜ないと</span>」 không dùng câu ý chí hay nhờ vả như 「～ましょう」「～てください」):<br><span class='gd-jp'>予約しないと、入れないよ。</span>(Không đặt trước thì sẽ không vào được đâu nhé)<br>Đổi thành 「<span class='gd-jp'>予約しないことには、入れない</span>」 cũng được, nhưng giọng cứng hơn, như đang nhấn mạnh “đặt trước là ngưỡng cửa tuyệt đối”.</div><div class='gd-warn'>Mẹo chọn nhanh: muốn nói “chưa làm thì khỏi bàn” dùng ないことには; “làm rồi mới biết” dùng てはじめて; chỉ là “nếu không ~” bình thường thì dùng ないと／なければ là đủ.</div>","n2-29":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にすぎない」 nghĩa là <b>“chỉ là ~ thôi”, “cùng lắm cũng chỉ là ~”</b>. Người nói cố ý <b>nói nhỏ sự việc đi</b>, ý là “chỉ có thế thôi, không có gì to tát”.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Danh từ</b>: ghép thẳng, ở giữa không thêm だ.<br><span class='gd-pair'><span class='gd-jp'>噂</span> → <span class='gd-jp'>噂にすぎない</span></span>(chỉ là tin đồn)<br><b>Động từ</b>: dùng thể thường (thể từ điển, thể た).<br><span class='gd-pair'><span class='gd-jp'>従った</span> → <span class='gd-jp'>従ったにすぎない</span></span>(chỉ là làm theo lệnh)<br>Muốn nói quá khứ thì đổi thành <b>にすぎなかった</b>, muốn lịch sự hơn thì nói <b>にすぎません</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói nhẹ sự việc</span>Nhấn mạnh “chỉ có vậy thôi, đừng nghĩ nhiều”.</div><div class='gd-ex-line'>・<span class='gd-jp'>それはただの噂にすぎない。</span>(Đó chẳng qua chỉ là tin đồn thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は命令に従ったにすぎない。</span>(Anh ấy chỉ làm theo lệnh mà thôi)</div><div class='gd-sec'><span class='gd-tag'>Số lượng ít</span>Hay đi cùng 「わずか」 (vỏn vẹn), nhấn mạnh con số nhỏ.</div><div class='gd-ex-line'>・<span class='gd-jp'>参加者はわずか5人にすぎなかった。</span>(Người tham gia chỉ vỏn vẹn 5 người)</div><div class='gd-sec'><span class='gd-tag'>Khiêm tốn khi được khen</span>Dùng để nói về bản thân thì thành “tôi có làm gì đặc biệt đâu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は当たり前のことをしたにすぎません。</span>(Tôi chỉ làm điều đáng làm thôi ạ)</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'>Phía trước thường thêm <span class='gd-jp'>ただの</span>、<span class='gd-jp'>単なる</span> (đơn thuần)、<span class='gd-jp'>ほんの</span> (chỉ một chút)、<span class='gd-jp'>わずか</span> để tăng thêm cảm giác “chỉ là”.<br>Khi câu chưa kết thúc mà muốn nối tiếp, sẽ viết thành <b>にすぎず</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>これは一つの例にすぎず、問題はほかにもたくさんある。</span>(Đây chỉ là một ví dụ, còn nhiều vấn đề khác nữa)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ <b>đừng thêm だ</b>: viết <span class='gd-jp'>噂にすぎない</span>, không phải 「噂だにすぎない」.<br>・Mẫu này khác hẳn 「〜すぎる」 (quá ~). <span class='gd-jp'>高すぎない</span> là “không đắt quá”; còn <span class='gd-jp'>にすぎない</span> thì phía trước luôn có 「に」, nghĩa là “chẳng qua chỉ là”.<br>・Sắc thái khá trang trọng, rất hay gặp trong tin tức, báo cáo, bài phát biểu. Trò chuyện với bạn bè thì nói <span class='gd-jp'>ただの噂だよ</span>、<span class='gd-jp'>〜だけだよ</span> sẽ tự nhiên hơn.<br>・Mẫu này mang đánh giá “không đáng nhắc tới”. Nói về người khác, như <span class='gd-jp'>彼はまだ新入社員にすぎない</span>, có thể nghe hơi coi thường; nói về bản thân thì mới thành khiêm tốn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>にすぎない</b> = <b>nói nhỏ</b> sự việc đi, “chẳng qua chỉ là ~”:<br><span class='gd-jp'>今回の成功は偶然にすぎない。</span>(Thành công lần này chẳng qua chỉ là ăn may thôi)<br><b>にほかならない</b> = <b>khẳng định chắc nịch</b> “chính là ~, không phải gì khác”:<br><span class='gd-jp'>今回の成功はみんなの努力の結果にほかならない。</span>(Thành công lần này chính là kết quả nỗ lực của mọi người)<br>Cả hai đều có dạng 「〜にＸない」 và đều có thể dịch là “chẳng qua là”, nên rất dễ nhầm. Thực ra sắc thái ngược hẳn nhau: mẫu đầu là hạ thấp, mẫu sau là khẳng định mạnh.</div><div class='gd-warn'>Mẹo chọn nhanh: muốn nói “có gì to tát đâu” dùng にすぎない; muốn nói “chính là nó, không phải gì khác” dùng にほかならない.</div>","n2-41":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に違いない」nghĩa là <b>「chắc chắn là ~」「nhất định là ~」</b>. Bạn thấy một manh mối rồi rút ra kết luận với độ chắc chắn cao, giống thám tử đang suy luận: \"Đèn đang sáng, bên trong <b>chắc chắn</b> có người\". Câu này nói về <b>suy đoán</b> của bạn, không phải sự thật đã được xác nhận.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thấy manh mối rồi kết luận</span>Trước mắt có bằng chứng hoặc tình huống khiến bạn rất chắc chắn.</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がついている。誰かいるに違いない。</span>(Đèn đang sáng, chắc chắn có người ở trong)</div><div class='gd-ex-line'>・<span class='gd-jp'>顔がそっくりだ。あの二人は兄弟に違いない。</span>(Mặt giống hệt nhau, hai người đó chắc chắn là anh em)</div><div class='gd-sec'><span class='gd-tag'>Suy đoán chuyện đã xảy ra</span>Phía trước dùng thể quá khứ, để đoán rằng \"lúc đó chắc chắn là ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はもう知っていたに違いない。</span>(Cô ấy chắc chắn đã biết từ lâu rồi)</div><div class='gd-sec'>Câu này hay đi cùng <span class='gd-jp'>きっと</span> để giọng điệu chắc chắn hơn nữa: <span class='gd-jp'>きっと疲れているに違いない。</span>(Anh ấy chắc chắn đang rất mệt)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối trực tiếp, dùng được ở hiện tại, quá khứ và phủ định.<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るに違いない</span></span><span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たに違いない</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないに違いない</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いに違いない</span></span></div><div class='gd-sec'><b>Tính từ な, danh từ</b>: bỏ「だ」rồi mới nối.<br><span class='gd-pair'><span class='gd-jp'>大変だ</span> → <span class='gd-jp'>大変に違いない</span></span><span class='gd-pair'><span class='gd-jp'>犯人だ</span> → <span class='gd-jp'>犯人に違いない</span></span><br>Trong văn viết trang trọng hơn, người ta cũng viết thành <span class='gd-jp'>犯人であるに違いない</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau tính từ な và danh từ không được giữ lại「だ」: <span class='gd-jp'>大変だに違いない</span> là sai.<br>・Trong tiếng Việt, \"nhất định\" cũng có nghĩa \"nhất định phải làm\" (bạn nhất định phải đến nhé), nhưng「に違いない」chỉ có nghĩa \"đoán rất chắc\", không dùng để yêu cầu người khác.<br>・Chuyện bản thân đã biết rõ thì không dùng mẫu này. Nếu nói về thân phận hay cảm xúc của chính mình mà dùng <span class='gd-jp'>私は学生に違いない</span> thì nghe như đang đoán về chính mình, rất kỳ.<br>・Mẫu này hơi mang màu sắc văn viết, tiểu thuyết. Khi nói chuyện với bạn bè, người Nhật hay dùng <span class='gd-jp'>きっと〜だよ</span> hoặc <span class='gd-jp'>〜に決まってる</span> hơn.<br>・Cách nói lịch sự là <span class='gd-jp'>〜に違いありません</span>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>はず</b> = dựa trên sự thật hoặc kế hoạch đã biết, \"theo lẽ thường thì phải ~\":<br><span class='gd-jp'>昨日送ったから、今日届くはずだ。</span>(Hôm qua đã gửi rồi, theo lẽ thường hôm nay sẽ đến)<br><b>に違いない</b> = thấy manh mối rồi suy ra kết luận:<br><span class='gd-jp'>窓が割れている。泥棒が入ったに違いない。</span>(Cửa sổ bị vỡ, chắc chắn có trộm đột nhập)<br>Câu này đổi sang はず thì sẽ không tự nhiên, vì bạn không tính toán theo một kế hoạch đã biết mà phán đoán sau khi nhìn thấy hiện trường. Ngoài ra, はず còn nối được với vế \"kết quả lại không như vậy\": <span class='gd-jp'>来るはずなのに来ない。</span>(Theo lẽ thường thì sẽ đến, vậy mà lại không đến). に違いない không có cách dùng này.</div><div class='gd-sec'><b>に決まっている</b> = \"đương nhiên là ~ rồi\", chủ quan và khẩu ngữ hơn, thường mang cảm xúc:<br><span class='gd-jp'>そんな話、嘘に決まってるよ。</span>(Chuyện như thế đương nhiên là nói dối rồi)<br><b>に相違ない</b> = nghĩa giống に違いない, nhưng cứng và mang tính văn viết hơn, phần lớn xuất hiện trong bài viết.</div><div class='gd-warn'>Mẹo phân biệt: suy ra theo lẽ thường, theo kế hoạch thì dùng「はず」; thấy manh mối rồi rút ra kết luận thì dùng「に違いない」; khi trò chuyện mà có cảm xúc kiểu \"đương nhiên là ~ rồi\" thì dùng「に決まってる」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tiếp theo hãy xem <span class='gd-jp'>〜に決まっている</span> và <span class='gd-jp'>〜に相違ない</span>, cũng là những mẫu thể hiện sự chắc chắn, để phân biệt rõ khác biệt về giọng điệu và hoàn cảnh sử dụng.</div>","n2-43":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に相違ない」là <b>phiên bản mặc vest (trang trọng)</b> của「〜に違いない」, nghĩa là \"chắc chắn là ~\" \"nhất định là ~\". Bạn rất chắc chắn, nhưng đây <b>vẫn là suy đoán</b>. Giọng điệu giống kiểu \"hẳn là ~\", \"chắc chắn là ~\" trong báo cáo hay bình luận báo chí tiếng Việt, bình thường nói chuyện sẽ không nói như vậy.</div><div class='gd-sec'>Trước tiên hãy làm quen với từ này: <span class='gd-jp'>相違</span> đọc là <b>そうい</b>, nghĩa là \"khác nhau, có chênh lệch\". Vì vậy <span class='gd-jp'>相違ない</span> theo nghĩa đen là \"không có chênh lệch\", tức là \"không sai được\".</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ, tính từ い: nối trực tiếp với thể thường (tức cách nói không có ます, です).<br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>知っているに相違ない</span></span>(chắc chắn là biết)<br><span class='gd-pair'><span class='gd-jp'>高かった</span> → <span class='gd-jp'>高かったに相違ない</span></span>(lúc đó chắc chắn là đắt)</div><div class='gd-sec'>Danh từ, tính từ な: <b>không thêm だ</b>, nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼に相違ない</span></span>(chắc chắn là anh ấy)<br><span class='gd-pair'><span class='gd-jp'>有名</span> → <span class='gd-jp'>有名に相違ない</span></span>(chắc chắn là nổi tiếng)<br>Với quá khứ thì dùng <span class='gd-jp'>だった</span>: <span class='gd-jp'>彼だったに相違ない</span>(lúc đó chắc chắn là anh ấy)</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Suy đoán trong văn viết</span>Trong báo cáo, luận văn, bình luận báo chí, tiểu thuyết trinh thám, dùng để đưa ra phán đoán dựa trên manh mối.</div><div class='gd-ex-line'>・<span class='gd-jp'>犯人はこの近くに住んでいるに相違ない。</span>(Thủ phạm chắc chắn sống ở gần đây)</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は全員の努力の賜物に相違ない。</span>(Kết quả này chắc chắn là thành quả nỗ lực của mọi người)</div><div class='gd-sec'><span class='gd-tag'>Phiên bản lịch sự</span>Đổi thành <span class='gd-jp'>〜に相違ありません</span>, dùng khi nêu suy đoán của mình trong hoàn cảnh trang trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>犯人はあの男に相違ありません。</span>(Thủ phạm chắc chắn là người đàn ông đó)</div><div class='gd-sec'><span class='gd-tag'>Xác nhận sự thật: lời khai, giấy tờ</span>Nhóm này <b>không phải suy đoán</b>. Khi khai báo, trả lời cảnh sát hay điền giấy tờ, <span class='gd-jp'>相違ありません</span> là cách nói cố định, nghĩa là \"đúng như vậy, không sai\", nói về điều mà bản thân vốn đã biết.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の財布に相違ありません。</span>(Đây đúng là ví của tôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>上記のとおり相違ありません。</span>(Những điều trên là đúng sự thật)</div><div class='gd-sec'>Câu thứ hai thường được in ở cuối đơn xin, bản cam kết. Phía trước không có に vì nghĩa là \"không có sai khác so với nội dung viết ở trên\".</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ, tính từ な <b>không được thêm だ</b>: đúng là <span class='gd-jp'>彼に相違ない</span>, không phải 彼だに相違ない.<br>・「相」trong <span class='gd-jp'>相違</span> đọc là <b>そう</b>, cả từ đọc là そういない.<br>・Nói với bạn bè <span class='gd-jp'>あの店、おいしいに相違ない</span> sẽ nghe rất lạ, như đang diễn phim trinh thám. Khi nói chuyện hãy dùng <span class='gd-jp'>おいしいに違いない</span> hoặc <span class='gd-jp'>きっとおいしいよ</span>.<br>・Khi dùng để suy đoán, cốt lõi là một suy đoán có độ chắc chắn cao; những việc chính mình đã tận mắt xác nhận, vốn đã biết thì không dùng「〜に相違ない」để suy đoán. Tuy nhiên, khi <span class='gd-jp'>相違ありません</span> được dùng làm cách nói cố định để xác nhận, chứng minh thì là ngoại lệ (tức nhóm lời khai, giấy tờ ở trên).</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống: anh ấy đã thành công, nguyên nhân là gì?<br><b>に違いない</b> = \"chắc chắn là ~\" thông thường, dùng được cả khi nói lẫn khi viết:<br><span class='gd-jp'>彼が成功したのは、努力したからに違いない。</span>(Anh ấy thành công chắc chắn là vì đã nỗ lực)<br><b>に相違ない</b> = nghĩa giống nhau, nhưng cứng và trang trọng hơn, hầu như chỉ xuất hiện trong bài viết:<br><span class='gd-jp'>彼が成功したのは、努力したからに相違ない。</span>(Sở dĩ anh ấy thành công, hẳn là vì đã nỗ lực)<br><b>に決まっている</b> = khẩu ngữ, chủ quan kiểu \"đương nhiên là vậy rồi\", thường mang giọng không cho phản bác:<br><span class='gd-jp'>努力したからに決まってるよ。</span>(Đương nhiên là vì anh ấy đã nỗ lực rồi)<br><b>にほかならない</b> = không phải suy đoán mà là người nói <b>khẳng định</b> \"không gì khác ngoài ~\", dùng để giải thích nguyên nhân hoặc bản chất:<br><span class='gd-jp'>彼の成功は、努力の結果にほかならない。</span>(Thành công của anh ấy chính là kết quả của sự nỗ lực)</div><div class='gd-warn'>Mẹo phân biệt: suy đoán thông thường dùng に違いない; cũng là suy đoán nhưng muốn viết vào báo cáo, bài viết thì dùng に相違ない; nói với bạn bè kiểu \"đương nhiên rồi\" thì dùng に決まっている; muốn nhấn mạnh \"chính là cái này, không phải gì khác\" thì dùng にほかならない.</div>","n2-50":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に伴って」chính là kiểu <b>「cùng với ～」「kéo theo ～」</b> hay thấy trong tin tức và thông báo. Một việc xảy ra hoặc thay đổi, thì việc khác cũng xảy ra hoặc thay đổi theo. Những thông báo kiểu 「Do văn phòng chuyển địa điểm, số điện thoại sẽ thay đổi」 mà bạn hay gặp, tiếng Nhật rất hay dùng mẫu này.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Cùng nhau thay đổi dần</span>Vế trước thay đổi thì vế sau cũng thay đổi theo. Hay dùng với những thứ biến đổi từ từ như dân số, kinh tế, nhiệt độ.</div><div class='gd-ex-line'>・<span class='gd-jp'>年を取るに伴って、体力が落ちてきた。</span>（Càng lớn tuổi, thể lực càng kém đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>気温の上昇に伴い、電気の使用量が増えている。</span>（Nhiệt độ tăng lên nên lượng điện sử dụng cũng đang tăng）</div><div class='gd-sec'><span class='gd-tag'>Kéo theo một việc khác</span>Vế trước là một sự kiện xảy ra một lần, và do nó mà một việc khác cũng xảy ra kèm theo. Cực kỳ hay gặp trong thông báo và tin tức.</div><div class='gd-ex-line'>・<span class='gd-jp'>地震に伴い、津波が発生した。</span>（Kéo theo trận động đất, sóng thần đã xảy ra）</div><div class='gd-ex-line'>・<span class='gd-jp'>事務所の移転に伴い、電話番号が変わります。</span>（Do văn phòng chuyển địa điểm, số điện thoại sẽ thay đổi）</div><div class='gd-ex-line'>・<span class='gd-jp'>工事に伴って、この道は来週から通れなくなります。</span>（Vì thi công nên từ tuần sau con đường này sẽ không đi qua được）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ＋に伴って</b>: Phổ biến nhất, và phần lớn là những danh từ chỉ sự thay đổi hoặc sự kiện như 「増加 (tăng), 発展 (phát triển), 普及 (phổ biến), 移転 (chuyển địa điểm)」.<br><span class='gd-pair'><span class='gd-jp'>人口の増加</span> → <span class='gd-jp'>人口の増加に伴って</span></span><br><b>Động từ thể từ điển＋に伴って</b>, hoặc chèn thêm の thành <b>のに伴って</b>, cả hai dạng đều gặp.<br><span class='gd-pair'><span class='gd-jp'>人口が増える</span> → <span class='gd-jp'>人口が増えるに伴って</span></span><br><span class='gd-pair'><span class='gd-jp'>年を取る</span> → <span class='gd-jp'>年を取るのに伴って</span></span></div><div class='gd-sec'><b>に伴って</b> và <b>に伴い</b> nghĩa giống nhau, nhưng <span class='gd-jp'>に伴い</span> mang tính văn viết hơn, hay được dùng nhất trong tiêu đề tin tức và thông báo.<br>Khi muốn nối thẳng với danh từ phía sau, đổi thành <b>に伴う＋danh từ</b>: <span class='gd-jp'>台風に伴う大雨</span>（mưa lớn đi kèm với bão）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「伴」đọc là <b>ともなって</b>, đừng đọc theo âm Hán Việt \"bạn\" thành ばん.<br>・Mẫu này rất trang trọng, là kiểu dùng trong tin tức, báo cáo, thông báo. Khi nói chuyện với bạn bè kiểu 「trời lạnh nên ai cũng bắt đầu mặc áo khoác」 mà dùng nó thì nghe như đang đọc bản tin; trong văn nói, dùng <span class='gd-jp'>〜につれて</span> hoặc đơn giản là <span class='gd-jp'>〜と</span> sẽ tự nhiên hơn.<br>・Khi nối với danh từ, nhớ là trước danh từ thường có dạng 「〜の〜」: phải nói <span class='gd-jp'>経済の発展に伴って</span>, đừng viết thành 経済が発展に伴って.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>につれて</b> cũng là \"cùng với ～\", nhưng nó chỉ dùng cho kiểu <b>「bên này thay đổi từng chút một, bên kia cũng thay đổi từng chút theo」</b>.<br>Cùng nói về dân số, cả hai đều dùng được, chỉ khác sắc thái:<br><span class='gd-jp'>人口が増えるにつれて、町がにぎやかになった。</span>（Dân số tăng lên nên thị trấn trở nên nhộn nhịp hơn: dùng để giải thích hay trò chuyện đều được）<br><span class='gd-jp'>人口の増加に伴って、住宅不足が深刻化した。</span>（Dân số tăng nên tình trạng thiếu nhà ở trở nên nghiêm trọng: giọng tin tức, báo cáo）<br>Nhưng nếu vế trước là <b>một sự kiện xảy ra một lần</b> thì chỉ dùng được に伴って:<br>○<span class='gd-jp'>地震に伴い、津波が発生した。</span><br>×地震につれて、津波が発生した。（Động đất không phải là thứ \"thay đổi từ từ\" nên không dùng được につれて）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: những việc \"chỉ xảy ra một lần\" như động đất, chuyển nhà, thi công thì chỉ dùng に伴って; còn nếu cả hai bên đều đang thay đổi dần thì dùng cái nào cũng được, nói chuyện thiên về につれて, tin tức và thông báo thiên về に伴って.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là kiểu \"hai vế liên động với nhau\" còn có <span class='gd-jp'>〜に応じて</span>（điều chỉnh tùy theo ～）, ví dụ <span class='gd-jp'>人数に応じて、部屋を選べます。</span>（Bạn có thể chọn phòng tùy theo số người）. Trọng tâm của nó là \"ứng phó phù hợp với từng tình huống khác nhau\", chứ không phải \"thay đổi theo\", nên bạn có thể đặt cạnh に伴って để so sánh và nhớ.</div>","n2-57":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Bạn có thể coi 「〜まい」 là <b>mặt đối lập</b> của thể ý chí 「〜よう」, và đây là cách nói cứng, thường gặp trong văn viết. <span class='gd-jp'>行こう</span> là \"tôi sẽ đi\", còn <span class='gd-jp'>行くまい</span> là \"tôi tuyệt đối không đi nữa\". Nó còn có nghĩa thứ hai là \"chắc là sẽ không ～ đâu\", giống kiểu văn viết \"quyết không\" và \"chắc hẳn sẽ không\" trong tiếng Việt.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Quyết tâm không làm</span>Tự mình hạ quyết tâm \"tuyệt đối không ～ nữa\". Hay đi cùng <span class='gd-jp'>二度と</span>（không bao giờ nữa）, phía sau thường nối với <span class='gd-jp'>と思う</span>、<span class='gd-jp'>と心に誓う</span>、<span class='gd-jp'>と決める</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店には二度と行くまい。</span>（Quán đó tôi tuyệt đối không đến nữa）</div><div class='gd-ex-line'>・<span class='gd-jp'>二度とあのようなミスは犯すまいと心に誓った。</span>（Tôi thề trong lòng sẽ không bao giờ phạm lại lỗi như thế）</div><div class='gd-sec'><span class='gd-tag'>Phỏng đoán là không</span>Nghĩa giống <span class='gd-jp'>ないだろう</span>, dùng để đoán người khác hay sự việc nào đó \"chắc là sẽ không ～ đâu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は今さら戻ってくるまい。</span>（Đến nước này rồi, chắc anh ấy sẽ không quay lại đâu）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことはあるまい。</span>（Chắc không đến mức có chuyện như vậy đâu）</div><div class='gd-sec'>Cách phân biệt là cái nào: nếu chủ ngữ là \"tôi\" và đang nói về quyết tâm thì là nghĩa thứ nhất; nếu chủ ngữ là người khác hoặc sự việc nào đó thì là nghĩa thứ hai.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: thể từ điển thêm まい trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くまい</span></span><span class='gd-pair'><span class='gd-jp'>乗る</span> → <span class='gd-jp'>乗るまい</span></span><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あるまい</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」rồi thêm まい, hoặc không bỏ mà dùng thể từ điển thêm まい, cả hai đều đúng.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べまい</span></span>／<span class='gd-jp'>食べるまい</span></div><div class='gd-sec'><b>Nhóm 3 (する・来る)</b>: có khá nhiều cách viết, gặp thì đều phải nhận ra.<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>するまい</span></span>／<span class='gd-jp'>すまい</span>（cũng có người nói <span class='gd-jp'>しまい</span>）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るまい</span></span>／<span class='gd-jp'>来まい</span><br>「来まい」theo truyền thống đọc là こまい, hiện đại cũng hay đọc là きまい, cả hai cách đọc đều gặp.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nhóm 1 là <b>thể từ điển</b> thêm まい, đừng nối theo kiểu 「ない」: viết <span class='gd-jp'>行くまい</span>, không phải「行かまい」, càng không phải「行かないまい」.<br>・Bản thân まい đã là phủ định, không có dạng khẳng định. Muốn nói \"tôi sẽ làm\" thì dùng thể ý chí <span class='gd-jp'>行こう</span>.<br>・Nó <b>không dùng để bảo người khác đừng làm</b>. <span class='gd-jp'>あなたは行くまい</span> không phải là \"bạn đừng đi\", mà nghe thành \"chắc bạn sẽ không đi đâu\". Muốn bảo người ta đừng đi, hãy nói <span class='gd-jp'>行かないで</span>.<br>・Khi dùng thẳng 「〜まい」 ở cuối câu để thể hiện quyết tâm, người hạ quyết tâm chính là người nói.<br>・Rất văn viết, rất cứng. Nói chuyện với bạn bè mà dùng <span class='gd-jp'>もう行くまい</span> thì nghe như lời dẫn truyện trong tiểu thuyết; văn nói chỉ cần <span class='gd-jp'>もう二度と行かない</span> là được.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>Cùng một tình huống: đoán xem ngày mai anh ấy có đến không.<br><b>ないだろう</b>: cách nói thông thường, nói hay viết đều dùng được.<br>・<span class='gd-jp'>彼は明日来ないだろう。</span>（Ngày mai chắc anh ấy sẽ không đến đâu）<br><b>まい</b>: nghĩa giống nhau, nhưng mang tính văn viết, cứng, sắc thái vẫn dè dặt, là \"chắc là\".<br>・<span class='gd-jp'>彼は明日来るまい。</span>（Ngày mai chắc hẳn anh ấy sẽ không đến）<br><b>っこない</b>: khẩu ngữ, và rất chắc chắn, là \"làm gì có chuyện\".<br>・<span class='gd-jp'>あんなに怒っていたんだから、来っこないよ。</span>（Giận đến thế thì làm gì có chuyện anh ấy đến chứ）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nói chuyện bình thường dùng ないだろう; trong văn viết, kiểu \"chắc là không\" dè dặt thì dùng まい; khi trò chuyện mà muốn nói chắc nịch \"làm gì có chuyện\" thì dùng っこない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>まい thường xuất hiện trong hai cách nói cố định:<br>「〜うが〜まいが」 là \"dù làm hay không làm\": <span class='gd-jp'>行こうが行くまいが、私の自由だ。</span>（Đi hay không là quyền tự do của tôi）<br>「〜ではあるまいし」 là \"có phải ～ đâu mà\": <span class='gd-jp'>子どもじゃあるまいし、一人で行けるよ。</span>（Có phải trẻ con đâu, một mình đi được mà）</div>","n2-62":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に越したことはない」nghĩa là <b>「~ thì tốt nhất rồi」「~ thì còn gì bằng」</b>. Mẫu này nói về một lẽ thường ai cũng đồng ý, kiểu như \"chuyện này còn phải nói sao\". Giọng nhẹ nhàng, không phải đang ra lệnh cho ai.</div><div class='gd-sec'>Nghĩa đen thì <span class='gd-jp'>越す</span> là \"vượt qua\", cả câu là \"không có gì tốt hơn điều này\", nên nghĩa trở thành \"làm vậy là tốt nhất\".</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ: thể từ điển hoặc thể ない＋に越したことはない<br><span class='gd-pair'><span class='gd-jp'>確認する</span> → <span class='gd-jp'>確認するに越したことはない</span></span>（kiểm tra lại thì tốt nhất rồi）<br><span class='gd-pair'><span class='gd-jp'>使わない</span> → <span class='gd-jp'>使わないに越したことはない</span></span>（không phải dùng thì tốt nhất）<br>Tính từ い: nối trực tiếp<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いに越したことはない</span></span><br>Tính từ な, danh từ: nối trực tiếp, hoặc thêm である (trang trọng hơn)<br><span class='gd-pair'><span class='gd-jp'>安全</span> → <span class='gd-jp'>安全に越したことはない</span></span>／<span class='gd-jp'>安全であるに越したことはない</span></div><div class='gd-h'>Những cách dùng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Nói lẽ thường</span>Dùng một mình, nghĩa là \"làm vậy thì chắc chắn không sai\".</div><div class='gd-ex-line'>・<span class='gd-jp'>準備は早いに越したことはない。</span>（chuẩn bị thì tất nhiên càng sớm càng tốt）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬は飲まないに越したことはない。</span>（thuốc thì không phải uống là tốt nhất）</div><div class='gd-sec'><span class='gd-tag'>Theo sau là けど・が</span>Đây là cách dùng phổ biến nhất: trước tiên thừa nhận \"được như vậy thì tất nhiên là tốt nhất\", rồi nói \"nhưng thực tế thì…\".</div><div class='gd-ex-line'>・<span class='gd-jp'>経験はあるに越したことはないが、なくても大丈夫です。</span>（có kinh nghiệm thì tốt nhất, nhưng không có cũng không sao）</div><div class='gd-ex-line'>・<span class='gd-jp'>値段は安いに越したことはないけど、品質も大事だよ。</span>（giá thì tất nhiên càng rẻ càng tốt, nhưng chất lượng cũng quan trọng đấy）</div><div class='gd-sec'>Trong tin tuyển dụng, bạn sẽ rất hay gặp cách viết như câu đầu tiên. Ý là \"không phải điều kiện bắt buộc, có thì được cộng điểm\".</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải viết <b>越した</b>, không phải 越す: <span class='gd-jp'>越すことはない</span> là sai.<br>・Phía trước nối với <b>thể từ điển</b>, không nối với thể た: <span class='gd-jp'>早く行ったに越したことはない</span> là sai, phải nói <span class='gd-jp'>早く行くに越したことはない</span>.<br>・Đừng thấy nửa sau \"ことはない\" rồi tưởng là \"không cần\". Nghĩa khác hẳn nhau (xem phần so sánh bên dưới).<br>・Mẫu này nghĩa là \"làm được thì tốt\", <b>không phải \"nhất định phải làm\"</b>. Khi muốn yêu cầu mạnh với người khác thì không dùng mẫu này.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng một tình huống: \"có gấp không\".<br><b>ことはない</b>＝không cần: <span class='gd-jp'>そんなに急ぐことはない。</span>（không cần vội như vậy）<br><b>に越したことはない</b>＝tất nhiên là tốt nhất: <span class='gd-jp'>急ぐに越したことはない。</span>（nhanh được chút nào thì tốt nhất）</div><div class='gd-sec'>Cùng một tình huống: \"ra khỏi nhà sớm\".<br><b>ほうがいい</b>＝đưa lời khuyên trực tiếp cho đối phương: <span class='gd-jp'>早く出たほうがいいよ。</span>（bạn nên ra khỏi nhà sớm đấy）<br><b>に越したことはない</b>＝nói về lẽ thường chung, nhẹ nhàng hơn và chừa chỗ cho đối phương: <span class='gd-jp'>早く出るに越したことはない。</span>（ra khỏi nhà sớm thì tất nhiên là tốt nhất）</div><div class='gd-sec'>Một mẫu nữa có nghĩa khá gần: <b>に限る</b>＝\"~ là nhất, cứ chọn nó\", là lời giới thiệu mạnh mẽ của chính người nói: <span class='gd-jp'>暑い日は冷たいビールに限る。</span>（ngày nóng thì phải uống bia lạnh）. Còn に越したことはない là lẽ thường ai cũng công nhận, giọng điềm tĩnh hơn.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: thấy「に越した」thì nghĩ \"còn gì bằng\"; chỉ có「ことはない」thì là \"không cần\"; muốn khuyên thẳng đối phương thì dùng「ほうがいい」.</div>","n2-1":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜つつある」nghĩa là <b>「đang dần dần ~」「ngày càng ~」</b>. Mẫu này nói về <b>một sự thay đổi đang diễn ra, chưa kết thúc</b>, giống như tin tức hay nói \"nhiệt độ liên tục tăng\", \"kinh tế đang dần phục hồi\". Giọng khá trang trọng, thường xuất hiện trong tin tức, báo cáo, bài viết.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Thay đổi đang diễn ra</span>Một việc đang từ từ thay đổi theo một hướng, và hiện tại vẫn đang thay đổi.</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は少しずつ回復しつつある。</span>（kinh tế đang phục hồi từng chút một）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町の人口は減りつつある。</span>（dân số của thị trấn này đang dần giảm）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本でもキャッシュレス決済が広がりつつある。</span>（ở Nhật, thanh toán không dùng tiền mặt cũng ngày càng phổ biến）</div><div class='gd-sec'><span class='gd-tag'>Từng bước tiến tới kết quả</span>Khi đi với những động từ như \"biến mất, đến gần\" (vốn diễn ra trong chốc lát), nghĩa là \"đang từng bước tiến tới kết quả đó nhưng chưa tới\".</div><div class='gd-ex-line'>・<span class='gd-jp'>台風が日本に近づきつつある。</span>（bão đang dần tiến gần đến Nhật Bản）</div><div class='gd-ex-line'>・<span class='gd-jp'>伝統的な祭りが消えつつある。</span>（các lễ hội truyền thống đang dần biến mất）</div><div class='gd-sec'><span class='gd-tag'>Nói về quá khứ</span>Đổi thành「つつあった」, nghĩa là lúc đó đang thay đổi.</div><div class='gd-ex-line'>・<span class='gd-jp'>当時、この町は大きく変わりつつあった。</span>（lúc đó, thị trấn này đang thay đổi rất lớn）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chia động từ sang thể ます, rồi <b>bỏ ます</b>, thêm「つつある」.<br><span class='gd-pair'><span class='gd-jp'>増えます</span> → <span class='gd-jp'>増えつつある</span></span><span class='gd-pair'><span class='gd-jp'>進みます</span> → <span class='gd-jp'>進みつつある</span></span><br><span class='gd-pair'><span class='gd-jp'>回復します</span> → <span class='gd-jp'>回復しつつある</span></span><span class='gd-pair'><span class='gd-jp'>失われます</span> → <span class='gd-jp'>失われつつある</span></span><br>Muốn nói lịch sự hơn thì dùng「つつあります」: <span class='gd-jp'>景気は回復しつつあります。</span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nối với thể ます (bỏ ます), không phải thể từ điển: phải nói <span class='gd-jp'>増えつつある</span>, không nói「増えるつつある」; phải nói <span class='gd-jp'>回復しつつある</span>, không nói「回復するつつある」.<br>・Cuối câu là <b>ある</b>, không phải いる.<br>・Chỉ nối được với động từ chỉ sự thay đổi, như <span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>変わる</span>、<span class='gd-jp'>広がる</span>、<span class='gd-jp'>進む</span>、「〜化する」. Hành động thông thường thì không dùng được: \"tôi đang ăn cơm\" là <span class='gd-jp'>ご飯を食べている</span>, không nói「ご飯を食べつつある」.<br>・Mẫu này mang tính văn viết. Khi nói với bạn bè \"dạo này trời lạnh dần rồi\", cách nói tự nhiên là <span class='gd-jp'>最近、だんだん寒くなってきたね。</span> Nếu nói「寒くなりつつある」thì nghe giống như đang đọc bản tin.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>〜ている</b>: khi đi với động từ kiểu \"biến mất\", nghĩa là <b>đã thay đổi xong rồi</b>.<br>・<span class='gd-jp'>その技術はもう失われている。</span>（kỹ thuật đó đã thất truyền rồi）<br><b>〜つつある</b>: nghĩa là <b>vẫn đang thay đổi, chưa xong</b>.<br>・<span class='gd-jp'>その技術は失われつつある。</span>（kỹ thuật đó đang dần thất truyền）<br>Với động từ kiểu \"tăng, giảm\", <span class='gd-jp'>人口が減っている</span> cũng có thể nghĩa là \"đang giảm\", ý khá gần nhau. Khác biệt là つつある nhấn mạnh hơn vào quá trình \"liên tục thay đổi\", và trang trọng hơn.</div><div class='gd-sec'><b>〜ばかりだ</b> (nối với thể từ điển): chỉ thay đổi theo một hướng, và gần như luôn là xấu đi, mang giọng lo lắng hoặc than phiền.<br>・<span class='gd-jp'>景気は悪くなるばかりだ。</span>（kinh tế cứ ngày càng tệ đi）<br><b>〜つつある</b>: chỉ đơn thuần mô tả sự thay đổi, hướng tốt hay xấu đều được.<br>・<span class='gd-jp'>景気は回復しつつある。</span>（kinh tế đang dần phục hồi）</div><div class='gd-sec'><b>〜つつ（も）</b>: phía sau không có ある thì nghĩa hoàn toàn khác, là \"vừa ~ vừa\" hoặc \"rõ ràng ~ mà lại\".<br>・<span class='gd-jp'>体に悪いと知りつつ、タバコがやめられない。</span>（biết rõ là có hại cho sức khỏe mà vẫn không bỏ được thuốc lá）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: thấy「つつ＋ある」thì dịch là \"đang dần ~\"; muốn nói \"đã thành ~ rồi\" thì dùng ている; muốn nói \"chỉ ngày càng tệ\" thì dùng ばかりだ; chỉ có「つつ」mà không có ある thì là \"vừa ~ vừa／rõ ràng ~ mà\".</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là nói về sự thay đổi, bạn có thể học tiếp「〜につれて」(càng ~ thì càng), ví dụ <span class='gd-jp'>年をとるにつれて、体力が落ちてきた。</span>（càng lớn tuổi, thể lực càng giảm sút）</div>","n2-3":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AからBにかけて」nghĩa là <b>“từ A đến B, trong khoảng này”</b> (về thời gian hoặc khu vực). Điểm mấu chốt là <b>“đại khái”</b>: điểm đầu và điểm cuối không phải một đường kẻ chính xác mà là một phạm vi mờ mờ. Dự báo thời tiết nói “tối nay đến ngày mai sẽ có mưa”, chứ không nói mấy giờ mấy phút bắt đầu, mấy giờ mấy phút tạnh. Khi đó tiếng Nhật dùng にかけて.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Phạm vi thời gian</span>Một việc xảy ra trong một khoảng thời gian đại khái. Có thể kéo dài liên tục, cũng có thể lúc có lúc không.</div><div class='gd-ex-line'>・<span class='gd-jp'>今夜から明日の朝にかけて、強い雨が降るでしょう。</span>（Từ tối nay đến sáng mai sẽ có mưa lớn）</div><div class='gd-ex-line'>・<span class='gd-jp'>この辺りは、年末から正月にかけてとても混む。</span>（Khu này từ cuối năm đến dịp Tết rất đông）</div><div class='gd-sec'><span class='gd-tag'>Phạm vi địa điểm</span>Cả một vùng từ nơi này đến nơi kia. Thường gặp trong dự báo thời tiết và tin tức.</div><div class='gd-ex-line'>・<span class='gd-jp'>九州から四国にかけて、大雨に注意してください。</span>（Từ Kyushu đến Shikoku, hãy chú ý mưa lớn）</div><div class='gd-sec'><span class='gd-tag'>Bộ phận cơ thể</span>Cũng nghe rất nhiều trong đời sống, đặc biệt hữu ích khi đi khám bệnh và mô tả chỗ đau.</div><div class='gd-ex-line'>・<span class='gd-jp'>首から肩にかけてが痛いんです。</span>（Tôi bị đau từ cổ đến vai）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Dạng cơ bản: danh từ＋から＋danh từ＋にかけて<br><span class='gd-pair'><span class='gd-jp'>3月から4月</span> → <span class='gd-jp'>3月から4月にかけて</span></span><br><br>Phần「から」đôi khi có thể bỏ, chỉ nói “hướng về ~, khoảng ~”:</div><div class='gd-ex-line'>・<span class='gd-jp'>週末にかけて、天気が崩れるでしょう。</span>（Đến khoảng cuối tuần, thời tiết sẽ xấu đi）</div><div class='gd-sec'>Khi phía sau cần nối với danh từ, dùng <b>にかけての</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>春から夏にかけての季節が一番好きだ。</span>（Mình thích nhất khoảng thời gian từ xuân sang hè）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tiếng Việt nói “từ A đến B” cho mọi trường hợp, nhưng tiếng Nhật phải phân biệt: khi <b>thời gian được nói rất chính xác</b>, như giờ làm việc hay giờ mở cửa, phải dùng <b>から～まで</b>.<br>　×<span class='gd-jp'>9時から6時にかけて働きます。</span><br>　○<span class='gd-jp'>9時から6時まで働きます。</span><br>・Phía trước chỉ đặt được <b>danh từ</b>, và là loại “có thể vẽ ra một phạm vi” như thời gian, địa điểm, bộ phận cơ thể. Không đi với động từ, cũng không đặt người vào: “từ anh A đến anh B” thì không dùng にかけて.<br>・Khi nối với danh từ phía sau đừng quên「の」: đúng là <span class='gd-jp'>夏にかけての旅行</span>, không phải 夏にかけて旅行.<br>・Sắc thái thiên về văn viết, trang trọng, hay gặp nhất trong tin tức, dự báo thời tiết, văn giải thích. Trò chuyện hằng ngày cũng nghe được, nhưng khi nói về thời gian thì văn nói thường dùng thẳng から～まで hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>から～まで</b>＝điểm đầu và điểm cuối <b>rõ ràng, chính xác</b>：<span class='gd-jp'>会議は1時から3時までです。</span>（Cuộc họp từ một giờ đến ba giờ）<br><b>にかけて</b>＝<b>đại khái</b> nằm trong khoảng này：<span class='gd-jp'>午後から夕方にかけて雨が降る。</span>（Từ chiều đến tối sẽ có mưa）<br><b>にわたって</b>＝nhấn mạnh <b>bao trùm cả một đoạn dài, quy mô lớn</b>, thường đi với những từ chỉ độ dài, độ lớn như「3日間」「10年」「全国」：<span class='gd-jp'>雨が3日間にわたって降り続いた。</span>（Mưa kéo dài suốt ba ngày liền）</div><div class='gd-sec'>Ngoài ra, <b>にかけては</b> có thêm một chữ「は」, nghĩa hoàn toàn khác, là “nói về mặt ~ thì”：<span class='gd-jp'>料理の腕にかけては、彼に勝てる人はいない。</span>（Về tài nấu ăn, không ai hơn được anh ấy）. Thấy có「は」và phía sau đang khen ai đó giỏi thì chính là mẫu này.</div><div class='gd-warn'>Mẹo phân biệt: thời gian chính xác dùng まで, khoảng đại khái dùng にかけて, nhấn mạnh “suốt cả một đoạn dài” dùng にわたって; thêm một chữ「は」và đang nói về năng lực thì là にかけては.</div>","n2-4":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜末（に）」nghĩa là <b>“sau một hồi ~, cuối cùng…”</b>. Phía trước là một quá trình tốn thời gian, tốn sức (bàn bạc lâu, băn khoăn lâu, cố gắng lâu), phía sau nối với <b>kết quả cuối cùng</b>. Giống như bạn nói “cãi nhau cả buổi tối, cuối cùng quyết định đi Nhật chơi”.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>Danh từ＋の＋末（に）<br><span class='gd-pair'><span class='gd-jp'>議論</span> → <span class='gd-jp'>議論の末に</span></span>（sau khi thảo luận）<br><span class='gd-pair'><span class='gd-jp'>苦労</span> → <span class='gd-jp'>苦労の末に</span></span>（sau bao vất vả）</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Động từ thể た＋末（に）<br><span class='gd-pair'><span class='gd-jp'>悩む</span> → <span class='gd-jp'>悩んだ</span> → <span class='gd-jp'>悩んだ末に</span></span>（sau một thời gian dài băn khoăn）<br><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えた</span> → <span class='gd-jp'>考えた末に</span></span>（sau khi suy nghĩ rất lâu）</div><div class='gd-sec'>「に」có thể bỏ, nghĩa không đổi. Khi phía sau nối với danh từ thì dùng「末の」：<span class='gd-jp'>悩んだ末の決断</span>（quyết định sau bao băn khoăn）.</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'>Phía sau thường có「<span class='gd-jp'>ようやく</span>」「<span class='gd-jp'>やっと</span>」「<span class='gd-jp'>ついに</span>」để nhấn mạnh cảm giác “cuối cùng thì cũng”.</div><div class='gd-ex-line'>・<span class='gd-jp'>長い話し合いの末、やっと契約が決まった。</span>（Sau cuộc thương lượng dài, cuối cùng hợp đồng cũng được chốt）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も迷った末に、この部屋に決めた。</span>（Phân vân mãi mấy lần, cuối cùng mình quyết định thuê phòng này）</div><div class='gd-sec'>Kết quả không nhất thiết là chuyện tốt, <b>kết quả xấu cũng dùng được</b>; 「末」chỉ thuật lại một cách khách quan là cuối cùng đã ra sao.</div><div class='gd-ex-line'>・<span class='gd-jp'>長い闘病の末に亡くなった。</span>（Sau thời gian dài chống chọi với bệnh tật, cuối cùng ông ấy đã qua đời）</div><div class='gd-ex-line'>・<span class='gd-jp'>悩んだ末、進学を諦めた。</span>（Băn khoăn mãi, cuối cùng bỏ ý định học lên）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ bắt buộc dùng <b>thể た</b>: đúng là <span class='gd-jp'>悩んだ末</span>, không phải「悩む末」.<br>・Ở đây 末 đọc là <b>すえ</b>, không phải まつ.<br>・Phía trước phải là “một quá trình” như thảo luận, nỗ lực, băn khoăn, đàm phán, tức là những việc tốn thời gian. Chỉ ghi khoảng thời gian thì không được: 「3時間の末」nghe không tự nhiên, phải nói <span class='gd-jp'>3時間の議論の末</span>.<br>・「Danh từ chỉ thời gian＋の末」là một nghĩa khác, “cuối ~”：<span class='gd-jp'>来月の末に引っ越す</span> là “cuối tháng sau chuyển nhà”, không phải “sau khi tháng sau trôi qua”.<br>・Phía sau là <b>kết quả đã có</b>, thường dùng thì quá khứ (決めた、決まった、出た), không nối với kiểu “~ nhé” hay “hãy ~”.<br>・Sắc thái khá trang trọng, hay gặp trong tin tức, báo cáo, lời giải thích chính thức; khi nói chuyện với bạn bè thì thường nói「<span class='gd-jp'>結局</span>」hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Mẫu cùng cấp「<b>〜あげく（に）</b>」có cách ghép giống hệt (thể た／danh từ の), cũng là “sau một hồi ~ cuối cùng…”, khác nhau ở <b>tâm trạng của người nói</b>.<br><b>末</b>＝thuật lại kết quả cuối cùng một cách khách quan, tốt, xấu hay trung tính đều được:<br><span class='gd-jp'>さんざん迷った末、何も買わなかった。</span>（Phân vân mãi, cuối cùng chẳng mua gì）<br><b>あげく</b>＝mang theo sự bất mãn, bất lực, có cảm giác “loay hoay cả buổi, rốt cuộc lại…”:<br><span class='gd-jp'>さんざん迷ったあげく、何も買わなかった。</span>（Phân vân mãi, cuối cùng rốt cuộc chẳng mua gì）<br>Vì vậy khi kết quả là chuyện tốt, như <span class='gd-jp'>努力の末に合格した</span>（nỗ lực rồi đã đậu）, thường không đổi sang あげく.</div><div class='gd-warn'>Mẹo phân biệt: chỉ đơn thuần thuật lại kết quả thì dùng 末; mang tâm trạng than phiền, bất lực, thấy “loay hoay cả buổi mà lại ra thế này” thì dùng あげく.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn có thể học tiếp <span class='gd-jp'>〜あげく（に）</span>, luyện hai mẫu cùng lúc sẽ dễ nắm được sự khác biệt về sắc thái hơn.</div>","n2-7":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜て以来」 nghĩa là <b>「kể từ khi ~ thì cứ… mãi đến giờ」</b>. Phía trước đặt một sự việc đã xảy ra trong quá khứ làm <b>mốc bắt đầu</b>. Phía sau nói từ lúc đó đến nay <b>tình trạng cứ như thế nào</b>. Giống câu \"Kể từ khi chuyển nhà, sáng nào mình cũng chạy bộ\".</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ thể て＋<span class='gd-jp'>以来</span> (đọc là いらい). Bạn đã biết thể て rồi, cứ thế nối vào là được:<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て以来</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会って以来</span></span><span class='gd-pair'><span class='gd-jp'>卒業する</span> → <span class='gd-jp'>卒業して以来</span></span><br>Thể bị động cũng dùng được:<span class='gd-pair'><span class='gd-jp'>導入される</span> → <span class='gd-jp'>導入されて以来</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Giữ nguyên trạng thái đến tận bây giờ</span>Phía sau thường đi với「ている」「ずっと」.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来て以来、ずっとこのアパートに住んでいる。</span>(Từ khi đến Nhật, mình cứ sống mãi ở căn hộ này)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが生まれて以来、ゆっくり映画を見る時間がない。</span>(Từ khi con chào đời, mình không có thời gian thong thả xem phim)</div><div class='gd-sec'><span class='gd-tag'>Từ đó đến giờ chưa từng…</span>Phía sau thường đi với「一度も」「〜ていない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼とけんかして以来、一度も話していない。</span>(Từ lúc cãi nhau với anh ấy, mình chưa nói chuyện với nhau lần nào)</div><div class='gd-sec'><span class='gd-tag'>Từ đó trở nên…</span>Đi với「〜ようになった」: sau khi thay đổi thì giữ nguyên như vậy đến nay.</div><div class='gd-ex-line'>・<span class='gd-jp'>留学して以来、字幕なしでドラマが見られるようになった。</span>(Từ khi đi du học, mình đã xem được phim truyền hình mà không cần phụ đề)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nối với <b>thể て</b>, không phải thể た: nói <span class='gd-jp'>卒業して以来</span>, không được nói 「卒業した以来」.<br>・Vế sau <b>không được là việc chỉ xảy ra một lần</b>. Câu \"Từ khi đến Nhật, mình đã đi Kyoto một lần\" không dùng được 以来: ×日本に来て以来、一度京都へ行った。 Kiểu \"sau đó đã làm việc gì đó\" thì phải dùng <span class='gd-jp'>日本に来てから、京都へ行った。</span><br>・Vế trước chỉ có thể là việc <b>đã xảy ra rồi</b>, không dùng để nói về kế hoạch tương lai.<br>・Mốc bắt đầu thường cách hiện tại một khoảng thời gian. Nói \"từ lúc vừa ăn trưa xong đến giờ\" nghe lạ trong tiếng Việt, thì tiếng Nhật cũng lạ y như vậy.<br>・Giọng văn khá trang trọng, thiên về văn viết. Khi nói chuyện với bạn bè, nhiều người sẽ đổi thành <span class='gd-jp'>〜てから、ずっと</span>.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Cùng là chuyện \"chuyển nhà\":<br><b>てから</b>＝chỉ nói thứ tự trước sau, \"làm A rồi B\":<br><span class='gd-jp'>引っ越してから、ジョギングを始めた。</span>(Sau khi chuyển nhà, mình bắt đầu chạy bộ)<br><b>て以来</b>＝từ lúc đó <b>cho đến bây giờ</b> vẫn như vậy:<br><span class='gd-jp'>引っ越して以来、毎朝ジョギングしている。</span>(Từ khi chuyển nhà, sáng nào mình cũng chạy bộ)<br><b>をきっかけに</b>＝nhấn mạnh việc đó là <b>cơ hội, bước ngoặt</b>, nhờ nó mà bắt đầu:<br><span class='gd-jp'>引っ越しをきっかけに、ジョギングを始めた。</span>(Nhân dịp chuyển nhà, mình bắt đầu chạy bộ)</div><div class='gd-warn'>Mẹo nhỏ để chọn: nếu vế sau có thể thêm \"đến giờ vẫn thế\" thì dùng て以来; chỉ là \"rồi sau đó\" thì dùng てから; muốn nói \"nhờ việc này mà mới bắt đầu\" thì dùng をきっかけに.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Trước <span class='gd-jp'>以来</span> cũng có thể đặt trực tiếp danh từ chỉ thời gian, hoặc dùng <span class='gd-jp'>それ以来</span> (từ đó đến nay) để nối với câu trước:</div><div class='gd-ex-line'>・<span class='gd-jp'>去年の春以来、彼から連絡がない。</span>(Từ mùa xuân năm ngoái, anh ấy không liên lạc với mình)</div><div class='gd-ex-line'>・<span class='gd-jp'>一度飲みすぎて倒れた。それ以来、お酒は飲んでいない。</span>(Có lần mình uống quá chén rồi ngã quỵ. Từ đó mình không uống rượu nữa)</div>","n2-9":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜からこそ」 nghĩa là <b>「chính vì ~ nên mới ~」</b>. 「から」 thông thường chỉ nêu lý do; thêm 「こそ」 giống như tô đậm lý do bằng bút dạ quang, ý là <b>chính là lý do này, không phải gì khác</b>. Mẫu này hay dùng khi ngược với suy nghĩ thông thường: người ta nghĩ A khiến mình không muốn làm, vậy mà bạn lại chính vì A mà làm.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>「Thể thông thường」 là cách nói không có です・ます.<br><b>Động từ, tính từ い</b>: nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>思う</span> → <span class='gd-jp'>思うからこそ</span></span><span class='gd-pair'><span class='gd-jp'>頑張った</span> → <span class='gd-jp'>頑張ったからこそ</span></span><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいからこそ</span></span><br><b>Danh từ, tính từ な</b>: ở giữa phải thêm 「だ」.<br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族だからこそ</span></span><span class='gd-pair'><span class='gd-jp'>大切</span> → <span class='gd-jp'>大切だからこそ</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nhấn mạnh lý do thật sự</span>Nói với đối phương: mình làm vậy, lý do nằm ngay ở đây.</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたのことを思うからこそ、厳しく言うんです。</span>(Chính vì nghĩ cho bạn nên mình mới nói nặng lời như vậy)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日練習したからこそ、本番で落ち着いていられた。</span>(Chính vì ngày nào cũng luyện tập nên lúc thi đấu thật mình mới giữ được bình tĩnh)</div><div class='gd-sec'><span class='gd-tag'>Ngược với suy nghĩ thông thường</span>Theo lẽ thường người ta sẽ nghĩ theo hướng khác, nhưng bạn lại nói \"chính vì thế nên mới ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいからこそ、休みの日を大切にしている。</span>(Chính vì bận nên mình mới đặc biệt trân trọng ngày nghỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>失敗したからこそ、わかったこともある。</span>(Chính vì đã thất bại nên mình mới hiểu ra một số điều)</div><div class='gd-sec'><span class='gd-tag'>だからこそ</span>Đặt ở đầu câu, nối với nội dung câu trước, nghĩa là \"cũng chính vì vậy mà\". Cách dùng này rất thường gặp.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は大変です。だからこそ、やりがいがあります。</span>(Công việc này vất vả. Nhưng cũng chính vì vậy mà nó mới đáng làm)</div><div class='gd-sec'>Vế sau thường kết thúc bằng 「<span class='gd-jp'>のだ</span>」 hoặc 「<span class='gd-jp'>んです</span>」. Thêm vào sẽ có sắc thái giải thích kiểu \"thật ra là vậy đó\", rất hợp với からこそ.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な đừng quên thêm 「だ」: phải là <span class='gd-jp'>家族だからこそ</span>, không phải 「家族からこそ」.<br>・Chỉ dùng được 「から」, không thể đổi thành 「ので」: không có cách nói 「ので＋こそ」.<br>・Đừng dùng cho những lý do nhỏ nhặt, bình thường hay tiêu cực. Ví dụ \"mình ngủ quên nên bị trễ\" thì chỉ cần nói <span class='gd-jp'>寝坊したから遅刻した</span>. Nói thành 「寝坊したからこそ遅刻した」 sẽ rất kỳ, như thể ngủ quên là một lý do gì ghê gớm lắm.<br>・Tiếng Việt nói \"chính vì… <b>nên mới</b>…\", còn vế sau trong tiếng Nhật không cần tìm thêm một từ riêng tương ứng với \"mới\", vì こそ đã mang sắc thái đó rồi.<br>・Cách nói này mang cảm xúc khá mạnh, thường xuất hiện khi nói thật lòng, trong bài diễn thuyết hoặc bài viết. Nếu dùng liên tục cho chuyện vặt hằng ngày thì nghe sẽ rất kịch tính.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>から</b>＝chỉ đơn thuần nêu lý do.<br>・<span class='gd-jp'>心配だから、電話した。</span>(Vì lo nên mình gọi điện cho bạn)<br><b>からこそ</b>＝nhấn mạnh \"chính là lý do này\", thường dùng khi đối phương hiểu lầm, hoặc khi bạn muốn nói nặng hơn.<br>・<span class='gd-jp'>心配だからこそ、何度も電話したんです。</span>(Chính vì lo cho bạn nên mình mới gọi hết lần này đến lần khác)</div><div class='gd-sec'><b>からには</b>＝đã ~ thì phải ~, vế sau là quyết tâm hoặc việc nên làm.<br>・<span class='gd-jp'>留学するからには、しっかり勉強したい。</span>(Đã đi du học thì mình muốn học hành cho nghiêm túc)<br><b>からこそ</b>＝chính vì ~ nên mới ~, vế sau là kết quả hoặc hành động nảy sinh từ đó.<br>・<span class='gd-jp'>留学したからこそ、台湾の良さに気づいた。</span>(Chính vì đã đi du học nên mình mới nhận ra cái hay của Đài Loan)</div><div class='gd-warn'>Mẹo nhỏ để chọn: nếu nói được \"đã ~ thì phải ~\" thì dùng からには; nếu nói được \"chính vì ~ nên mới ~\" thì dùng からこそ; còn chỉ là \"vì ~ nên ~\" bình thường thì dùng から là đủ.</div>","n2-10":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にもかかわらず」nghĩa là <b>「mặc dù ～, vậy mà vẫn ～」</b>. Vế trước nêu một sự thật, vế sau là một kết quả <b>trái với dự đoán</b>. Mẫu này khá giống「のに」, nhưng <b>trang trọng và khách quan</b> hơn. Bạn sẽ gặp nhiều trong tin tức, báo cáo, diễn thuyết, môi trường công sở, còn nói chuyện với bạn bè thì ít dùng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Kết quả bất ngờ</span>Theo lẽ thường thì phải thế này, nhưng kết quả lại không phải vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も確認したにもかかわらず、同じミスをしてしまった。</span>（Dù đã kiểm tra nhiều lần, vẫn mắc lại đúng lỗi cũ）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が集まった。</span>（Dù trời mưa, vẫn có rất nhiều người tập trung đến）</div><div class='gd-sec'><span class='gd-tag'>Mô tả tình trạng hiện tại</span>Vế sau không nhất thiết phải ở thì quá khứ, việc đang tiếp diễn cũng dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>反対が多いにもかかわらず、政府は計画を進めている。</span>（Dù có nhiều ý kiến phản đối, chính phủ vẫn đang thúc đẩy kế hoạch）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はお金持ちであるにもかかわらず、質素な生活をしている。</span>（Anh ấy giàu có, vậy mà lại sống rất giản dị）</div><div class='gd-sec'><span class='gd-tag'>Lời cảm ơn trong dịp trang trọng</span>Cách nói cố định thường nghe trong bài phát biểu và email công việc.</div><div class='gd-ex-line'>・<span class='gd-jp'>本日はお忙しいにもかかわらず、お集まりいただきありがとうございます。</span>（Hôm nay dù mọi người rất bận rộn vẫn dành thời gian đến dự, xin chân thành cảm ơn）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ, tính từ い</b>: ghép trực tiếp với thể thường (dạng từ điển, thể た hoặc thể ない).<br><span class='gd-pair'><span class='gd-jp'>努力した</span> → <span class='gd-jp'>努力したにもかかわらず</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いにもかかわらず</span></span></div><div class='gd-sec'><b>Danh từ, tính từ な</b>: không thêm「だ」, hoặc ghép thẳng, hoặc thêm「である」.<br><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨にもかかわらず</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生であるにもかかわらず</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便にもかかわらず</span></span>（cũng có thể nói <span class='gd-jp'>不便であるにもかかわらず</span>）<br>Với quá khứ thì dùng「だった」là được: <span class='gd-jp'>学生だったにもかかわらず</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ <b>không thêm だ</b>: nói <span class='gd-jp'>雨にもかかわらず</span>, không phải「雨だにもかかわらず」.<br>・Vế sau phải nói về <b>sự thật</b> (việc đã xảy ra hoặc tình trạng đang diễn ra). Không đi với ý chí, lời rủ rê, mệnh lệnh, yêu cầu kiểu「chúng ta hãy ～」「hãy ～」「tôi sẽ ～」. Muốn nói「Dù trời mưa, chúng ta vẫn đi chơi nhé」thì phải dùng ても: <span class='gd-jp'>雨でも出かけよう。</span><br>・Vế trước cũng phải là <b>sự thật</b>. 「Dù có」「cho dù」trong tiếng Việt nhiều khi chỉ là giả định (chưa xảy ra). Trường hợp đó phải dùng「ても」, không dùng được にもかかわらず.<br>・Mẫu này rất trang trọng. Khi than phiền với bạn kiểu「tớ nói rồi mà cậu vẫn không nghe」thì dùng のに sẽ tự nhiên hơn, dùng にもかかわらず nghe như đang đọc thông cáo báo chí.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>のに</b> = mang theo <b>cảm xúc của người nói</b> (bất mãn, tiếc nuối, ngạc nhiên), rất hay dùng trong văn nói, còn có thể bỏ lửng ở cuối câu.<br><b>にもかかわらず</b> = trình bày <b>bình tĩnh, khách quan</b> hơn, trang trọng, thiên về văn viết.</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も説明したのに、全然わかってくれない！</span>（Mình giải thích bao nhiêu lần rồi mà cậu vẫn chẳng hiểu gì cả!）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も説明したにもかかわらず、理解してもらえなかった。</span>（Dù đã giải thích nhiều lần, đối phương vẫn không hiểu）</div><div class='gd-sec'><span class='gd-jp'>せっかく作ったのに。</span>（Công mình đã cất công làm mà…）Kiểu nói bỏ lửng giữa chừng này chỉ のに mới dùng được, にもかかわらず thì không.</div><div class='gd-sec'>Một chỗ nữa cực dễ đọc nhầm là <b>にかかわらず</b> thiếu「も」, nghĩa hoàn toàn khác, là <b>「bất kể ～」</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢にかかわらず、誰でも参加できます。</span>（Bất kể bao nhiêu tuổi, ai cũng có thể tham gia）</div><div class='gd-ex-line'>・<span class='gd-jp'>天気にかかわらず、試合は行います。</span>（Bất kể thời tiết thế nào, trận đấu vẫn diễn ra）</div><div class='gd-warn'>Mẹo phân biệt: muốn than phiền, có cảm xúc thì dùng のに; muốn nói「mặc dù ～ vẫn ～」một cách trang trọng, khách quan thì dùng にもかかわらず. Gặp「にかかわらず」hãy xem có「も」không: có も là「mặc dù」, không có も là「bất kể」.</div><div class='gd-h'>Học tiếp sau mẫu này</div><div class='gd-sec'>Đặt ở đầu câu thành「<span class='gd-jp'>それにもかかわらず</span>」, nghĩa là「dù vậy」, dùng để nối với câu trước: <span class='gd-jp'>何度も注意された。それにもかかわらず、彼は遅刻を続けた。</span>（Anh ta đã bị nhắc nhở nhiều lần. Dù vậy, anh ta vẫn tiếp tục đi trễ）<br><span class='gd-jp'>ものの</span> và <span class='gd-jp'>とはいえ</span> cùng cấp độ cũng mang nghĩa「tuy ～ nhưng ～」, bạn có thể học tiếp rồi so sánh với nhau.</div>","n2-12":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とはいえ」nghĩa là <b>「tuy nói là ～ nhưng …」「nói thì cũng đúng, nhưng …」</b>. Vế trước thừa nhận một sự thật, vế sau bổ sung: 「Nhưng mà, mọi chuyện không đơn giản như bạn nghĩ đâu.」<br>Giống như bạn nói「Tuy là mùa xuân nhưng sáng sớm vẫn lạnh」: bạn thừa nhận bây giờ là mùa xuân, nhưng ấn tượng「xuân = ấm áp」không hoàn toàn đúng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Tuy nói là ～</span>Vế trước là một sự thật khiến người nghe có một ấn tượng nào đó, vế sau nói thực tế lại khác với ấn tượng ấy.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいえ、朝晩はまだ寒い。</span>（Tuy nói là mùa xuân, sáng tối vẫn còn lạnh）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に5年住んでいるとはいえ、敬語はまだ苦手だ。</span>（Tuy đã sống ở Nhật 5 năm, tôi vẫn chưa giỏi kính ngữ）</div><div class='gd-ex-line'>・<span class='gd-jp'>安いとはいえ、毎日買うと結構な金額になる。</span>（Tuy rẻ, nhưng ngày nào cũng mua thì cũng thành một khoản không nhỏ）</div><div class='gd-sec'><span class='gd-tag'>Đặt đầu câu</span>Đứng riêng ở đầu câu, nghĩa là「nói vậy chứ」, dùng để nối với câu trước.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は大変だ。とはいえ、辞めるつもりはない。</span>（Công việc vất vả thật. Nói vậy chứ tôi cũng không định nghỉ việc）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Động từ, tính từ い: ghép trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>慣れている</span> → <span class='gd-jp'>慣れているとはいえ</span></span><span class='gd-pair'><span class='gd-jp'>合格した</span> → <span class='gd-jp'>合格したとはいえ</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとはいえ</span></span><br>Danh từ, tính từ な: 「だ」phía sau <b>thường được lược bỏ</b>, ghép thẳng với とはいえ (thêm だ cũng được).<br><span class='gd-pair'><span class='gd-jp'>春</span> → <span class='gd-jp'>春とはいえ</span></span><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利とはいえ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>便利とはいえ、スマホばかり見るのはよくない。</span>（Tuy tiện lợi, nhưng cứ dán mắt vào điện thoại mãi thì không tốt）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「は」đọc là <b>わ</b>: とはいえ đọc là「とわいえ」.<br>・Vế trước nhất định phải là <b>sự thật đã thành lập</b>, không đặt giả định chưa xảy ra vào được. 「Cho dù ngày mai trời mưa」phải nói <span class='gd-jp'>明日雨が降っても</span>, không dùng とはいえ.<br>・Vế sau nhất định là nội dung「khác với dự đoán」, thường đi cùng <span class='gd-jp'>まだ</span>, <span class='gd-jp'>やはり</span>. Nó không phải「cho nên」, vế sau không được nói tiếp thuận theo vế trước.<br>・とはいえ mang cảm giác văn viết, trang trọng. Khi nói chuyện với bạn bè, người ta hay nói <span class='gd-jp'>とは言っても</span> hoặc <span class='gd-jp'>って言っても</span> hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>ものの</b> cũng là「tuy ～ nhưng」, nhưng cách dùng tự nhiên nhất là「<b>đã làm một việc gì đó, nhưng kết quả lại không như mong đợi</b>」:<br>・<span class='gd-jp'>チケットを買ったものの、結局行けなかった。</span>（Vé thì mua rồi, nhưng rốt cuộc không đi được）<br>Nếu vế trước là danh từ, ものの phải viết thành「danh từ＋である＋ものの」, nghe khá cứng. Lúc này dùng とはいえ sẽ rất mượt:<br>・<span class='gd-jp'>プロとはいえ、ミスすることもある。</span>（Tuy là dân chuyên nghiệp, cũng có lúc mắc lỗi）</div><div class='gd-sec'><b>にもかかわらず</b> là「mặc dù ～, vậy mà …」, nhấn mạnh kết quả <b>ngoài dự đoán</b>, thường mang giọng ngạc nhiên hoặc trách móc:<br>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（Dù trời mưa, vẫn có rất nhiều người đến）<br>とはいえ không gây cảm giác bất ngờ mạnh như vậy, mà giống như thừa nhận sự thật ở vế trước rồi bình tĩnh bổ sung một câu「Có điều…」.</div><div class='gd-warn'>Mẹo phân biệt: 「Tuy là ～ (thân phận, trạng thái này), nhưng không có nghĩa là…」dùng とはいえ;「Đã làm ～, vậy mà kết quả lại không…」dùng ものの;「Mặc dù ～, thế mà lại còn…」dùng にもかかわらず.</div><div class='gd-h'>Học tiếp sau mẫu này</div><div class='gd-sec'><span class='gd-jp'>とはいうものの</span> có nghĩa gần như y hệt, cũng đặt được ở đầu câu với nghĩa「nói vậy chứ」: <span class='gd-jp'>とはいうものの、やはり心配だ。</span>（Nói vậy chứ, vẫn thấy lo）</div>","n2-13":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜くせに」gần với <b>「rõ ràng là ～ mà lại ～」「đã ～ mà còn ～」</b> trong tiếng Việt, và luôn được nói với giọng bực bội. Khi nghe ai đó nói「<span class='gd-jp'>知ってるくせに</span>」, ý không chỉ là \"rõ ràng biết mà\", mà đằng sau còn có một câu \"bạn quá đáng thật đấy\". Đây không phải câu miêu tả khách quan, mà là để <b>trách móc, nói móc người khác</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ, tính từ い: nối trực tiếp (thì hiện tại hay quá khứ đều được)<br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>知っているくせに</span></span><span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若いくせに</span></span><span class='gd-pair'><span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったくせに</span></span><br>Tính từ な: giữ nguyên <b>な</b> rồi mới nối　<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なくせに</span></span><br>Danh từ: thêm <b>の</b> rồi mới nối　<span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どものくせに</span></span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Trách móc người khác</span>Vế trước nói về điều kiện, hoàn cảnh của đối phương, vế sau nói việc người đó làm thật không ra gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>知っているくせに、教えてくれない。</span>（Rõ ràng biết mà không chịu nói cho mình）</div><div class='gd-ex-line'>・<span class='gd-jp'>行くって言ったくせに、来なかった。</span>（Rõ ràng nói sẽ đi mà rốt cuộc không đến）</div><div class='gd-ex-line'>・<span class='gd-jp'>下手なくせに、いつも自慢する。</span>（Đã dở tệ mà còn lúc nào cũng khoe）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものくせに、生意気なことを言うな。</span>（Con nít mà dám nói mấy câu xấc xược như vậy hả）</div><div class='gd-sec'><span class='gd-tag'>Nói lửng</span>Không nói vế sau, dừng luôn ở くせに, thường mang giọng nũng nịu hoặc châm chọc nhẹ.</div><div class='gd-ex-line'>・<span class='gd-jp'>本当は好きなくせに。</span>（Rõ ràng là thích mà）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な <b>không được nối với だ</b>: phải là <span class='gd-jp'>子どものくせに</span>、<span class='gd-jp'>下手なくせに</span>, chứ không phải 「子どもだくせに」「下手だくせに」.<br>・Hai vế phải nói về <b>cùng một người</b>. \"Anh ấy rõ ràng biết mà <b>anh ấy</b> lại không nói\" thì được; còn nếu chủ ngữ hai vế khác nhau thì không dùng được くせに.<br>・Giọng điệu rất nặng, gần như đang mắng người, nên <b>đừng dùng với cấp trên, khách hàng, người lớn tuổi</b>, cũng không hợp để viết trong văn bản trang trọng.<br>・Phần lớn dùng để trách người khác. Nếu dùng cho bản thân thì thành kiểu tự giễu: <span class='gd-jp'>日本人のくせに、漢字が苦手なんです。</span>（Mình là người Nhật mà lại không giỏi chữ Hán）</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng một tình huống: anh ấy rõ ràng biết đáp án mà không nói cho mình.<br><b>くせに</b>＝bực bội, đang trách anh ấy: <span class='gd-jp'>彼は知っているくせに、教えてくれない。</span><br><b>のに</b>＝cảm thấy bất ngờ, tiếc nuối, giọng trung tính hơn: <span class='gd-jp'>彼は知っているのに、教えてくれない。</span><br><b>にもかかわらず</b>＝trang trọng, văn viết, không mang cảm xúc: <span class='gd-jp'>彼は事情を知っているにもかかわらず、説明しなかった。</span>（Anh ấy rõ ràng nắm được tình hình mà vẫn không giải thích）</div><div class='gd-sec'>のに dùng được trong phạm vi rộng hơn, hai trường hợp sau đây thì くせに đều không dùng được:<br>Chủ ngữ hai vế khác nhau: <span class='gd-jp'>雨なのに、彼は出かけた。</span>（Trời mưa mà anh ấy vẫn ra ngoài）<br>Nói về nuối tiếc của bản thân, không trách ai: <span class='gd-jp'>一生懸命勉強したのに、落ちた。</span>（Mình đã học chăm chỉ như vậy mà vẫn trượt）</div><div class='gd-warn'>Mẹo nhỏ để chọn: muốn <b>trách một người nào đó</b> thì dùng くせに; chỉ thấy <b>tiếc, bất ngờ</b> thì dùng のに; <b>trong hoàn cảnh trang trọng</b> thì viết にもかかわらず.</div>","n2-14":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜一方で」giống như <b>「vừa ……, mặt khác lại ……」</b> trong tiếng Việt. Nó đặt hai việc cạnh nhau cho người nghe thấy: một bên là A, bên kia là B. Báo chí, báo cáo, bài viết rất hay dùng, giọng khá trang trọng.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đối chiếu hai mặt</span>Cùng một việc có mặt tốt và mặt xấu, hoặc tình hình của hai người, hai nơi trái ngược nhau, thì đặt chúng cạnh nhau để so sánh.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は大変な一方で、やりがいもある。</span>（Công việc này vất vả, nhưng mặt khác cũng rất đáng làm）</div><div class='gd-ex-line'>・<span class='gd-jp'>都市部の人口が増える一方で、地方の人口は減っている。</span>（Dân số thành thị tăng lên, trong khi dân số ở địa phương lại giảm）</div><div class='gd-ex-line'>・<span class='gd-jp'>兄はスポーツが得意な一方で、弟は本を読むのが好きだ。</span>（Anh trai giỏi thể thao, còn em trai thì thích đọc sách）</div><div class='gd-sec'><span class='gd-tag'>Làm hai việc cùng lúc</span>Một người làm A và đồng thời cũng làm B. Lúc này không có nghĩa \"trái ngược\", chỉ là nói người đó lo được cả hai bên.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は会社で働く一方で、週末は小説を書いている。</span>（Anh ấy đi làm ở công ty, đồng thời cuối tuần còn viết tiểu thuyết）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中先生は研究を続ける一方で、学生の指導にも力を入れている。</span>（Thầy Tanaka vừa tiếp tục nghiên cứu, vừa dốc sức hướng dẫn sinh viên）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt \"thể thông thường\", tức là cách nói không có ます、です. Động từ, tính từ い nối trực tiếp; <b>tính từ な và danh từ cần chú ý đặc biệt</b>.<br>Động từ: <span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増える一方で</span></span>, thì quá khứ cũng được: <span class='gd-pair'><span class='gd-jp'>伸びた</span> → <span class='gd-jp'>伸びた一方で</span></span><br>Tính từ い: <span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しい一方で</span></span><br>Tính từ な: giữ lại「な」: <span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な一方で</span></span>（cũng có thể nói <span class='gd-jp'>便利である一方で</span>）<br>Danh từ: thêm「である」: <span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生である一方で</span></span><br>「で」có thể lược bỏ, chỉ nói「一方」, nghe còn mang tính văn viết hơn.</div><div class='gd-sec'>Nó cũng có thể đứng riêng ở đầu câu, dùng với nghĩa \"mặt khác\": <span class='gd-jp'>その一方で</span>、<span class='gd-jp'>一方、</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>給料は上がった。その一方で、残業も増えた。</span>（Lương đã tăng. Nhưng mặt khác, giờ làm thêm cũng nhiều hơn）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ な không được nối với だ: nói 「便利だ一方で」 là sai, phải nói <span class='gd-jp'>便利な一方で</span>. Danh từ cũng vậy, không nói 「学生だ一方で」, mà phải nói <span class='gd-jp'>学生である一方で</span>.<br>・Mẫu này rất trang trọng, nếu nói chuyện với bạn bè mà bảo 「仕事は大変な一方で…」 thì nghe như đang đọc thông cáo báo chí. Khi nói chuyện hằng ngày chỉ cần dùng <span class='gd-jp'>けど</span>: <span class='gd-jp'>仕事は大変だけど、楽しいよ。</span>（Công việc mệt thật, nhưng vui lắm đó）<br>・<b>「一方」đặt ở cuối câu thành「一方だ」thì nghĩa hoàn toàn khác</b>, xem phần dưới nhé.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng nói về dân số:<br><b>一方で (ở giữa câu)</b>＝đối chiếu hai bên</div><div class='gd-ex-line'>・<span class='gd-jp'>都市の人口は増える一方で、地方は減っている。</span>（Dân số thành thị đang tăng, mặt khác địa phương lại đang giảm）</div><div class='gd-sec'><b>一方だ (ở cuối câu)</b>＝chỉ biến đổi theo một hướng, cứ thế tiếp diễn</div><div class='gd-ex-line'>・<span class='gd-jp'>都市の人口は増える一方だ。</span>（Dân số thành thị cứ liên tục tăng）</div><div class='gd-sec'>Trước 一方だ chỉ đặt được động từ \"có sự biến đổi\", như <span class='gd-jp'>増える</span>、<span class='gd-jp'>減る</span>、<span class='gd-jp'>悪くなる</span>, và phần lớn là biến đổi theo hướng xấu.</div><div class='gd-sec'><b>ばかりだ (biến đổi)</b> nghĩa gần như giống 一方だ, nhưng nghiêng về \"càng ngày càng tệ\", thường mang cảm giác lo lắng, bất lực.</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなるばかりだ。</span>（Bệnh của bố cứ ngày một nặng thêm）</div><div class='gd-warn'>Mẹo nhỏ để chọn: nếu sau「一方」còn có lời tiếp, đang so sánh hai việc thì là 一方で; nếu「一方」nằm ở cuối câu, câu kết thúc ngay tại đó thì là 一方だ với nghĩa \"cứ ～ mãi\".</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>一方で chỉ đặt hai việc cạnh nhau để so sánh. Nếu muốn nói \"tuy A nhưng kết quả lại B\", với sắc thái chuyển ý kiểu \"khác với dự đoán\", bạn có thể học tiếp <span class='gd-jp'>〜ものの</span>、<span class='gd-jp'>〜にもかかわらず</span>.</div>","n2-20":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に限らず」nghĩa là <b>“không chỉ ～”, “không giới hạn ở ～”</b>. Phía trước bạn đặt một thứ mà ai cũng nghĩ đến đầu tiên, rồi phía sau cho biết: thật ra phạm vi rộng hơn, những thứ khác cũng vậy.<br>Giống như trong tiếng Việt ta nói “Không chỉ cuối tuần, ngày thường cũng đông”, tiếng Nhật sẽ là <span class='gd-jp'>週末に限らず、平日も混んでいる。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt <b>danh từ</b>, rồi nối thẳng với 「に限らず」là được.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生に限らず</span></span>（không chỉ học sinh, sinh viên）<br><span class='gd-pair'><span class='gd-jp'>日本</span> → <span class='gd-jp'>日本に限らず</span></span>（không chỉ Nhật Bản）<br>「限らず」đọc là <b>かぎらず</b>, nghĩa là “không giới hạn ở”. Vế sau thường xuất hiện những từ như <span class='gd-jp'>も</span>、<span class='gd-jp'>誰でも</span>、<span class='gd-jp'>何でも</span> để mở rộng phạm vi.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Phạm vi rộng hơn bạn nghĩ</span>Mọi người tưởng chỉ có A như vậy, nhưng thật ra B, C cũng thế.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は週末に限らず、平日もいつも混んでいる。</span>（Quán này không chỉ cuối tuần, ngày thường cũng lúc nào cũng đông）</div><div class='gd-ex-line'>・<span class='gd-jp'>この公園は子どもに限らず、大人にも人気がある。</span>（Công viên này không chỉ trẻ em, người lớn cũng rất thích）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に限らず、アジア全体で少子化が進んでいる。</span>（Không chỉ Nhật Bản, cả châu Á đều đang giảm tỉ lệ sinh）</div><div class='gd-sec'><span class='gd-tag'>Không giới hạn, ai cũng được</span>Rất hay gặp trong thông báo và phần giới thiệu sự kiện.</div><div class='gd-ex-line'>・<span class='gd-jp'>学生に限らず、誰でも参加できます。</span>（Không giới hạn học sinh, sinh viên, ai cũng có thể tham gia）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Ngược nghĩa với 「に限り」「に限って」</b>：<span class='gd-jp'>本日に限り半額</span> là “chỉ riêng hôm nay giảm nửa giá”, còn <span class='gd-jp'>本日に限らず</span> là “không chỉ hôm nay”. Thêm một chữ 「ず」 là nghĩa đảo ngược hoàn toàn, nên khi đọc thông báo bạn nhớ chú ý nhé.<br>・Phía trước về cơ bản là danh từ, động từ không nối thẳng được: không thể nói 「食べるに限らず」. Nếu muốn nói về hành động, dùng 「〜ばかりでなく」sẽ tự nhiên hơn.<br>・Sắc thái khá trang trọng, thiên về văn viết, hay gặp trong báo chí, thông báo, bài luận. Khi nói chuyện với bạn bè, chỉ cần dùng <span class='gd-jp'>〜だけじゃなくて</span> là đủ.<br>・Phần đặt phía trước nên là “thứ ai cũng nghĩ đến đầu tiên”, phần phía sau mới là “thứ thật ra cũng bao gồm”. Nếu đảo thứ tự, câu sẽ nghe lạ.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>に限らず</b>＝phía trước là <b>một thứ cụ thể</b>, nghĩa là “không chỉ riêng nó”:<br><span class='gd-jp'>学生に限らず、社会人も参加できる。</span>（Không chỉ học sinh, sinh viên, người đi làm cũng có thể tham gia）<br><b>を問わず</b>＝phía trước là <b>một nhóm có thể chia thành nhiều loại</b>, nghĩa là “loại nào cũng vậy”:<br><span class='gd-jp'>このイベントは年齢を問わず、誰でも参加できる。</span>（Sự kiện này bất kể tuổi nào, ai cũng có thể tham gia）<br>「年齢」có thể chia thành nhiều độ tuổi nên dùng を問わず; 「学生」là một nhóm cụ thể nên dùng に限らず.</div><div class='gd-warn'>Mẹo phân biệt: nếu phía trước có thể thay bằng “bất kể ○○ nào” (年齢、性別、国籍、経験、天候) thì dùng を問わず; nếu phía trước là một người/vật/sự việc cụ thể (学生、日本、週末) thì dùng に限らず.</div><div class='gd-sec'><b>とは限らない</b>：cũng có chữ “限”, nhưng nó đứng ở cuối câu và có nghĩa là “<b>không nhất thiết</b>”：<span class='gd-jp'>高い物がいい物とは限らない。</span>（Đồ đắt không nhất thiết là đồ tốt）. Cái này hoàn toàn khác với “không chỉ ～”.</div><div class='gd-sec'>Ngoài ra, <span class='gd-jp'>のみならず</span>、<span class='gd-jp'>ばかりでなく</span> cũng có nghĩa “không chỉ ～, mà còn ～”, khi phía trước là danh từ thì thường có thể thay cho に限らず. Điểm khác là に限らず chỉ nối với danh từ, và trọng tâm nằm ở ý “phạm vi không dừng ở đây”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn hãy học tiếp <span class='gd-jp'>〜を問わず</span>（bất kể ～）, cùng với <span class='gd-jp'>〜のみならず</span>、<span class='gd-jp'>〜ばかりか</span> cũng có nghĩa “không chỉ ～”, thế là bạn nắm trọn cả nhóm “phạm vi” rồi.</div>","n2-21":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜を問わず」nghĩa là <b>“không phân biệt ～”, “bất kể ～”</b>. <span class='gd-jp'>問う</span> là “hỏi, truy cứu”, nên <span class='gd-jp'>問わず</span> là “không đặt vấn đề”. Quảng cáo tuyển dụng viết “không giới hạn tuổi, không yêu cầu kinh nghiệm”, tiếng Nhật chính là <span class='gd-jp'>年齢を問わず</span>、<span class='gd-jp'>経験を問わず</span>. Ý là dù điều kiện này thuộc loại nào, kết quả vẫn như nhau.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Tuyển dụng・thông báo</span>Hay gặp nhất trong tin tuyển người, đăng ký sự kiện, thông báo của cửa hàng, thể hiện ý “điều kiện này không bị giới hạn”.</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢を問わず、どなたでもご参加いただけます。</span>（Bất kể tuổi tác, ai cũng có thể tham gia）</div><div class='gd-ex-line'>・<span class='gd-jp'>このアルバイトは経験を問わず、誰でも応募できます。</span>（Công việc làm thêm này không yêu cầu kinh nghiệm, ai cũng có thể ứng tuyển）</div><div class='gd-sec'><span class='gd-tag'>Miêu tả tình huống</span>Nói rằng một việc không bị điều kiện ảnh hưởng, trường hợp nào cũng đúng.</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌は世代を問わず愛されている。</span>（Bài hát này được yêu thích ở mọi thế hệ）</div><div class='gd-ex-line'>・<span class='gd-jp'>昼夜を問わず、工事の音がうるさい。</span>（Bất kể ngày đêm, tiếng thi công đều ồn ào）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ thêm trực tiếp <span class='gd-jp'>を問わず</span>. Danh từ phía trước có hai loại:<br><b>Từ bản thân đã có nhiều loại</b>：<span class='gd-jp'>年齢</span>、<span class='gd-jp'>性別</span>、<span class='gd-jp'>国籍</span>、<span class='gd-jp'>経験</span>、<span class='gd-jp'>天候</span><br><b>Cặp từ đối lập</b>：<span class='gd-jp'>男女</span>、<span class='gd-jp'>昼夜</span>、<span class='gd-jp'>経験の有無</span>（có hay không có kinh nghiệm）<br>Cũng có thể nối với 「〜かどうか」：<span class='gd-pair'><span class='gd-jp'>経験があるかどうか</span> → <span class='gd-jp'>経験があるかどうかを問わず</span></span></div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>は問いません</span>Đặt ở cuối câu, cực kỳ phổ biến trong quảng cáo tuyển dụng.</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢は問いません。</span>（Không giới hạn tuổi）</div><div class='gd-sec'><span class='gd-tag'>Lược を</span>Trên áp phích, tin tuyển người, để viết cho ngắn gọn, người ta thường viết thành <span class='gd-jp'>年齢問わず</span>、<span class='gd-jp'>経験問わず</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải đặt từ “có nhiều loại khác nhau”. <span class='gd-jp'>学生を問わず</span> không tự nhiên, vì “học sinh, sinh viên” chỉ có một loại, không có gì để “không phân biệt”. Bạn nên nói <span class='gd-jp'>学生かどうかを問わず</span>, hoặc <span class='gd-jp'>学生・社会人を問わず</span>.<br>・「問わず」đọc là <b>とわず</b>, là dạng phủ định của <span class='gd-jp'>問う</span>, đừng viết thành 問えず.<br>・Đây là cách nói rất trang trọng, thiên về văn viết. Khi nói chuyện với bạn bè, dùng <span class='gd-jp'>関係なく</span> sẽ tự nhiên hơn：<span class='gd-jp'>年とか関係なく、誰でも楽しめるよ。</span>（Không cần biết bao nhiêu tuổi, ai chơi cũng vui đó）<br>・Trợ từ cố định là 「を」, đừng đổi thành に hay が.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>に限らず</b>＝<b>không chỉ A, mà B cũng ～</b>（nêu một đại diện, rồi mở rộng phạm vi ra ngoài）：<br><span class='gd-jp'>このアプリは若者に限らず、お年寄りにも人気だ。</span>（App này không chỉ giới trẻ, mà người lớn tuổi cũng rất thích）<br><b>を問わず</b>＝<b>dù A thuộc loại nào cũng như nhau</b>（điều kiện hoàn toàn không được đưa vào xem xét）：<br><span class='gd-jp'>このアプリは年齢を問わず人気だ。</span>（App này được ưa chuộng ở mọi độ tuổi）</div><div class='gd-sec'>Ngoài ra, <span class='gd-jp'>にかかわらず</span> có nghĩa gần như giống を問わず：<span class='gd-jp'>天候にかかわらず実施します。</span>（Dù thời tiết thế nào vẫn tiến hành）<br>Thêm một chữ 「も」 ở giữa thành <b>にもかかわらず</b> thì nghĩa hoàn toàn khác, là “mặc dù ～ nhưng vẫn ～”：<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（Mặc dù trời mưa, vẫn có rất nhiều người đến）</div><div class='gd-warn'>Mẹo phân biệt: “không chỉ A, mà B cũng” dùng に限らず; “dù A là gì” dùng を問わず; “mặc dù A, vẫn” dùng にもかかわらず.</div>","n2-22":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にわたって」chính là kiểu nói quen thuộc trên báo chí tiếng Việt: <b>「kéo dài suốt ~」「trải khắp ~」「liên tục ~」</b>. Ví dụ như \"mưa lớn liên tục ba ngày\", \"mất điện trên diện rộng cả nước\". Trọng tâm là nhấn mạnh <b>thời gian rất dài, phạm vi rất rộng</b>, và là từ đầu đến cuối, bao trọn cả một khoảng hay cả một vùng.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ＋にわたって. Danh từ đứng trước phải là <b>một khoảng dài</b> hoặc <b>cả một vùng rộng</b>. Thường gặp nhất có ba loại:</div><div class='gd-sec'><span class='gd-tag'>Thời gian dài</span>3日間、10年、長年、長期間</div><div class='gd-ex-line'>・<span class='gd-jp'>会議は5時間にわたって続いた。</span>（Cuộc họp kéo dài suốt năm tiếng đồng hồ）</div><div class='gd-sec'><span class='gd-tag'>Phạm vi rộng</span>全国、広範囲、関東全域、多方面</div><div class='gd-ex-line'>・<span class='gd-jp'>台風の影響で、関東全域にわたって大雨が降った。</span>（Do ảnh hưởng của bão, mưa lớn đã đổ xuống khắp vùng Kanto）</div><div class='gd-sec'><span class='gd-tag'>Số lần・khối lượng</span>3回、数ページ</div><div class='gd-ex-line'>・<span class='gd-jp'>この特集は3回にわたって放送されます。</span>（Chuyên đề này sẽ được phát sóng thành ba kỳ）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><b>にわたり</b>: nghĩa giống hệt nhưng mang tính văn viết hơn, thường dùng trong thông cáo báo chí và thông báo.</div><div class='gd-ex-line'>・<span class='gd-jp'>調査は全国にわたり実施された。</span>（Cuộc khảo sát được tiến hành trên khắp cả nước）</div><div class='gd-sec'><b>にわたる＋danh từ</b>: khi phía sau là một danh từ, bạn dùng dạng này.</div><div class='gd-ex-line'>・<span class='gd-jp'>長年にわたる研究の成果が発表された。</span>（Thành quả nghiên cứu suốt nhiều năm đã được công bố）</div><div class='gd-sec'><b>にわたった＋danh từ</b>: dùng cho việc đã kết thúc.</div><div class='gd-ex-line'>・<span class='gd-jp'>2時間にわたった話し合いは、結論が出ないまま終わった。</span>（Cuộc thảo luận kéo dài hai tiếng rốt cuộc kết thúc mà không có kết luận）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước không được đặt <b>một mốc thời gian</b> hay <b>một địa điểm đơn lẻ</b>: không nói được 「3時にわたって」「月曜日にわたって」. Mẫu câu này cần \"một khoảng\" hoặc \"cả một vùng\", ví dụ <span class='gd-jp'>3時間</span>、<span class='gd-jp'>1週間</span>、<span class='gd-jp'>全国</span>.<br>・Nó mang sắc thái \"rất dài, rất rộng\", nên dùng cho chuyện nhỏ nhặt sẽ rất kỳ. <span class='gd-jp'>10分にわたってシャワーを浴びた</span> nghe như đang đưa tin thời sự về chuyện bạn đi tắm vậy.<br>・Giọng văn khá trang trọng, hay xuất hiện trong báo chí, báo cáo, thông báo. Khi nói chuyện với bạn bè, bạn nói <span class='gd-jp'>3日間ずっと雨だった</span> (mưa suốt ba ngày liền) sẽ tự nhiên hơn nhiều.<br>・Khi phía sau nối thẳng với danh từ thì phải dùng <b>にわたる</b>: nói <span class='gd-jp'>3時間にわたる会議</span>, đừng nói 「3時間にわたって会議」.<br>・Mẫu ngữ pháp này bắt nguồn từ động từ <span class='gd-jp'>渡る</span>, thỉnh thoảng bạn sẽ thấy viết là 「に渡って」, nhưng phần lớn người ta viết bằng hiragana.</div><div class='gd-h'>Phân biệt với mẫu giống nhau</div><div class='gd-sec'>Mẫu dễ nhầm nhất là <b>〜にかけて</b>. Cả hai đều nói về phạm vi, nhưng góc nhìn khác nhau.<br><b>にかけて</b>: nói <b>từ đâu đến đâu</b>, đưa ra điểm đầu và điểm cuối, phạm vi chỉ ước chừng.<br><div class='gd-ex-line'>・<span class='gd-jp'>3月から5月にかけて工事が行われる。</span>（Công trình sẽ thi công từ khoảng tháng ba đến tháng năm）</div><b>にわたって</b>: nói <b>tổng cộng dài bao lâu, cả vùng rộng cỡ nào</b>, nhấn mạnh độ dài và độ rộng.<br><div class='gd-ex-line'>・<span class='gd-jp'>3か月にわたって工事が行われる。</span>（Công trình sẽ thi công kéo dài ba tháng）</div>Với địa điểm cũng vậy: <span class='gd-jp'>九州から関西にかけて雨が降る</span>（Từ Kyushu đến vùng Kansai sẽ có mưa）là đang nêu phạm vi; còn <span class='gd-jp'>西日本全域にわたって雨が降る</span>（Mưa sẽ trải khắp toàn bộ miền Tây Nhật Bản）là nhấn mạnh phạm vi rất rộng.</div><div class='gd-warn'>Mẹo phán đoán nhanh: trong câu có hai đầu mút \"A から B\" thì thường dùng にかけて; còn phía trước chỉ có một \"tổng độ dài\" hoặc \"cả một vùng\" như <span class='gd-jp'>3か月</span>、<span class='gd-jp'>全国</span> thì dùng にわたって.</div>","n2-23":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜をもとに」tương đương với <b>「dựa trên ~」「lấy ~ làm nền (để làm ra)」</b>. Phía trước là <b>nguyên liệu, điểm xuất phát</b>, phía sau là <b>thứ mới</b> bạn làm ra từ đó. Ví dụ như \"bộ phim chuyển thể từ câu chuyện có thật\", \"món cà ri nấu theo công thức của bà\" chính là cảm giác này.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phía trước nhất định là <b>danh từ</b>, thêm <span class='gd-jp'>をもとに</span> hoặc <span class='gd-jp'>をもとにして</span>, nghĩa giống nhau, dạng có して thì đầy đủ hơn một chút.<br><span class='gd-pair'><span class='gd-jp'>データ</span> → <span class='gd-jp'>データをもとに</span></span>（dựa trên dữ liệu）<br>Khi phía sau nối thẳng với danh từ, đổi thành <b>をもとにした＋danh từ</b>:<br><span class='gd-pair'><span class='gd-jp'>実話</span> → <span class='gd-jp'>実話をもとにした映画</span></span>（bộ phim dựa trên câu chuyện có thật）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>をもとに＋hành động</span>Phía sau thường là các động từ tạo ra thứ gì đó như \"làm, viết, nghĩ, quyết định, dự đoán\".</div><div class='gd-ex-line'>・<span class='gd-jp'>アンケートの結果をもとに、新しいメニューを考えた。</span>（Dựa trên kết quả khảo sát, mình đã nghĩ ra thực đơn mới）</div><div class='gd-ex-line'>・<span class='gd-jp'>祖母のレシピをもとにして、カレーを作ってみた。</span>（Lấy công thức của bà làm nền, mình đã thử nấu món cà ri）</div><div class='gd-sec'><span class='gd-tag'>をもとに作られた</span>Rất hay gặp khi giới thiệu nguồn gốc của một tác phẩm.</div><div class='gd-ex-line'>・<span class='gd-jp'>このドラマは人気漫画をもとに作られた。</span>（Bộ phim truyền hình này được làm dựa trên một bộ truyện tranh nổi tiếng）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi viết bằng kanji là <span class='gd-jp'>基に</span> hoặc <span class='gd-jp'>元に</span>, đọc là <b>もとに</b>, đừng đọc thành 「きに」. Bình thường viết bằng hiragana cũng hoàn toàn ổn.<br>・Phía trước chỉ đặt được danh từ. Muốn đặt cả một câu thì trước hết dùng 「こと」 biến nó thành danh từ: <span class='gd-jp'>調べたことをもとに、レポートを書いた。</span>（Mình đã viết báo cáo dựa trên những gì đã tra cứu được）<br>・Chữ \"theo\" trong tiếng Việt như \"Theo dự báo thời tiết, ngày mai sẽ mưa\" là để <b>dẫn nguồn tin</b>. Tiếng Nhật không dùng をもとに cho trường hợp này mà dùng <span class='gd-jp'>によると</span>: <span class='gd-jp'>天気予報によると、明日は雨だそうだ。</span><br>・Phía sau phải có hành động hoặc kết quả kiểu \"làm ra / nghĩ ra / quyết định\", còn những câu đơn thuần như \"ở đó\", \"thích\" thì không nối vào được.</div><div class='gd-h'>Phân biệt với mẫu giống nhau</div><div class='gd-sec'><b>をもとに</b> = lấy làm <b>chất liệu, điểm xuất phát</b>, sau đó có thể gia công, mở rộng, chuyển thể:<br><span class='gd-jp'>このデータをもとに、新しい企画を考えた。</span>（Lấy số liệu này làm điểm xuất phát, mình đã nghĩ ra một kế hoạch mới）<br><b>に基づいて</b> = <b>làm đúng theo</b> một căn cứ nào đó, không lệch khỏi nó:<br><span class='gd-jp'>このデータに基づいて、結論を出した。</span>（Căn cứ vào số liệu này, mình đã đưa ra kết luận）<br>Khi nói đến việc phán đoán theo luật pháp, quy tắc thì thường dùng <span class='gd-jp'>法律に基づいて判断する</span> sẽ tự nhiên và trang trọng hơn. をもとに thiên về \"lấy làm nguyên liệu rồi làm ra thứ mới\", dùng với luật pháp, quy tắc thì sắc thái yếu hơn, trong bối cảnh trang trọng nên dùng に基づいて.</div><div class='gd-warn'>Mẹo phán đoán nhanh: kết quả là \"lấy nó làm nền, tạo ra thứ mới\" thì dùng をもとに; kết quả là \"đi theo quy định, bằng chứng của nó\" thì dùng に基づいて.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là mẫu câu \"danh từ＋を＋〜に\", còn có <span class='gd-jp'>をきっかけに</span> mang nghĩa \"nhân dịp ~, lấy ~ làm cơ hội\": <span class='gd-jp'>留学をきっかけに、料理を始めた。</span>（Nhờ đi du học, mình bắt đầu học nấu ăn）. Phía trước là \"khởi đầu của sự việc\", không phải \"nguyên liệu\", bạn có thể đối chiếu để nhớ.</div>","n2-24":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に応じて」nghĩa là <b>「tùy theo ~ mà điều chỉnh」「tùy vào ~」</b>. Giống như chủ quán cơm hộp 「xem số người rồi quyết định đặt bao nhiêu suất」: vế trước thay đổi thì cách làm ở vế sau cũng <b>thay đổi theo, điều chỉnh cho phù hợp</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Gắn thẳng vào sau danh từ: <span class='gd-pair'><span class='gd-jp'>収入</span> → <span class='gd-jp'>収入に応じて</span></span>（tùy theo thu nhập）<br>Danh từ đứng trước thường là thứ <b>khác nhau tùy từng người, từng hoàn cảnh</b>, ví dụ thu nhập, độ tuổi, năng lực, trình độ, ngân sách, tình hình, nhu cầu.<br>Cách đọc là <b>おうじて</b>. Trong văn viết, bạn cũng hay gặp dạng bỏ 「て」 là <span class='gd-jp'>に応じ</span>, nghĩa vẫn y như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>収入に応じて、税金が決まる。</span>（Thuế được quyết định tùy theo thu nhập）</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢に応じて、料金が変わります。</span>（Chi phí thay đổi tùy theo độ tuổi）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>必要に応じて</span>nghĩa là 「tùy theo nhu cầu」, cực kỳ hay gặp trong công ty và thông báo.</div><div class='gd-ex-line'>・<span class='gd-jp'>必要に応じて、資料を追加してください。</span>（Hãy bổ sung tài liệu tùy theo nhu cầu）</div><div class='gd-sec'><span class='gd-tag'>に応じた＋名詞</span>Khi phía sau cần nối với danh từ, bạn dùng dạng này nhiều nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>レベルに応じたクラスを選べます。</span>（Bạn có thể chọn lớp phù hợp với trình độ của mình）</div><div class='gd-sec'>Cũng có cách nói <span class='gd-jp'>に応じての</span>＋danh từ (ví dụ: <span class='gd-jp'>能力に応じての配置</span>), nghĩa giống nhau nhưng ít gặp hơn, nên người mới học chỉ cần nhớ <span class='gd-jp'>に応じた</span> là đủ.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vế sau phải là việc <b>thay đổi, điều chỉnh theo</b> vế trước. Nếu chỉ muốn nói 「theo tin tức thì biết rằng...」 thì không dùng được: <span class='gd-jp'>ニュースによると、明日は雨だ。</span>（Theo bản tin, ngày mai trời sẽ mưa）Ở đây phải dùng によると.<br>・Sắc thái khá trang trọng, hay xuất hiện trong thông báo, hướng dẫn, môi trường công việc. Khi nói chuyện với bạn bè, người ta hay dùng <span class='gd-jp'>に合わせて</span> hoặc <span class='gd-jp'>によって</span> hơn.<br>・Động từ <span class='gd-jp'>応じる</span> khi đứng một mình thường có nghĩa 「đáp lại, đồng ý」: <span class='gd-jp'>インタビューに応じる</span>（nhận lời phỏng vấn）, đừng nhầm với nghĩa 「điều chỉnh theo ~」.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về thu nhập và thuế:<br><b>に応じて</b>＝<b>điều chỉnh cho khớp</b> với vế trước: <span class='gd-jp'>収入に応じて、税金が決まる。</span>（Thuế được quyết định theo thu nhập）<br><b>によって</b>＝<b>tùy vào</b> vế trước mà <b>khác nhau</b>, trọng tâm là 「sự khác biệt」: <span class='gd-jp'>収入によって、税金が違う。</span>（Thuế khác nhau tùy theo thu nhập）<br><b>につれて</b>＝vế trước cứ thay đổi dần thì vế sau cũng <b>từ từ thay đổi theo</b>: <span class='gd-jp'>収入が増えるにつれて、税金も増える。</span>（Thu nhập càng tăng thì thuế cũng tăng theo）</div><div class='gd-sec'>Khi không có ai đang 「điều chỉnh cho khớp」 thì dùng によって sẽ tự nhiên hơn: <span class='gd-jp'>国によって、習慣が違う。</span>（Mỗi nước có phong tục khác nhau）Câu này mà đổi sang に応じて thì nghe rất lạ.</div><div class='gd-warn'>Mẹo phân biệt nhanh: 「điều chỉnh cho phù hợp với nó」 dùng に応じて, 「khác nhau vì nó」 dùng によって, 「càng ~ càng ~」 dùng につれて.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng diễn đạt ý 「thay đổi theo」 còn có <span class='gd-jp'>〜に伴って</span> (cùng với ~) và <span class='gd-jp'>〜につれて</span>, bạn nên đặt chúng cạnh nhau để so sánh.</div>","n2-27":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜のみならず」là phiên bản trang trọng của <b>「không chỉ ~, mà còn…」</b>. Nghĩa giống 「<span class='gd-jp'>だけでなく</span>」 mà bạn đã quen, nhưng mẫu này dùng khi <b>viết báo cáo, tin tức, diễn thuyết</b>, còn nói chuyện với bạn bè thì sẽ không nói thế.<br>Tách ra là hiểu ngay: <span class='gd-jp'>のみ</span>＝<span class='gd-jp'>だけ</span> (chỉ có), <span class='gd-jp'>ならず</span>＝「không phải」, ghép lại thành 「không chỉ là A」.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thêm vào</span>Nói A trước, rồi bổ sung B, và B thường là phạm vi lớn hơn, rộng hơn. Vế sau hay có <b>も、でも、にも</b> để nói 「B cũng vậy」.</div><div class='gd-ex-line'>・<span class='gd-jp'>国内のみならず、海外でも高い評価を得ている。</span>（Không chỉ trong nước, ở nước ngoài cũng được đánh giá cao）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は学生のみならず、社会人にも人気がある。</span>（Quán này không chỉ được học sinh, sinh viên yêu thích mà người đi làm cũng rất thích）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Danh từ</b>: gắn thẳng vào. <span class='gd-pair'><span class='gd-jp'>日本</span> → <span class='gd-jp'>日本のみならず</span></span><br><b>Động từ, tính từ い</b>: dùng thể thường (dạng từ điển, hoặc thể た, thể ない) rồi gắn thẳng vào.<br><span class='gd-pair'><span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるのみならず</span></span><span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いのみならず</span></span><br><b>Tính từ な</b>: phải thêm <b>である</b>, không dùng 「だ」. <span class='gd-pair'><span class='gd-jp'>静かだ</span> → <span class='gd-jp'>静かであるのみならず</span></span><br>Khi muốn nhấn mạnh 「thân phận, tính chất」 của danh từ thì cũng có thể thêm である: <span class='gd-jp'>医者であるのみならず</span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼は英語が話せるのみならず、中国語も読める。</span>（Anh ấy không chỉ nói được tiếng Anh mà còn đọc được cả tiếng Trung）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は狭いのみならず、駅からも遠い。</span>（Căn phòng này không chỉ chật mà còn xa ga）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は静かであるのみならず、交通も便利だ。</span>（Thị trấn này không chỉ yên tĩnh mà giao thông cũng thuận tiện）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ただ〜のみならず</span>Thêm 「ただ」 phía trước thành 「không đơn thuần chỉ là ~」, sắc thái mạnh hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>これはただ個人の問題のみならず、社会全体の問題でもある。</span>（Đây không đơn thuần là vấn đề của cá nhân mà còn là vấn đề của toàn xã hội）</div><div class='gd-sec'><span class='gd-tag'>Đặt ở đầu câu</span>Dùng riêng như một liên từ, nghĩa là 「không chỉ vậy」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は仕事が速い。のみならず、ミスもほとんどない。</span>（Anh ấy làm việc rất nhanh. Không chỉ vậy, anh ấy còn hầu như không mắc lỗi）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Với tính từ な không nói <span class='gd-jp'>静かだのみならず</span>, phải nói <span class='gd-jp'>静かであるのみならず</span>.<br>・Mẫu này rất cứng, rất trang trọng. Khi nói với bạn bè 「không chỉ ~」 hãy dùng <span class='gd-jp'>だけじゃなく</span>, dùng のみならず nghe sẽ như đang đọc công văn.<br>・Nó là kiểu <b>cộng thêm lên</b>, không phải 「không phải A mà là B」. Hai vế phải tương xứng: A là địa điểm thì B cũng phải là địa điểm; A là vấn đề thì B cũng phải là vấn đề. Nhớ bổ sung 「も」 ở vế sau.<br>・Hướng của hai vế phải giống nhau: tốt nối với tốt, xấu nối với xấu. Không dùng để nói hai điều trái ngược.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng một tình huống: trò chơi này cả người lớn lẫn trẻ em đều thích chơi.<br><b>だけでなく</b>＝cách nói thông dụng nhất, dùng được cả khi nói lẫn khi viết: <span class='gd-jp'>このゲームは子どもだけでなく、大人にも人気がある。</span><br><b>のみならず</b>＝nghĩa giống hệt, chỉ chuyển sang giọng trang trọng, văn viết: <span class='gd-jp'>このゲームは子どものみならず、大人にも人気がある。</span><br><b>ばかりか</b>＝mang chút bất ngờ kiểu 「không ngờ đến cả ~ cũng」: <span class='gd-jp'>このゲームは子どもばかりか、大人まで夢中になっている。</span>（Không chỉ trẻ em, đến cả người lớn cũng mê mẩn）<br><b>に限らず</b>＝trọng tâm là 「không giới hạn trong phạm vi A」, vế sau hay đi với <span class='gd-jp'>誰でも</span>, <span class='gd-jp'>どこでも</span>: <span class='gd-jp'>このゲームは子どもに限らず、誰でも楽しめる。</span>（Trò chơi này không giới hạn ở trẻ em, ai cũng có thể chơi vui vẻ）</div><div class='gd-warn'>Mẹo phân biệt nhanh: nói chuyện thường ngày dùng だけじゃなく, viết văn dùng のみならず; muốn thể hiện sự bất ngờ kiểu 「đến cả ~ cũng」 dùng ばかりか; muốn nói 「không giới hạn, ai cũng được」 dùng に限らず.</div>","n2-28":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AはもちろんBも」tương đương với <b>「A thì khỏi phải nói rồi, đến cả B cũng ～」</b> trong tiếng Việt. A là điều ai cũng nghĩ tới, hiển nhiên rồi. B là điều được thêm vào sau, hơi bất ngờ hơn một chút.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は味はもちろん、サービスもいい。</span>(Quán này vị ngon thì khỏi nói rồi, phục vụ cũng tốt)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Về cơ bản, bạn gắn「はもちろん」trực tiếp vào danh từ. Vế sau thường dùng <b>も</b> hoặc <b>まで</b> để đáp lại:<br><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供はもちろん、大人も</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子供はもちろん、大人も楽しめる映画です。</span>(Trẻ em thì khỏi nói rồi, người lớn cũng xem vui vẻ được)</div><div class='gd-ex-line'>・<span class='gd-jp'>家具はもちろん、家電までついている部屋だ。</span>(Nội thất thì khỏi nói rồi, đến cả đồ điện gia dụng cũng có sẵn trong phòng)</div><div class='gd-sec'>Nếu sau danh từ có trợ từ nhỏ như「で」「に」, bạn cứ giữ nguyên rồi thêm「はもちろん」:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本ではもちろん、海外でも人気がある。</span>(Ở Nhật thì khỏi nói rồi, ở nước ngoài cũng được yêu thích)</div><div class='gd-sec'>Muốn nói về một hành động, bạn thêm「の」sau động từ để biến nó thành danh từ:</div><div class='gd-ex-line'>・<span class='gd-jp'>話すのはもちろん、書くのも得意だ。</span>(Nói thì khỏi phải bàn, viết cũng giỏi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Đừng đảo thứ tự</b>: vế đầu là điều \"vốn dĩ đương nhiên\". Nhắc đến công viên giải trí, mọi người sẽ nghĩ đến trẻ em trước, nên nói <span class='gd-jp'>子供はもちろん、大人も</span> nghe thuận hơn.<br>・<b>Khi cuối câu là phủ định, vế trước phải là điều \"khó\"</b>: <span class='gd-jp'>漢字はもちろん、ひらがなも書けない。</span>(Chữ Hán thì khỏi nói, đến cả Hiragana cũng không viết được) Không viết được chữ Hán là chuyện bình thường, còn đến Hiragana đơn giản cũng không viết được mới là điểm nhấn.<br>・Nhớ thêm <b>も</b> hoặc <b>まで</b> ở vế sau. <span class='gd-jp'>英語はもちろん、スペイン語が話せる</span> mà thiếu も thì nghe sẽ vấp, không tự nhiên.<br>・Khác với「もちろん」đứng một mình (đương nhiên): <span class='gd-jp'>もちろん行きます</span> nghĩa là \"tất nhiên tôi sẽ đi\", không có nghĩa \"A khỏi nói, đến cả B cũng\".</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cả ba mẫu đều có thể dịch là \"không chỉ A mà B cũng ～\". Hãy so sánh qua cùng một câu:<br><b>はもちろん</b> = A vốn đã là chuyện đương nhiên: <span class='gd-jp'>彼は英語はもちろん、中国語も話せる。</span>(Tiếng Anh thì khỏi nói rồi, anh ấy còn nói được cả tiếng Trung)<br><b>ばかりか</b> = trọng tâm là B khiến người ta hơi bất ngờ: <span class='gd-jp'>彼は英語ばかりか、中国語も話せる。</span>(Anh ấy không chỉ biết tiếng Anh, mà còn nói được cả tiếng Trung, thật bất ngờ)<br><b>のみならず</b> = nghĩa gần giống ばかりか nhưng rất trang trọng, hay dùng trong văn viết hoặc bài phát biểu: <span class='gd-jp'>彼は英語のみならず、中国語も話せる。</span></div><div class='gd-sec'>Còn một điểm khác biệt thực tế nữa: sau <b>はもちろん</b> có thể nối những vế nhờ vả hoặc quyết định như \"xin hãy ～\", \"tôi sẽ ～\", còn <b>ばかりか</b> thì hầu như không dùng như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>準備はもちろん、片付けも手伝ってください。</span>(Chuẩn bị thì khỏi nói rồi, dọn dẹp cũng xin hãy giúp)</div><div class='gd-warn'>Mẹo phân biệt nhanh: muốn nói \"A thì khỏi nói\" thì dùng はもちろん. Muốn nhấn mạnh \"đến cả B cũng, bất ngờ thật\" thì dùng ばかりか. Chỉ khi viết văn trang trọng mới dùng のみならず.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜はもちろんのこと」có nghĩa giống hệt, chỉ nhấn mạnh hơn một chút. Trong văn viết, bạn hay gặp dạng trang trọng hơn là <span class='gd-jp'>〜はもとより</span>: <span class='gd-jp'>国内はもとより、海外からも注文が来る。</span>(Trong nước thì khỏi nói rồi, đến cả nước ngoài cũng có đơn đặt hàng)</div>","n2-30":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜だけのことはある」tương đương với <b>「Đúng là ～」「Quả không hổ là ～」「Thảo nào ～」</b> trong tiếng Việt. Bạn thấy một kết quả rất ấn tượng rồi quay lại nhận xét: ừ, điều này khớp hoàn toàn với thân phận, số tiền bỏ ra hay công sức của họ, quả là <b>danh bất hư truyền</b>.</div><div class='gd-sec'><span class='gd-jp'>だけ</span> ở đây không có nghĩa là \"chỉ\". Cảm giác của cả câu là: \"Họ là ～ thì có thực lực tương xứng, quả đúng như vậy.\"</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Xứng với thân phận</span>Chuyên gia, quán nổi tiếng, người nổi tiếng thể hiện tốt đúng như danh tiếng.</div><div class='gd-ex-line'>・<span class='gd-jp'>さすがプロだけのことはある。</span>(Đúng là dân chuyên nghiệp có khác)</div><div class='gd-ex-line'>・<span class='gd-jp'>英語がペラペラだ。5年もアメリカに住んでいただけのことはある。</span>(Tiếng Anh trôi chảy quá, quả không hổ là từng sống ở Mỹ tận năm năm)</div><div class='gd-sec'><span class='gd-tag'>Tiền bỏ ra xứng đáng</span>Giống câu \"tiền nào của nấy\" trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>このいす、全然疲れない。高かっただけのことはある。</span>(Cái ghế này ngồi bao lâu cũng không mệt. Đắt cũng có lý do của nó)</div><div class='gd-sec'><span class='gd-tag'>Thảo nào được yêu thích</span>Sau khi tự trải nghiệm, bạn thấy đánh giá của mọi người đúng thật.</div><div class='gd-ex-line'>・<span class='gd-jp'>このパン、本当においしい。行列ができるだけのことはあるね。</span>(Bánh mì này ngon thật. Thảo nào người ta xếp hàng dài)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: nối trực tiếp với thể thông thường　<span class='gd-pair'><span class='gd-jp'>練習した</span> → <span class='gd-jp'>練習しただけのことはある</span></span><br><b>Tính từ đuôi い</b>: nối trực tiếp　<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いだけのことはある</span></span><br><b>Tính từ đuôi な</b>: phải giữ「な」　<span class='gd-pair'><span class='gd-jp'>有名</span> → <span class='gd-jp'>有名なだけのことはある</span></span><br><b>Danh từ</b>: nối trực tiếp, không thêm だ　<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロだけのことはある</span></span><br>Muốn nói lịch sự hơn thì dùng <span class='gd-jp'>だけのことはありますね</span>.</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'>Phía trước thường có <span class='gd-jp'>さすが</span>, dùng cùng nhau thì sắc thái \"quả không hổ là\" đậm hơn. Thứ tự thường gặp là <b>nói kết quả đã thấy trước, rồi thêm một câu だけのことはある</b> làm kết luận.</div><div class='gd-ex-line'>・<span class='gd-jp'>景色が最高だ。さすが有名なだけのことはある。</span>(Phong cảnh tuyệt vời. Quả không hổ là nơi nổi tiếng)</div><div class='gd-sec'>Với việc đã có kết quả, bạn cũng có thể dùng thể quá khứ「あった」, thường dùng để nói nỗ lực đã được đền đáp.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できた。毎日勉強しただけのことはあった。</span>(Đỗ rồi. Ngày nào cũng học, quả là không uổng công)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Thấy <span class='gd-jp'>だけ</span> là dịch thành \"chỉ\" thì cả câu sẽ hoàn toàn khó hiểu. Ở đây nghĩa là \"quả không hổ, xứng với danh tiếng\".<br>・Sau danh từ đừng thêm だ: nói <span class='gd-jp'>プロだけのことはある</span>, không nói プロだだけのことはある.<br>・Tính từ đuôi な phải giữ「な」: nói <span class='gd-jp'>有名なだけのことはある</span>, không nói 有名だけのことはある.<br>・Nhất định phải có <b>kết quả thực tế đã thấy</b> làm bằng chứng. Việc chưa xảy ra, chỉ là phỏng đoán thì không dùng được.<br>・Người mới học nên nhớ trước: đây là lời <b>khen, đồng tình</b>. Muốn than phiền đồ dở thì tạm thời đừng dùng.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>だけあって</b>: cũng có nghĩa \"quả không hổ là\", nhưng đứng <b>giữa câu</b>, phía sau nối thẳng kết quả, nói gọn trong một câu.<br>・<span class='gd-jp'>さすがプロだけあって、写真がきれいだ。</span>(Quả không hổ là dân chuyên nghiệp, ảnh chụp rất đẹp)<br><b>だけのことはある</b>: đứng <b>cuối câu</b>, làm kết luận sau cùng.<br>・<span class='gd-jp'>写真がきれいだ。さすがプロだけのことはある。</span>(Ảnh đẹp quá. Đúng là dân chuyên nghiệp có khác)</div><div class='gd-sec'><b>ことだから</b>: cũng liên quan đến tính cách, thực lực của một người, nhưng đây là <b>phỏng đoán khi kết quả chưa có</b>. Cách nối là danh từ + の + ことだから.<br>・<span class='gd-jp'>田中さんのことだから、きっと今回も合格するよ。</span>(Người như anh Tanaka thì lần này chắc chắn cũng đỗ thôi)<br>・<span class='gd-jp'>一回で合格した。さすが田中さんだけのことはある。</span>(Đỗ ngay lần đầu. Quả không hổ là anh Tanaka)</div><div class='gd-warn'>Mẹo phân biệt nhanh: kết quả chưa có, đang đoán thì dùng ことだから. Kết quả đã có, đang cảm thán thì dùng だけのことはある. Muốn nói tiếp kết quả ngay trong cùng một câu thì đổi sang だけあって.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><span class='gd-jp'>〜に値する</span> (đáng để ～) cũng là một mẫu đánh giá tích cực, ví dụ <span class='gd-jp'>この映画は見るに値する。</span>(Bộ phim này đáng xem).</div>","n2-16":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜つつも」có nghĩa là <b>“biết rõ ～ mà vẫn ～”, “trong lòng nghĩ ～ nhưng rốt cuộc vẫn ～”</b>. Giống như “biết thức khuya hại sức khỏe mà vẫn lướt điện thoại đến 3 giờ sáng”, tức là cảm giác <b>trong đầu biết rồi nhưng hành động lại không theo kịp</b>. Mẫu này thiên về <b>văn viết</b>, hay gặp trong bài viết, tin tức và những dịp trang trọng.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Lấy thể ます của động từ, bỏ ます rồi thêm つつ（も）.<br><span class='gd-pair'><span class='gd-jp'>思う</span> → <span class='gd-jp'>思います</span> → <span class='gd-jp'>思いつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>知る</span> → <span class='gd-jp'>知ります</span> → <span class='gd-jp'>知りつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言います</span> → <span class='gd-jp'>言いつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span> → <span class='gd-jp'>しつつ</span></span><br>Chỉ nối được với <b>động từ</b>, tính từ và danh từ thì không nối trực tiếp được.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Tuy ～ nhưng ～</span>Vế trước là suy nghĩ trong lòng, vế sau là hành động trái với suy nghĩ đó. Hay gặp nhất là「<span class='gd-jp'>〜と知りつつ</span>」「<span class='gd-jp'>〜と思いつつ</span>」「<span class='gd-jp'>〜と言いつつ</span>」. Phía sau thường có <span class='gd-jp'>てしまう</span>, <span class='gd-jp'>られない</span>, mang chút hối tiếc hoặc cảm giác không làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>体に悪いと知りつつも、夜更かしがやめられない。</span>（Biết là có hại cho sức khỏe mà vẫn không bỏ được thói thức khuya）</div><div class='gd-ex-line'>・<span class='gd-jp'>早く返事をしなきゃと思いつつ、一週間たってしまった。</span>（Cứ nghĩ phải trả lời sớm, thế mà một tuần đã trôi qua）</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエット中だと言いつつ、ケーキを二つも食べた。</span>（Miệng thì nói đang ăn kiêng, vậy mà ăn tới hai cái bánh kem）</div><div class='gd-sec'><span class='gd-tag'>Vừa ～ vừa ～</span>「つつ」không có「も」còn một nghĩa khác: hai việc diễn ra cùng lúc, là phiên bản văn viết của「ながら」.</div><div class='gd-ex-line'>・<span class='gd-jp'>景色を楽しみつつ、山道を歩いた。</span>（Vừa ngắm cảnh vừa đi bộ trên đường núi）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの意見を聞きつつ、計画を進めていきます。</span>（Chúng tôi sẽ vừa lắng nghe ý kiến của mọi người vừa thúc đẩy kế hoạch）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải nối với thể ます, không phải thể từ điển: <span class='gd-jp'>知りつつ</span> mới đúng, không thể nói「知るつつ」.<br>・Chủ thể trước và sau phải là <b>cùng một người</b>. “Mẹ phản đối nhưng tôi vẫn đi du học” là hai người khác nhau nên không dùng được つつ, phải nói <span class='gd-jp'>母は反対したが、私は留学した。</span><br>・Khi có「も」thì chắc chắn là nghĩa “tuy ～ nhưng ～”; còn chỉ có「つつ」thì phải dựa vào ngữ cảnh để biết là “tuy” hay “vừa… vừa…”.<br>・Mẫu này thiên về văn viết, nói chuyện với bạn bè thường dùng「<span class='gd-jp'>〜けど</span>」「<span class='gd-jp'>〜のに</span>」là đủ. Tuy nhiên các cách nói cố định như「<span class='gd-jp'>〜と思いつつ</span>」「<span class='gd-jp'>〜と知りつつ</span>」thì văn nói cũng nghe được.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>つつも và ながらも</b>: nghĩa gần như giống nhau, trong cùng một câu thường thay được cho nhau.<br><span class='gd-jp'>悪いと知りつつも、やってしまった。</span><br><span class='gd-jp'>悪いと知りながらも、やってしまった。</span>（Biết là không đúng mà vẫn làm）<br>Khác nhau ở chỗ: つつも <b>chỉ nối được với động từ</b>, giọng văn viết hơn; còn ながらも nối được cả tính từ và danh từ, ví dụ <span class='gd-jp'>狭いながらも楽しい我が家</span>（tuy nhỏ nhưng là mái ấm vui vẻ）, câu này không thể đổi sang つつも.</div><div class='gd-sec'><b>つつも và つつある</b>: chỉ khác nhau một chữ nhưng nghĩa hoàn toàn khác. つつある là “đang dần trở nên ～”, không có nghĩa “tuy”.<br><span class='gd-jp'>景気は回復しつつある。</span>（Kinh tế đang dần phục hồi）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: “biết ～ mà vẫn ～” dùng つつも; nếu phía trước là tính từ hay danh từ thì đổi sang ながらも; thấy つつある thì nghĩ đến “đang dần thay đổi”.</div>","n2-17":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ながら（も）」ở đây có nghĩa là <b>“tuy ～ nhưng ～”, “rõ ràng ～ mà lại ～”</b>. Vế trước nêu một tình huống, vế sau là một kết quả mà “lẽ ra không nên như vậy”.<br>Ở N4 bạn đã học「<span class='gd-jp'>音楽を聞きながら勉強する</span>」（vừa nghe nhạc vừa học), đó là <b>làm hai việc cùng lúc</b>. Ở đây hình thức giống hệt nhưng nghĩa hoàn toàn khác.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: dùng thể ます, bỏ ます rồi thêm ながら. Dạng hay gặp nhất là「〜ている」.<br><span class='gd-pair'><span class='gd-jp'>住んでいます</span> → <span class='gd-jp'>住んでいながら</span></span><span class='gd-pair'><span class='gd-jp'>知ります</span> → <span class='gd-jp'>知りながら</span></span><br><b>Tính từ い</b>: nối trực tiếp, giữ nguyên い. <span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いながら</span></span><br><b>Tính từ な</b>: bỏ な rồi nối. <span class='gd-pair'><span class='gd-jp'>残念な</span> → <span class='gd-jp'>残念ながら</span></span><br><b>Danh từ</b>: nối trực tiếp. <span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもながら</span></span><br>Thêm「も」phía sau thành「ながらも」, nghĩa vẫn vậy nhưng cảm giác “tuy” mạnh hơn một chút.</div><div class='gd-ex-line'>・<span class='gd-jp'>近くに住んでいながら、一度も行ったことがない。</span>（Rõ ràng sống ở gần đó mà chưa đi lần nào）</div><div class='gd-ex-line'>・<span class='gd-jp'>悪いと知りながら、うそをついてしまった。</span>（Biết là không đúng mà vẫn nói dối）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は学生ながら、自分で会社を経営している。</span>（Anh ấy tuy vẫn là sinh viên nhưng đang tự điều hành công ty）</div><div class='gd-ex-line'>・<span class='gd-jp'>狭いながらも、住み心地のいい部屋だ。</span>（Tuy nhỏ nhưng là căn phòng ở rất dễ chịu）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'>Có vài cụm đã thành cách nói cố định, trong đời sống và công việc đều hay nghe. Học thuộc cả câu là nhanh nhất.</div><div class='gd-sec'><span class='gd-tag'>残念ながら</span>Rất tiếc, thường dùng khi thông báo tin xấu.</div><div class='gd-ex-line'>・<span class='gd-jp'>残念ながら、明日の試合は中止になりました。</span>（Rất tiếc, trận đấu ngày mai đã bị hủy）</div><div class='gd-sec'><span class='gd-tag'>勝手ながら</span>Hay thấy trong thông báo của cửa hàng, nghĩa là “xin phép được tự ý ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>勝手ながら、本日は休業させていただきます。</span>（Chúng tôi xin phép tạm nghỉ bán trong hôm nay）</div><div class='gd-sec'><span class='gd-tag'>陰ながら</span>Âm thầm ở phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>陰ながら応援しています。</span>（Mình sẽ âm thầm cổ vũ bạn）</div><div class='gd-sec'><span class='gd-tag'>我ながら</span>Ngay cả bản thân mình cũng thấy.</div><div class='gd-ex-line'>・<span class='gd-jp'>我ながらよくできたと思う。</span>（Ngay cả bản thân mình cũng thấy làm khá tốt）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đừng thêm bớt linh tinh khi nối: là <span class='gd-jp'>狭いながら</span>, không phải 狭くながら; là <span class='gd-jp'>残念ながら</span>, không phải 残念なながら; là <span class='gd-jp'>子どもながら</span>, không phải 子どものながら.<br>・Ngoài các cách nói cố định ở trên, mẫu này <b>thiên về văn viết, trang trọng</b>, dùng trong bài viết, tin tức, phỏng vấn. Khi nói chuyện với bạn bè thì nói「<span class='gd-jp'>狭いけど、いい部屋だよ</span>」sẽ tự nhiên hơn.<br>・<span class='gd-jp'>昔ながらの</span>, <span class='gd-jp'>生まれながらの</span> không mang nghĩa “tuy”: <span class='gd-jp'>昔ながらの町並み</span> là “con phố còn giữ nguyên dáng vẻ xưa”, <span class='gd-jp'>生まれながらの才能</span> là “tài năng bẩm sinh”, cần nhớ riêng.<br>・Vế trước và vế sau thường nói về <b>cùng một người hoặc cùng một việc</b>, ví dụ “anh ấy tuy là sinh viên nhưng (anh ấy) lại mở công ty”.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>ながら chỉ sự đồng thời</b> = vừa ～ vừa ～: <span class='gd-jp'>テレビを見ながらご飯を食べる。</span>（Vừa xem tivi vừa ăn cơm）<br><b>ながら chỉ sự đối lập</b> = rõ ràng ～ mà lại ～: <span class='gd-jp'>毎日テレビを見ていながら、そのニュースを知らなかった。</span>（Ngày nào cũng xem tivi mà lại không biết tin đó）</div><div class='gd-sec'><b>つつ（も）</b>: nghĩa gần như giống ながら（も） chỉ sự đối lập, nhưng mang tính văn viết hơn và <b>chỉ nối được với động từ</b>.<br><span class='gd-jp'>悪いと知りつつも、うそをついてしまった。</span>（Biết là không đúng mà vẫn nói dối）<br>Tính từ và danh từ thì không dùng được: phải nói <span class='gd-jp'>狭いながらも</span>, không thể nói 狭いつつも.</div><div class='gd-sec'><b>くせに</b>: cũng là “rõ ràng ～ mà”, nhưng mang sắc thái <b>trách móc, bất mãn</b>, là lời phàn nàn trong văn nói.<br><span class='gd-jp'>知っているくせに、教えてくれない。</span>（Rõ ràng biết mà còn không chịu nói cho mình!）<br><span class='gd-jp'>知っていながら、教えてくれなかった。</span>（Rõ ràng biết mà lại không nói cho mình: nghe giống lời kể bình tĩnh hơn）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nếu phía trước là tính từ, danh từ, hoặc phía sau có「も」thì là nghĩa “tuy”; nếu phía trước là động từ, hãy xem vế sau có “trái với dự đoán” không: có thì là “tuy”, không thì là “vừa ～ vừa ～”. Muốn phàn nàn với đối phương thì dùng くせに, viết văn thì dùng ながら hoặc つつ.</div>","n2-31":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に値する」chính là <b>「đáng ～」</b> trong tiếng Việt, nhưng mang sắc thái trang trọng, thiên về văn viết. Báo chí viết \"phát hiện này đáng chú ý\", bài bình sách viết \"cuốn sách này đáng đọc một lần\", và tiếng Nhật sẽ dùng mẫu này. Nghĩa của nó là: người hoặc việc này <b>xứng đáng, có giá trị đó</b>, xứng với lời đánh giá như vậy.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋に値する：<span class='gd-pair'><span class='gd-jp'>尊敬</span> → <span class='gd-jp'>尊敬に値する</span></span>（đáng tôn trọng）<br>Động từ thể từ điển (dạng gốc tra trong từ điển)＋に値する：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むに値する</span></span>（đáng đọc）<br><span class='gd-jp'>値する</span> đọc là <b>あたいする</b>, bản thân nó là một động từ, chia giống <span class='gd-jp'>する</span>：<span class='gd-jp'>値しない</span>、<span class='gd-jp'>値します</span>.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Đánh giá tích cực</span>Những từ hay đứng trước nhất là: <span class='gd-jp'>尊敬</span>、<span class='gd-jp'>称賛</span>、<span class='gd-jp'>信頼</span>、<span class='gd-jp'>注目</span>、<span class='gd-jp'>一読</span>、<span class='gd-jp'>検討</span>、<span class='gd-jp'>特筆</span>. Bạn cứ nhớ chúng như những cụm đi liền nhau cố định là được.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の努力は称賛に値する。</span>（Nỗ lực của anh ấy đáng được khen ngợi）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は一読に値する。</span>（Cuốn sách này đáng đọc một lần）</div><div class='gd-ex-line'>・<span class='gd-jp'>このデータは注目に値する。</span>（Số liệu này đáng chú ý）</div><div class='gd-sec'><span class='gd-tag'>Phủ định: không đáng</span>Chuyển thành <span class='gd-jp'>値しない</span> thì giọng khá phũ, gần như nói \"chẳng đáng để bận tâm\".</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな噂は信じるに値しない。</span>（Tin đồn như thế không đáng tin）</div><div class='gd-ex-line'>・<span class='gd-jp'>その意見は検討に値しない。</span>（Ý kiến đó không đáng để xem xét）</div><div class='gd-sec'><span class='gd-tag'>Đặt trước danh từ</span>Dùng trực tiếp để bổ nghĩa cho người hoặc vật.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は信頼に値する人物だ。</span>（Anh ấy là người đáng tin cậy）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trợ từ luôn dùng <b>に</b>: phải là <span class='gd-jp'>尊敬に値する</span>, không phải 尊敬を値する.<br>・Đọc là <b>あたいする</b>. Chữ 「値」 trong <span class='gd-jp'>値段</span> đọc là ね, đừng đọc lẫn.<br>・Phía trước không được dùng thể ます: không thể nói 「読みますに値する」. Muốn nói lịch sự thì đổi phần cuối: <span class='gd-jp'>読むに値します</span>.<br>・Mẫu này khá cứng, mang tính văn viết. Khi nói chuyện với bạn bè, muốn nói \"tô ramen này đáng ăn\" thì cứ dùng <span class='gd-jp'>このラーメン、食べる価値あるよ</span>; nói 食べるに値する nghe cứ như đang viết bài review ẩm thực vậy.<br>・Trong tiếng Việt, \"đáng tiền\", \"hời quá\" thường nói về chuyện được giá, ví dụ \"giảm giá rồi thì quá hời\". Ý này tiếng Nhật dùng <span class='gd-jp'>お得</span>, không dùng に値する.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>価値がある</b>: nghĩa gần như giống に値する, nhưng dùng được cả trong đời thường lẫn văn viết, là cách nói phổ biến nhất.<br><span class='gd-jp'>この本は読む価値がある。</span>（Cuốn sách này đáng đọc: nói chuyện hằng ngày cũng dùng được）<br><span class='gd-jp'>この本は一読に値する。</span>（Cuốn sách này đáng đọc một lần: dùng trong bài bình sách, hoàn cảnh trang trọng）</div><div class='gd-sec'><b>だけのことはある</b>: cũng là để khen, nhưng trọng tâm là「<b>đúng là ～, thảo nào ～</b>」, cho thấy kết quả xứng với xuất thân và công sức bỏ ra. Cùng một tình huống, sau khi nghe một buổi biểu diễn piano:<br><span class='gd-jp'>彼の演奏は称賛に値する。</span>（Phần biểu diễn của anh ấy đáng được khen ngợi: nói rằng buổi biểu diễn xứng đáng được khen）<br><span class='gd-jp'>さすが十年ウィーンで学んだだけのことはある。</span>（Đúng là người đã học mười năm ở Vienna có khác: nói rằng kết quả tốt xứng với quá trình của anh ấy）</div><div class='gd-warn'>Mẹo phân biệt: muốn nói \"đáng ～\" thì hoàn cảnh trang trọng dùng に値する, nói chuyện thường ngày dùng 価値がある; muốn nói \"đúng là ～, thảo nào ～\" thì dùng だけのことはある.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜に足る」ở N1 có nghĩa rất gần, là \"đủ để ～, xứng để ～\": <span class='gd-jp'>信頼に足る人物</span>（người đủ để tin cậy）.</div>","n2-32":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜上は」chính là <b>「đã ～ rồi thì (phải) ～」</b> trong tiếng Việt. Phía trước đặt một việc đã chắc chắn, ví dụ thân phận của bạn, quyết định bạn đã đưa ra, hay tình thế sự việc đã đi đến; phía sau nói \"vì vậy tôi sẽ / nên làm thế nào\". Giọng điệu giống câu \"đã hứa rồi thì phải làm cho được\" của tiếng Việt, chỉ là nghe <b>trang trọng và cứng hơn</b>, thường mang cảm giác đã hạ quyết tâm.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Trách nhiệm đi kèm thân phận</span>Đã mang thân phận này thì phải làm tròn việc cần làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>教師である上は、生徒の手本にならなければならない。</span>（Đã là giáo viên thì phải làm tấm gương cho học sinh）</div><div class='gd-sec'><span class='gd-tag'>Đã làm thì phải chịu trách nhiệm</span>Đã nhận lời, đã quyết định thì phải làm đến cùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた上は、最後まで責任を持ちます。</span>（Đã nhận rồi thì tôi sẽ chịu trách nhiệm đến cùng）</div><div class='gd-ex-line'>・<span class='gd-jp'>やると決めた上は、もう迷わない。</span>（Đã quyết định làm thì sẽ không phân vân nữa）</div><div class='gd-sec'><span class='gd-tag'>Đã đến nước này</span>Sự việc đã thành ra thế này thì đành phải đối mặt.</div><div class='gd-ex-line'>・<span class='gd-jp'>こうなった上は、正直に話すしかない。</span>（Đã đến nước này thì chỉ còn cách nói thật）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: thể từ điển hoặc thể た, thêm は trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>試合に出る</span> → <span class='gd-jp'>試合に出る上は</span></span>（đã ra thi đấu thì）<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した上は</span></span>（đã hứa rồi thì）<br><b>Danh từ</b>: ở giữa phải thêm「である」.<br><span class='gd-pair'><span class='gd-jp'>社会人</span> → <span class='gd-jp'>社会人である上は</span></span>（đã là người đi làm thì）</div><div class='gd-h'>Vế sau nên nối với gì</div><div class='gd-sec'>Vế sau phải là <b>quyết tâm, nghĩa vụ, lời khuyên hoặc phán đoán của bạn</b>. Các kiểu kết câu hay gặp nhất:<br><span class='gd-jp'>〜なければならない</span>（phải）、<span class='gd-jp'>〜べきだ</span>（nên）、<span class='gd-jp'>〜しかない</span>（chỉ còn cách）、<span class='gd-jp'>〜つもりだ</span>（định）、<span class='gd-jp'>〜たい</span>（muốn）.</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に出る上は、絶対に勝ちたい。</span>（Đã ra thi đấu thì nhất định muốn thắng）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đọc là <b>うえは</b>, không phải じょうは.<br>・Danh từ không nối trực tiếp được: phải là <span class='gd-jp'>学生である上は</span>, không thể nói 「学生だ上は」.<br>・Vế trước phải là việc <b>đã chắc chắn</b>, không phải giả định. Không thể thêm「もし」để nói 「もし約束した上は」.<br>・Vế sau không thể chỉ là một sự thật được nêu ra. Ví dụ 「日本に来た上は、毎日雨だった」 là sai, vì \"ngày nào cũng mưa\" không phải quyết tâm hay phán đoán của bạn.<br>・Giọng thiên về trang trọng, văn viết, nên nói thẳng với bạn bè sẽ rất gượng; nói chuyện thường ngày phần lớn dùng <span class='gd-jp'>からには</span>.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>からには</b>: nghĩa gần như giống hệt, đều là \"đã ～ thì ～\".<br>・<span class='gd-jp'>引き受けた上は、最後まで頑張ります。</span>（Đã nhận rồi thì tôi sẽ cố gắng đến cùng）<br>・<span class='gd-jp'>引き受けたからには、最後まで頑張ります。</span>（Như trên）<br>Khác nhau ở hoàn cảnh: <span class='gd-jp'>上は</span> cứng hơn, thường gặp trong văn bản, bài phát biểu, những lời tuyên bố rất nghiêm túc; <span class='gd-jp'>からには</span> dùng được cả trong hoàn cảnh trang trọng, và nghe nhiều hơn trong hội thoại hằng ngày.</div><div class='gd-sec'><b>上に</b>: chỉ khác một chữ, nhưng nghĩa hoàn toàn khác, là \"không những ～ mà còn ～\".<br>・<span class='gd-jp'>この店は安い上に、おいしい。</span>（Quán này không những rẻ mà còn ngon）<br>・<span class='gd-jp'>店長である上は、遅刻はできない。</span>（Đã là quản lý quán thì không được đi trễ）</div><div class='gd-warn'>Mẹo phân biệt: nếu vế sau là \"cộng thêm một ưu điểm hoặc khuyết điểm\" thì dùng 上に; nếu vế sau là \"vì vậy nên, phải, chỉ còn cách\" thì dùng 上は. Khi nói chuyện với bạn bè, hễ muốn nói \"đã ～ thì\" thì hãy nghĩ đến からには trước.</div>","n2-33":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜上に」tương đương với <b>「không những ~ mà còn ~」「~, hơn nữa còn ~」</b> trong tiếng Việt. Bạn nói một đặc điểm trước, rồi chồng thêm một đặc điểm <b>cùng hướng</b> lên trên: tốt thì thêm tốt, tệ thì thêm tệ.</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から近い上に、家賃も安い。</span>（Căn phòng này không những gần ga mà tiền thuê cũng rẻ）</div><div class='gd-ex-line'>・<span class='gd-jp'>道に迷った上に、雨にも降られた。</span>（Đã lạc đường lại còn bị mắc mưa）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: ghép trực tiếp, dùng thể hiện tại hay quá khứ đều được.<br><span class='gd-pair'><span class='gd-jp'>寝坊した</span> → <span class='gd-jp'>寝坊した上に</span></span><br><b>Tính từ đuôi い</b>: ghép trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安い上に</span></span><br><b>Tính từ đuôi な</b>: phải đổi「だ」thành「な」.<br><span class='gd-pair'><span class='gd-jp'>親切だ</span> → <span class='gd-jp'>親切な上に</span></span><br><b>Danh từ</b>: thêm「である」hoặc「の」; khi viết văn thì「である」thường gặp hơn.<br><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者である上に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は親切な上に、仕事も早い。</span>（Cô ấy vừa tốt bụng, làm việc lại nhanh）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は寝坊した上に、財布まで忘れてしまった。</span>（Hôm nay đã ngủ quên, đến cả ví cũng quên mang）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者である上に、作家としても有名だ。</span>（Anh ấy là bác sĩ, hơn nữa còn nổi tiếng với tư cách nhà văn）</div><div class='gd-sec'>Bạn sẽ thấy vế sau thường có <span class='gd-jp'>も</span> hoặc <span class='gd-jp'>まで</span>, vì ý nghĩa chính là「cái này <b>cũng</b> ~」「<b>đến cả</b> cái này <b>cũng</b> ~」.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đọc là <b>うえに</b>, không phải じょうに.<br>・Hai vế phải cùng một hướng. <span class='gd-jp'>安い上に、まずい。</span> là sai: rẻ là ưu điểm, dở là khuyết điểm, một tốt một xấu thì phải dùng <span class='gd-jp'>安いけど、まずい。</span>（Rẻ thì có rẻ, nhưng dở lắm）<br>・Tính từ đuôi な không được giữ lại「だ」: nói <span class='gd-jp'>便利な上に</span>, không nói 便利だ上に.<br>・Câu với「上に」là để miêu tả, đánh giá sự việc, nên phía sau đừng nối thẳng「xin hãy ~」「chúng ta cùng ~ nhé」. Muốn khuyên ai đó, hãy nói xong hai việc trước, rồi dẫn ra bằng <span class='gd-jp'>から</span>: <span class='gd-jp'>寒い上に風も強いから、今日は家にいよう。</span>（Vừa lạnh gió lại mạnh, hôm nay ở nhà thôi）<br>・「上に」trong <span class='gd-jp'>机の上に本がある。</span> nghĩa là「ở trên bàn」, nói về vị trí, không liên quan đến mẫu ngữ pháp này; nhìn ngữ cảnh là phân biệt được.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cả ba đều có「上」nhưng nghĩa hoàn toàn khác nhau. Hãy so sánh qua tình huống「công việc」:<br><b>上に</b>＝hơn nữa (hai sự thật chồng lên nhau): <span class='gd-jp'>この仕事は給料が安い上に、残業も多い。</span>（Công việc này lương thấp, lại còn tăng ca nhiều）<br><b>上で</b>＝làm xong A rồi mới làm B: <span class='gd-jp'>条件をよく確認した上で、契約します。</span>（Sau khi xác nhận kỹ các điều kiện, tôi sẽ ký hợp đồng）<br><b>上は</b>＝đã ~ thì nhất định phải ~: <span class='gd-jp'>引き受けた上は、最後までやります。</span>（Đã nhận rồi thì tôi sẽ làm đến cùng）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu dịch được là「hơn nữa / mà còn」thì là 上に; 「sau khi ~ rồi mới」là 上で; 「đã ~ thì」là 上は.</div><div class='gd-h'>Học tiếp sau khi đã nắm vững</div><div class='gd-sec'><span class='gd-jp'>その上</span> đặt ở đầu câu cũng có nghĩa là「hơn nữa」: <span class='gd-jp'>この店は安い。その上、おいしい。</span>（Quán này rẻ. Hơn nữa còn ngon）<br>Muốn diễn đạt mạnh hơn kiểu「không chỉ ~ mà thậm chí còn ~」, bạn có thể học tiếp <span class='gd-jp'>〜ばかりか</span>、<span class='gd-jp'>〜のみならず</span>.</div>","n2-34":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜のことだから」tương đương với <b>「với tính cách của anh ấy thì chắc chắn ~」「người như anh ấy thì chắc sẽ ~」</b> trong tiếng Việt. Bạn hiểu rõ dáng vẻ thường ngày của một người, nên lấy sự hiểu biết đó làm căn cứ để đoán lần này họ sẽ làm gì.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đoán theo tính cách</span>Vế trước nói về một người bạn quen thuộc, tốt nhất là nhắc luôn tính cách của họ; vế sau là suy đoán của bạn.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間に厳しい部長のことだから、もう会議室にいるはずだ。</span>（Trưởng phòng vốn nghiêm khắc về thời gian, chắc giờ đã ở phòng họp rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>優しい彼女のことだから、きっと手伝ってくれるよ。</span>（Cô ấy hiền như vậy, chắc chắn sẽ giúp bạn thôi）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟のことだから、どうせまだ寝ているよ。</span>（Thằng em tôi thì kiểu gì chẳng còn đang ngủ）</div><div class='gd-sec'><span class='gd-tag'>Dùng được cho công ty, cửa hàng</span>Miễn là phong cách thường ngày của họ ai cũng biết thì đều dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの会社のことだから、また値上げするだろう。</span>（Công ty đó thì chắc lại tăng giá nữa thôi）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Sau danh từ thêm「の」, rồi thêm「ことだから」:<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼のことだから</span></span><br><span class='gd-pair'><span class='gd-jp'>あの会社</span> → <span class='gd-jp'>あの会社のことだから</span></span><br>Phía trước thường thêm một từ miêu tả tính cách để căn cứ rõ ràng hơn:<br><span class='gd-pair'><span class='gd-jp'>真面目な彼</span> → <span class='gd-jp'>真面目な彼のことだから</span></span></div><div class='gd-sec'>Vế sau thường là suy đoán của bạn, nên hay đi cùng <span class='gd-jp'>だろう</span>、<span class='gd-jp'>きっと</span>、<span class='gd-jp'>はずだ</span>、<span class='gd-jp'>に違いない</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Không được bỏ「の」: phải là <span class='gd-jp'>彼のことだから</span>, không phải 彼ことだから.<br>・Người ở vế trước phải là người bạn biết rõ thường ngày họ như thế nào, và thường thì người nghe cũng biết tính cách đó. Với người mới gặp lần đầu thì không dùng được, vì bạn chưa hiểu gì về họ.<br>・Vế sau là「tôi đoán」「tôi nhận định」, không phải việc đã xảy ra. Với chuyện hoàn toàn chắc chắn thì không dùng mẫu câu này.<br>・Nếu dịch thành「vì là anh ấy」thì dễ khiến người ta tưởng chỉ là một lý do bình thường, trong khi trọng tâm thật sự là <b>「dựa trên sự hiểu biết của tôi về anh ấy」</b>.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng một tình huống, đoán xem bạn mình có đến đúng giờ không:<br><b>Danh từ＋だから</b>＝vì họ thuộc một thân phận, một loại người nào đó (lý do là sự thật hoặc phân loại): <span class='gd-jp'>彼は日本人だから、時間を守るだろう。</span>（Anh ấy là người Nhật nên chắc sẽ đúng giờ）<br><b>Danh từ＋のことだから</b>＝dựa trên sự hiểu biết của tôi về <b>con người này</b>: <span class='gd-jp'>彼のことだから、時間を守るだろう。</span>（Với tính cách của anh ấy thì chắc sẽ đúng giờ）<br>Câu đầu lấy thân phận「người Nhật」làm lý do, câu sau là vì bạn quen anh ấy và biết anh ấy lúc nào cũng đúng giờ.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu lý do là「anh ấy là ~ (thân phận, sự thật)」thì dùng だから; nếu lý do là「tôi biết anh ấy là người như vậy」thì dùng のことだから.</div><div class='gd-h'>Học tiếp sau khi đã nắm vững</div><div class='gd-sec'>Vế sau thường dùng để diễn đạt suy đoán rất chắc chắn, bạn có thể học tiếp <span class='gd-jp'>〜に違いない</span>（chắc chắn là ~）và <span class='gd-jp'>〜に決まっている</span>（đương nhiên là ~）: <span class='gd-jp'>あの人のことだから、また忘れたに決まっている。</span>（Người đó thì chắc chắn lại quên rồi）</div>","n2-36":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ずにはいられない」nghĩa là <b>「không kìm được mà～」「bất giác～」</b>. Trong lòng bỗng trào lên một cảm xúc hay một sự thôi thúc, bạn muốn nén cũng không nén nổi, và cuối cùng làm luôn. Nghĩa đen là 「nếu không làm ～ thì không yên được」, nói cách khác là 「không nhịn được mà làm」.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Cảm xúc trào dâng</span>Nghe hay nhìn thấy một điều gì đó, trong lòng tự nhiên nảy ra một cảm giác.</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌を聞くと、昔を思い出さずにはいられない。</span>（Mỗi lần nghe bài hát này, mình lại không kìm được mà nhớ về ngày xưa）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の努力には、感心せずにはいられない。</span>（Thấy anh ấy nỗ lực như vậy, thật sự không thể không khâm phục）</div><div class='gd-sec'><span class='gd-tag'>Không nhịn được mà lên tiếng, ra tay</span>Rõ ràng có thể không làm, nhưng bản thân lại không cầm lòng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>困っている人を見ると、声をかけずにはいられない。</span>（Thấy ai đó gặp khó khăn là mình không nhịn được mà đến hỏi thăm）</div><div class='gd-ex-line'>・<span class='gd-jp'>あまりにひどい話で、一言言わずにはいられなかった。</span>（Chuyện quá đáng quá, mình không nhịn được mà phải nói một câu）</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào</div><div class='gd-sec'>Trước hết chia động từ về dạng 「ない」, rồi xem nên nối theo phiên bản nào:<br>・<b>Bản ず</b>: bỏ 「ない」 đi, rồi nối với <span class='gd-jp'>ずにはいられない</span><br>・<b>Bản ないで</b>: giữ nguyên 「ない」, rồi nối với <span class='gd-jp'>ではいられない</span><br>Hai bản có nghĩa giống nhau. Bản ず phổ biến hơn và mang tính văn viết hơn; bản ないで thì khẩu ngữ hơn một chút.</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>:<br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣かない</span></span> → bỏ ない → <span class='gd-pair'><span class='gd-jp'>泣か</span> → <span class='gd-jp'>泣かずにはいられない</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わずにはいられない</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>:<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べずにはいられない</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないではいられない</span></span></div><div class='gd-sec'><b>Nhóm 3 (cần nhớ riêng)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはいられない</span></span><span class='gd-pair'><span class='gd-jp'>心配する</span> → <span class='gd-jp'>心配せずにはいられない</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはいられない</span>（こずには）</span><br>Bản ないで thì cứ theo dạng ない thông thường: <span class='gd-jp'>心配しないではいられない</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Bản ず của する là <b>せず</b>, không phải しず: <span class='gd-jp'>心配せずには</span> mới đúng. Còn bản ないで là <span class='gd-jp'>心配しないでは</span>, đừng trộn hai bản với nhau nhé.<br>・<span class='gd-jp'>来ずには</span> phải đọc là <b>こずには</b>, không phải きずには.<br>・Dạng ない của <span class='gd-jp'>言う</span> là <span class='gd-jp'>言わない</span>, nên phải nói <span class='gd-jp'>言わずには</span>, không phải 言あずには.<br>・Thấy một loạt phủ định, bạn dễ dịch theo phản xạ thành 「không thể không～」, nghe cứ như bị ép buộc. Thật ra mẫu này nói về việc <b>chính mình không kìm được</b>, nên nhớ là 「không nhịn được nên làm luôn」 là chuẩn nhất.<br>・Chủ ngữ thường là <b>chính tôi</b>. Khi nói về người khác, phải thêm <span class='gd-jp'>ようだ</span> hoặc <span class='gd-jp'>らしい</span>: <span class='gd-jp'>彼は文句を言わずにはいられないようだ。</span>（Anh ấy có vẻ không phàn nàn một chút thì không chịu nổi）</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>ざるを得ない</b> = không muốn làm, nhưng <b>bị hoàn cảnh ép</b> nên đành phải làm:<br><span class='gd-jp'>部長の冗談は全然おもしろくないけど、笑わざるを得なかった。</span>（Chuyện đùa của trưởng phòng chẳng buồn cười chút nào, nhưng mình buộc phải cười）<br><b>ずにはいられない</b> = cảm xúc trào lên trong lòng, <b>chính mình không nhịn được</b>:<br><span class='gd-jp'>友だちの冗談がおもしろすぎて、笑わずにはいられなかった。</span>（Chuyện đùa của bạn buồn cười quá, mình không nhịn được mà bật cười）</div><div class='gd-sec'><b>てたまらない</b> = nói về <b>cảm giác trong lòng</b> rất mãnh liệt, người đó có thể vẫn đang cố nhịn:<br><span class='gd-jp'>ケーキが食べたくてたまらない。</span>（Thèm ăn bánh kem không chịu nổi）<br><b>ずにはいられない</b> = nói về <b>hành động không dừng lại được</b>, thường là đã làm rồi:<br><span class='gd-jp'>ケーキを見ると、食べずにはいられない。</span>（Hễ thấy bánh kem là không nhịn được mà ăn）</div><div class='gd-warn'>Mẹo phân biệt nhanh: 「không nhịn được nên làm luôn」 là ずにはいられない, 「không muốn nhưng đành phải làm」 là ざるを得ない, 「cảm giác ～ đến mức không chịu nổi」 là てたまらない.</div>","n2-38":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜かねない」nghĩa là <b>「cứ thế này thì có khi sẽ～」</b>, và phía sau chắc chắn là <b>chuyện xấu</b>. Giống như câu bạn hay nghe: 「Cứ thức khuya thế này, sớm muộn gì cũng có chuyện đấy」, mang giọng nhắc nhở, cảnh báo.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nhắc về hậu quả xấu</span>Phía trước thường nêu một nguyên nhân hoặc điều kiện trước (<span class='gd-jp'>〜と</span>、<span class='gd-jp'>〜ば</span>、<span class='gd-jp'>このままでは</span>), rồi phía sau dùng かねない để nói điều xấu có thể xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>無理を続けると、体を壊しかねない。</span>（Cứ gắng gượng mãi thế này, có khi sẽ hỏng cả sức khỏe）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな言い方をしたら、誤解されかねないよ。</span>（Nói kiểu đó là có khi bị hiểu lầm đấy）</div><div class='gd-sec'><span class='gd-tag'>Người đó làm được chuyện ấy</span>Nói về ai đó rằng 「chuyện như vậy anh ta làm được thật đấy」, kèm đánh giá tiêu cực.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人なら、約束を忘れかねない。</span>（Nếu là người đó thì có khi quên luôn cả lời hẹn thật）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước hết chia động từ về dạng ます, bỏ 「ます」 đi, rồi thêm 「かねない」.<br><span class='gd-pair'><span class='gd-jp'>壊す</span> → <span class='gd-jp'>壊します</span> → <span class='gd-jp'>壊しかねない</span></span><br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れます</span> → <span class='gd-jp'>忘れかねない</span></span><br><span class='gd-pair'><span class='gd-jp'>誤解する</span> → <span class='gd-jp'>誤解します</span> → <span class='gd-jp'>誤解しかねない</span></span><br>Muốn nói lịch sự hơn thì dùng <b>かねません</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>このままでは、計画が中止になりかねません。</span>（Cứ thế này thì có khi kế hoạch sẽ bị hủy）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cuối từ tuy có 「ない」, nhưng nghĩa <b>không phải 「sẽ không」</b> mà là 「<b>có khả năng sẽ</b>」. Thấy ない đừng vội dịch theo phản xạ là 「không」.<br>・Chỉ dùng cho chuyện xấu. Chuyện tốt thì dùng かもしれない: ×<span class='gd-jp'>合格しかねない</span> → ○<span class='gd-jp'>合格するかもしれない</span>（biết đâu sẽ đậu）.<br>・Phía trước chỉ nối với dạng 「ます bỏ ます」, không nối với dạng từ điển hay dạng ない: ×<span class='gd-jp'>壊すかねない</span>、×<span class='gd-jp'>壊さないかねない</span>.<br>・Sắc thái khá trang trọng, rất hay gặp trong tin tức, báo cáo công ty, lời dặn của bác sĩ. Khi trò chuyện với bạn bè thì thường nói <span class='gd-jp'>〜かもしれない</span> hoặc <span class='gd-jp'>〜ちゃうかも</span>.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>かねる</b> = 「(do vị trí, lập trường) không thể～, bất tiện～」, thường là nhân viên cửa hàng, chăm sóc khách hàng từ chối một cách lịch sự.<br><b>かねない</b> = 「có khi sẽ～ (chuyện xấu)」.<br>Cùng là khi bị hỏi một câu nhạy cảm:</div><div class='gd-ex-line'>・<span class='gd-jp'>その質問にはお答えしかねます。</span>（Câu hỏi này xin phép tôi không thể trả lời）</div><div class='gd-ex-line'>・<span class='gd-jp'>その質問に答えたら、誤解されかねない。</span>（Nếu trả lời câu hỏi đó thì có khi sẽ bị hiểu lầm）</div><div class='gd-sec'><b>かもしれない</b> = đơn giản là 「có thể」, dùng được cho cả chuyện tốt lẫn xấu, giọng trung tính. <b>かねない</b> chỉ dùng cho chuyện xấu, lại còn mang thêm sắc thái cảnh báo 「phải cẩn thận」.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は晴れるかもしれない。</span>（Ngày mai có thể trời sẽ quang）</div><div class='gd-ex-line'>・<span class='gd-jp'>このまま遊んでいたら、試験に落ちかねない。</span>（Cứ chơi mãi thế này thì có khi sẽ trượt kỳ thi）</div><div class='gd-warn'>Mẹo phân biệt nhanh: 「không thể～, xin phép không～」 là かねる (không có ない nhưng lại là không làm được); 「cứ thế này có khi sẽ xảy ra chuyện」 là かねない; 「có thể」 không phân biệt tốt xấu thì dùng かもしれない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'><b>〜得る</b> cũng là 「có khả năng」, nhưng không phân biệt tốt xấu, giọng khách quan hơn: <span class='gd-jp'>これは誰にでも起こり得ることだ。</span>（Đây là chuyện ai cũng có thể gặp phải）</div>","n2-39":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜得る」nghĩa là <b>「có khả năng ～」</b>, còn「〜得ない」nghĩa là <b>「không thể nào ～」</b>. Giọng văn giống kiểu \"có khả năng xảy ra\", \"không thể nào\" trong tin tức, báo cáo tiếng Việt, khá trang trọng. Câu bạn hay nghe nhất chắc là <span class='gd-jp'>ありえない！</span> trong phim Nhật, nghĩa là \"Sao có thể như vậy được!\", \"Vô lý quá đi!\".</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đổi động từ sang dạng ます, bỏ ます đi, rồi thêm「得る」.<br><span class='gd-pair'><span class='gd-jp'>起こります</span> → bỏ ます → <span class='gd-jp'>起こり得る</span></span>(có thể xảy ra)<br><span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>あり得る</span></span>(có thể có)<br><span class='gd-pair'><span class='gd-jp'>考えます</span> → <span class='gd-jp'>考え得る</span></span>(có thể nghĩ ra được)<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>し得る</span></span>(có thể làm)</div><div class='gd-h'>Cách đọc: chỉ có một chỗ được chọn</div><div class='gd-sec'><b>Chỉ riêng dạng gốc「得る」</b>(khi đứng cuối câu hoặc đứng trước danh từ) thì đọc <b>うる</b> hay <b>える</b> đều được. <span class='gd-jp'>あり得る</span> đọc ありうる hay ありえる đều đúng, trong tin tức và văn viết thì ありうる nghe nhiều hơn.<br><b>Các dạng biến đổi khác đều đọc là「え」</b>: <span class='gd-jp'>得ない</span>(えない), <span class='gd-jp'>得ます</span>(えます), <span class='gd-jp'>得た</span>(えた).</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Có khả năng</span>Nói một cách khách quan rằng việc nào đó có thể xảy ra, chuyện tốt hay xấu đều dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にでも起こり得る問題だ。</span>(Đây là vấn đề ai cũng có thể gặp phải)</div><div class='gd-ex-line'>・<span class='gd-jp'>それは十分あり得る話だ。</span>(Đó là chuyện hoàn toàn có thể xảy ra)</div><div class='gd-sec'><span class='gd-tag'>Không thể nào</span>Khẳng định việc nào đó sẽ không xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことは現実的にあり得ない。</span>(Chuyện đó không thể xảy ra trong thực tế)</div><div class='gd-sec'><span class='gd-tag'>Nghĩ ra được・làm được</span>Thường đi cùng「限り」「すべて」.</div><div class='gd-ex-line'>・<span class='gd-jp'>考え得る方法は全部試した。</span>(Mọi cách nghĩ ra được tôi đều thử hết rồi)</div><div class='gd-sec'><span class='gd-tag'>Khẩu ngữ</span><span class='gd-jp'>ありえない</span> là trường hợp ngoại lệ, bạn bè nói chuyện cũng hay dùng để diễn tả sự sững sờ, không tin nổi.</div><div class='gd-ex-line'>・<span class='gd-jp'>え、また遅刻？ありえない！</span>(Hả, lại đi trễ nữa á? Vô lý quá đi!)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này nói về <b>việc có khả năng xảy ra hay không</b>, chứ không nói một người có biết làm một kỹ năng nào đó hay không. \"Tôi biết bơi\" phải nói <span class='gd-jp'>泳げる</span>, không nói được 泳ぎ得る.<br>・Dạng phủ định chỉ đọc えない: là <span class='gd-jp'>ありえない</span>, không có cách đọc「ありうない」.<br>・Ngoài <span class='gd-jp'>ありえない</span>, <span class='gd-jp'>ありえる</span>, các từ khác như <span class='gd-jp'>起こり得る</span> đều thiên về văn viết. Khi nói chuyện hằng ngày thì <span class='gd-jp'>起こるかもしれない</span> tự nhiên hơn.<br>・<span class='gd-jp'>ざるを得ない</span> cũng có「得ない」bên trong, nhưng nghĩa hoàn toàn khác: <span class='gd-jp'>行かざるを得ない</span> là \"buộc phải đi\", không phải \"không thể nào đi\".<br>・「得る」khi đứng một mình làm động từ thì đọc える, nghĩa là \"đạt được\", ví dụ <span class='gd-jp'>賞を得る</span>(đoạt giải), đây là chuyện khác với cách dùng ở đây.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'><b>得る vs かねない</b>: cả hai đều là \"có khả năng\", nhưng かねない chỉ dùng khi <b>lo sợ chuyện xấu xảy ra</b>.<br><span class='gd-jp'>このままでは事故が起こり得る。</span>(Cứ thế này thì có thể xảy ra tai nạn: nói bình tĩnh)<br><span class='gd-jp'>このままでは事故が起こりかねない。</span>(Cứ thế này thì không khéo xảy ra tai nạn mất: có sự lo lắng)<br>Chuyện tốt thì chỉ dùng được 得る: <span class='gd-jp'>努力すれば誰でも成功し得る。</span>(Chỉ cần nỗ lực thì ai cũng có thể thành công) Câu này đổi sang かねない là sai.</div><div class='gd-sec'><b>得ない vs っこない</b>: cả hai đều là \"không thể nào\", nhưng っこない rất <b>khẩu ngữ, rất chủ quan</b>, kiểu \"làm gì có chuyện đó chứ\".<br><span class='gd-jp'>一日で終わることはあり得ない。</span>(Không thể nào xong trong một ngày: trang trọng, khách quan)<br><span class='gd-jp'>一日で終わりっこないよ。</span>(Một ngày làm sao xong được chứ: than thở với bạn bè)</div><div class='gd-warn'>Mẹo nhỏ để chọn: nói khách quan \"có thể／không thể\" thì dùng 得る・得ない; lo chuyện xấu xảy ra thì dùng かねない; nói với bạn bè kiểu \"làm gì có chuyện đó\" thì dùng っこない.</div>","n2-40":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜っこない」nghĩa là <b>\"làm gì có chuyện ～ chứ\", \"sao có thể ～ được\"</b>. Người nói đã chắc chắn trong lòng rằng \"việc này tuyệt đối không xảy ra\", giọng khá mạnh, rất khẩu ngữ, thường mang cảm giác \"thôi đi\", \"đừng có ngốc\".</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなこと、できっこないよ。</span>(Chuyện đó, làm gì có chuyện làm được chứ)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đổi động từ sang dạng ます, <b>bỏ ます đi</b>, rồi thêm「っこない」.<br><span class='gd-pair'><span class='gd-jp'>できます</span> → <span class='gd-jp'>できっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>間に合います</span> → <span class='gd-jp'>間に合いっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>分かります</span> → <span class='gd-jp'>分かりっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>勝てます</span> → <span class='gd-jp'>勝てっこない</span></span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Không làm nổi</span>Hay đi với「できる」「分かる」「間に合う」, hoặc các động từ chỉ \"làm được hay không\" như「勝てる」「受かる」「取れる」, nghĩa là \"hoàn toàn không thể\".</div><div class='gd-ex-line'>・<span class='gd-jp'>あんな強いチームに勝てっこない。</span>(Đội mạnh như vậy, sao có thể thắng được)</div><div class='gd-ex-line'>・<span class='gd-jp'>今から走っても間に合いっこないよ。</span>(Giờ có chạy cũng không thể kịp đâu)</div><div class='gd-ex-line'>・<span class='gd-jp'>説明したって、あの人には分かりっこない。</span>(Dù có giải thích, người đó cũng không thể hiểu đâu)</div><div class='gd-sec'><span class='gd-tag'>Người khác sẽ không làm vậy</span>Khi nói về hành động của người khác, nghĩa là \"người đó đời nào lại làm vậy\".</div><div class='gd-ex-line'>・<span class='gd-jp'>あの頑固な父が謝りっこない。</span>(Ba tôi cứng đầu như thế, đời nào xin lỗi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải nối với <b>dạng đã bỏ ます</b>, không phải thể từ điển: nói <span class='gd-jp'>分かりっこない</span>, không nói「分かるっこない」.<br>・「っこない」tự nó đã là phủ định rồi, phía trước đừng thêm ない nữa.<br>・Mẫu này chỉ nối với động từ, không nối trực tiếp với tính từ hay danh từ.<br>・「っこ」có âm ngắt, phải dừng một nhịp rồi đọc「っこ」, đừng đọc thành「こない」, nếu không nghe giống「来ない」.<br>・Đây là cách nói giữa bạn bè, giọng rất mạnh. Nói với cấp trên, khách hàng hay viết trong báo cáo đều không hợp.<br>・Nói với ai đó「<span class='gd-jp'>君にはできっこない</span>」(cậu không thể làm được đâu) chẳng khác nào coi thường người ta ngay trước mặt, rất dễ làm tổn thương, hãy dùng cẩn thận.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng một ý \"Nhiều việc thế này, một ngày làm sao xong được\", có ba cách nói:<br><span class='gd-jp'>一日で終わりっこない。</span>(<b>っこない</b>: khẩu ngữ, mang cảm xúc, như đang than thở)<br><span class='gd-jp'>一日で終わるわけがない。</span>(<b>わけがない</b>: \"sao có thể\", dùng được cả khi nói lẫn khi viết)<br><span class='gd-jp'>一日で終わるはずがない。</span>(<b>はずがない</b>: suy luận theo lẽ thường rằng \"không thể\", bình tĩnh hơn)<br>Ngoài ra chú ý cách nối khác nhau: わけがない、はずがない nối với thể từ điển(<span class='gd-jp'>終わる</span>), còn っこない nối với dạng đã bỏ ます(<span class='gd-jp'>終わり</span>).</div><div class='gd-warn'>Mẹo nhỏ để chọn: lẩm bẩm, than phiền với bạn bè thì dùng「っこない」; muốn nói trang trọng hơn thì đổi sang「わけがない」hoặc「はずがない」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu có nghĩa ngược lại là「〜に決まっている」= \"chắc chắn sẽ ～, không sai đâu\": <span class='gd-jp'>そんなの、失敗するに決まっている。</span>(Làm kiểu đó thì chắc chắn thất bại thôi)</div>","n2-45":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ぶり」có hai cách dùng <b>hoàn toàn khác nhau</b>:<br>① Đi sau hành động = <b>「dáng vẻ, cách thức ~」</b>, giống như tiếng Việt nói \"dáng ăn\", \"thái độ làm việc\".<br>② Đi sau một khoảng thời gian = <b>「sau ~ mới lại ~, cách quãng ~」</b>, chính là ぶり trong <span class='gd-jp'>久しぶり</span> mà bạn đã biết từ lâu.</div><div class='gd-h'>Cách dùng ①: dáng vẻ ~</div><div class='gd-sec'><span class='gd-tag'>Cách nối</span>Danh từ thêm ぶり trực tiếp: <span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事ぶり</span></span> (cách làm việc, hiệu quả công việc)<br>Động từ chuyển sang thể ます, bỏ ます rồi thêm ぶり: <span class='gd-pair'><span class='gd-jp'>話します</span> → bỏ ます → <span class='gd-jp'>話しぶり</span></span> (cách nói chuyện) <span class='gd-pair'><span class='gd-jp'>暮らします</span> → <span class='gd-jp'>暮らしぶり</span></span> (cách sinh sống)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の仕事ぶりはみんなに認められている。</span>(Cách làm việc của anh ấy được mọi người công nhận)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の話しぶりから、自信を感じた。</span>(Qua cách nói chuyện của cô ấy, mình cảm nhận được sự tự tin)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の混雑ぶりに驚いた。</span>(Ga đông đến mức mình giật cả mình)</div><div class='gd-sec'>Cấu trúc này phần lớn dùng để miêu tả, đánh giá dáng vẻ mà <b>người khác hoặc một tình huống</b> thể hiện ra. Có vài từ quen đọc thành「っぷり」, ví dụ <span class='gd-jp'>食べっぷり</span>, <span class='gd-jp'>飲みっぷり</span>:</div><div class='gd-ex-line'>・<span class='gd-jp'>いい食べっぷりだね。</span>(Bạn ăn ngon lành, hào sảng thật đấy)</div><div class='gd-h'>Cách dùng ②: cách quãng ~ rồi lại ~</div><div class='gd-sec'><span class='gd-tag'>Cách nối</span>Khoảng thời gian + ぶり, phía sau thường là「に＋động từ」「の＋danh từ」, hoặc dùng thẳng「だ／です」.</div><div class='gd-ex-line'>・<span class='gd-jp'>5年ぶりに母校を訪れた。</span>(Sau năm năm, mình mới quay lại trường cũ)</div><div class='gd-ex-line'>・<span class='gd-jp'>10年ぶりの再会だった。</span>(Đó là cuộc gặp lại sau mười năm)</div><div class='gd-ex-line'>・<span class='gd-jp'>久しぶりの休みだ。</span>(Cuối cùng cũng có một ngày nghỉ sau thời gian dài)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、3年ぶりですね。</span>(Anh Tanaka, ba năm rồi mới gặp lại nhỉ)</div><div class='gd-sec'>Điểm mấu chốt: suốt khoảng thời gian ở giữa việc đó <b>không xảy ra</b>, và bây giờ nó <b>lại xảy ra</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau cách dùng ② không được dùng phủ định. Muốn nói \"ba năm rồi không gặp\", không thể nói <span class='gd-jp'>3年ぶりに会わなかった</span>, mà phải nói <span class='gd-jp'>3年間会っていない</span>.<br>・Cách dùng ② luôn mang nghĩa \"trước đây từng có, bây giờ <b>lại</b> có một lần nữa\". Việc làm lần đầu tiên thì không có \"lại\", nên không dùng được ぶり.<br>・Cách dùng ① không phải từ nào cũng nối được, thường gặp chỉ có vài từ: <span class='gd-jp'>仕事ぶり</span>、<span class='gd-jp'>話しぶり</span>、<span class='gd-jp'>暮らしぶり</span>、<span class='gd-jp'>生活ぶり</span>、<span class='gd-jp'>活躍ぶり</span>、<span class='gd-jp'>混雑ぶり</span>. Cách thực tế nhất là học thuộc cả cụm như từ vựng.<br>・Động từ phải nối ở dạng thể ます bỏ ます: là <span class='gd-jp'>話しぶり</span>, không phải 話すぶり.</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'>Cùng là tình huống \"sau khi tốt nghiệp\":<br><b>て以来</b> = từ đó đến nay <b>vẫn luôn</b> giữ một trạng thái: <span class='gd-jp'>卒業して以来、彼には一度も会っていない。</span>(Từ khi tốt nghiệp đến giờ mình chưa gặp anh ấy lần nào)<br><b>ぶり</b> = cách quãng lâu như vậy rồi <b>lại</b> xảy ra: <span class='gd-jp'>卒業以来、5年ぶりに彼に会った。</span>(Sau năm năm kể từ khi tốt nghiệp, cuối cùng mình cũng gặp lại anh ấy)<br><b>後</b> = đơn thuần là \"sau ~\", không quan tâm trước đó đã từng xảy ra hay chưa: <span class='gd-jp'>卒業して5年後に結婚した。</span>(Năm năm sau khi tốt nghiệp thì mình kết hôn)</div><div class='gd-warn'>Mẹo phân biệt nhanh: muốn nói \"từ đó đến giờ vẫn thế nào\" thì dùng て以来; muốn nói \"lâu lắm rồi mới lại ~\" thì dùng ぶり; chỉ nói \"sau ~\" thì dùng 後.</div>","n2-46":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜がたい」nghĩa là <b>\"khó mà ~\", \"khó lòng ~\"</b>. Trọng tâm không phải bạn thiếu năng lực, mà là <b>trong lòng không vượt qua được</b>: chuyện quá vô lý nên bạn thật sự khó tin, khó chấp nhận, khó tha thứ. Sắc thái khá trang trọng, rất hay gặp trong tin tức, bài viết và những dịp chính thức.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đổi động từ sang thể ます, bỏ ます rồi thêm がたい.<br><span class='gd-pair'><span class='gd-jp'>信じる</span> → <span class='gd-jp'>信じます</span> → <span class='gd-jp'>信じがたい</span></span><br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許します</span> → <span class='gd-jp'>許しがたい</span></span><br><span class='gd-pair'><span class='gd-jp'>理解する</span> → <span class='gd-jp'>理解します</span> → <span class='gd-jp'>理解しがたい</span></span><br>Nối xong, cả từ được dùng như tính từ đuôi い: có thể đặt trước danh từ, cũng có thể chuyển sang quá khứ.<br><span class='gd-pair'><span class='gd-jp'>信じがたい</span> → <span class='gd-jp'>信じがたかった</span></span> (trước đây rất khó tin)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Cuối câu</span>Nói thẳng ra \"mình thật sự khó mà ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼のあの行動は今でも理解しがたい。</span>(Hành động đó của anh ấy, đến giờ mình vẫn khó mà hiểu nổi)</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は受け入れがたい。</span>(Kết quả này thật khó chấp nhận)</div><div class='gd-sec'><span class='gd-tag'>Trước danh từ</span>Dùng như tính từ, đây là dạng phổ biến nhất, nhiều cụm đã thành cách nói cố định.</div><div class='gd-ex-line'>・<span class='gd-jp'>それは信じがたい話だ。</span>(Đó đúng là chuyện khó tin)</div><div class='gd-ex-line'>・<span class='gd-jp'>留学は忘れがたい経験になった。</span>(Du học đã trở thành một trải nghiệm khó quên)</div><div class='gd-ex-line'>・<span class='gd-jp'>許しがたい行為だ。</span>(Đây là hành vi không thể tha thứ)</div><div class='gd-sec'>Một số từ thường gặp khác: <span class='gd-jp'>想像しがたい</span> (khó tưởng tượng), <span class='gd-jp'>言いがたい</span> (khó nói), <span class='gd-jp'>得がたい</span> (hiếm có, đáng quý), <span class='gd-jp'>耐えがたい</span> (khó chịu đựng nổi).</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nối với <b>thể ます bỏ ます</b>, không phải thể từ điển: phải nói <span class='gd-jp'>信じがたい</span>, không thể nói 信じるがたい.<br>・Nếu <b>bản thân đồ vật khó dùng, khó làm</b> thì không dùng がたい: bút khó viết là <span class='gd-jp'>このペンは書きにくい</span>, không thể nói 書きがたい.<br>・Sắc thái hơi cứng, thiên về trang trọng. Khi nói chuyện với bạn bè, dùng <span class='gd-jp'>信じられない</span>、<span class='gd-jp'>許せない</span> sẽ tự nhiên hơn; nói 信じがたい nghe hơi như đang đọc diễn văn.<br>・Trong văn viết hay được viết bằng chữ Hán「難い」, ở đây đọc là <b>がたい</b>.</div><div class='gd-h'>Phân biệt với những mẫu na ná</div><div class='gd-sec'><b>にくい</b> = bản thân sự vật <b>khó ~</b>, khó về mặt vật lý hoặc kỹ thuật:<br><span class='gd-jp'>この説明は分かりにくい。</span>(Lời giải thích này khó hiểu: viết không rõ ràng)<br><b>がたい</b> = <b>trong lòng khó</b> chấp nhận, khó tin, khó tha thứ:<br><span class='gd-jp'>彼の考えは理解しがたい。</span>(Suy nghĩ của anh ấy mình thật sự không hiểu nổi: trong lòng không thể đồng tình)<br><b>かねる</b> = đứng ở lập trường của mình mà <b>không tiện làm</b>, thường dùng để từ chối một cách lịch sự:<br><span class='gd-jp'>その件にはお答えしかねます。</span>(Về việc đó, tôi xin phép không thể trả lời)</div><div class='gd-warn'>Mẹo phân biệt nhanh: đồ vật khó dùng, khó hiểu thì dùng にくい; trong lòng không vượt qua được, khó chấp nhận thì dùng がたい; lịch sự từ chối đối phương thì dùng かねる.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Từ <span class='gd-jp'>ありがたい</span> mà bạn nói hằng ngày thật ra bắt nguồn từ「有り難い」, nghĩa gốc là \"hiếm có, ít khi có được\", về sau mới thành \"đáng biết ơn\".</div>","n2-42":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に決まっている」nghĩa là <b>“chắc chắn là ~ rồi, nghĩ cũng biết”</b>. Người nói đã mặc định như vậy từ trước, giọng rất quả quyết, kiểu “còn phải nói nữa à?”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối trực tiếp, thể quá khứ và phủ định cũng được.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くに決まっている</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いに決まっている</span></span><span class='gd-pair'><span class='gd-jp'>忘れた</span> → <span class='gd-jp'>忘れたに決まっている</span></span></div><div class='gd-sec'><b>Danh từ, tính từ な</b>: <b>không thêm だ</b>, nối thẳng với に.<br><span class='gd-pair'><span class='gd-jp'>嘘</span> → <span class='gd-jp'>嘘に決まっている</span></span><span class='gd-pair'><span class='gd-jp'>無理</span> → <span class='gd-jp'>無理に決まっている</span></span></div><div class='gd-sec'>Khi trò chuyện thường rút gọn thành <span class='gd-jp'>〜に決まってる</span>; nói lịch sự hơn là <span class='gd-jp'>〜に決まっています</span>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nghĩ cũng biết</span>Không cần bằng chứng, trong lòng bạn đã chắc chắn là như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな時間に電話なんて、急用に決まってる。</span>(Giờ này mà gọi điện, chắc chắn là có việc gấp)</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなに安いのは偽物に決まってるよ。</span>(Rẻ như vậy thì chắc chắn là hàng giả rồi)</div><div class='gd-sec'><span class='gd-tag'>Còn phải nói</span>Đối phương hỏi một chuyện quá hiển nhiên, bạn đáp “tất nhiên rồi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>「一緒に行く？」「行くに決まってるじゃん！」</span>(“Đi cùng nhau nhé?” “Tất nhiên là đi rồi!”)</div><div class='gd-ex-line'>・<span class='gd-jp'>10時間も歩いたんだから、疲れたに決まってるでしょ。</span>(Đi bộ tận 10 tiếng thì tất nhiên là mệt rồi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ, tính từ な không thêm だ: nói <span class='gd-jp'>嘘だに決まっている</span> là sai, phải nói <span class='gd-jp'>嘘に決まっている</span>.<br>・Đây là <b>sự khẳng định chủ quan của người nói</b>, giọng rất mạnh. Nói 「〜に決まっています」 với cấp trên hay khách hàng dễ nghe như áp đặt, thậm chí như đang gắt với người ta; văn bản trang trọng, báo cáo cũng ít dùng.<br>・Trong tiếng Việt, “nhất định” còn có nghĩa là “nhất định phải làm”, nhưng に決まっている <b>không có nghĩa này</b>. Muốn nói “mai nhất định phải đến nhé” thì nói <span class='gd-jp'>明日は必ず来てください</span>.<br>・<span class='gd-jp'>決まっている</span> vốn nghĩa là “đã được quyết định”. Nên đôi khi nó chỉ mang nghĩa đen: <span class='gd-jp'>会議は月曜日に決まっている。</span>(Cuộc họp đã được định vào thứ Hai). Hãy dựa vào ngữ cảnh để phân biệt.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống: bạn của bạn đến giờ vẫn chưa tới.<br><b>に違いない</b> = suy đoán có căn cứ, giọng bình tĩnh hơn, dùng được cả khi nói lẫn khi viết:<br><span class='gd-jp'>道が混んでいるに違いない。</span>(Chắc chắn là đường đang kẹt)<br><b>に決まっている</b> = chủ quan hơn, cảm xúc mạnh hơn, gần như chỉ dùng khi trò chuyện:<br><span class='gd-jp'>道が混んでいるに決まってるよ。</span>(Chắc chắn là kẹt xe rồi, nghĩ cũng biết)<br><b>に相違ない</b> = nghĩa giống に違いない nhưng rất cứng, thường gặp trong văn viết, tiểu thuyết:<br><span class='gd-jp'>道が混んでいるに相違ない。</span>(Hẳn là giao thông đang ùn tắc)<br>Mẫu ngược lại là <b>っこない</b> = “làm gì có chuyện ~”, cũng khẩu ngữ và chủ quan:<br><span class='gd-jp'>あの人が時間通りに来っこないよ。</span>(Anh ta làm gì có chuyện đến đúng giờ)</div><div class='gd-warn'>Mẹo nhỏ: suy luận bình tĩnh dùng に違いない, văn viết dùng に相違ない, còn giọng kiểu “nghĩ cũng biết”, “còn phải nói” thì dùng に決まっている. Muốn nói “không thể nào” thì dùng っこない.</div>","n2-44":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ものだ」nghĩa là <b>“thật là ~ nhỉ”, “ngày xưa ấy mà……”</b>. Nó không phải để báo cáo sự thật, mà là nói với <b>cảm khái về cuộc đời</b>, giống giọng người lớn tuổi nhìn tấm ảnh cũ rồi thở dài “thời gian trôi nhanh thật”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ thể thường: <span class='gd-pair'><span class='gd-jp'>変わる</span> → <span class='gd-jp'>変わるものだ</span></span><br>Tính từ い: <span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早いものだ</span></span><br>Tính từ な phải giữ lại 「な」: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなものだ</span></span><br>Nói chuyện ngày xưa thì dùng thể た: <span class='gd-pair'><span class='gd-jp'>遊んだ</span> → <span class='gd-jp'>遊んだものだ</span></span><br>Khẩu ngữ thường rút gọn thành <b>もんだ</b>, cuối câu hay thêm <b>なあ</b>: <span class='gd-jp'>早いもんだなあ。</span>Nói lịch sự hơn thì dùng <span class='gd-jp'>ものです</span>.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Cảm khái cuộc đời</span>Thốt lên về thời gian, cuộc đời, sự thay đổi.</div><div class='gd-ex-line'>・<span class='gd-jp'>月日がたつのは早いものだ。</span>(Thời gian trôi nhanh thật đấy)</div><div class='gd-ex-line'>・<span class='gd-jp'>この町もずいぶん変わったものだ。</span>(Thị trấn này cũng thay đổi nhiều thật nhỉ)</div><div class='gd-sec'><span class='gd-tag'>Hoài niệm chuyện xưa</span>Thể た + ものだ, thường đi cùng 「よく」, nói về việc <b>ngày xưa hay làm</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃はよくこの川で遊んだものだ。</span>(Hồi nhỏ mình hay chơi ở con sông này lắm)</div><div class='gd-ex-line'>・<span class='gd-jp'>学生時代は朝まで友達と話したものだ。</span>(Hồi còn đi học, mình hay nói chuyện với bạn đến sáng)</div><div class='gd-sec'><span class='gd-tag'>Khâm phục hoặc ngán ngẩm</span>「よく～たものだ」= vậy mà cũng ~ được.</div><div class='gd-ex-line'>・<span class='gd-jp'>よくそんなことが言えたものだ。</span>(Vậy mà cũng nói ra được câu đó)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cách dùng hoài niệm chỉ nói được về việc <b>đã lặp đi lặp lại trong quá khứ</b>. Việc chỉ xảy ra một lần thì không dùng được: <span class='gd-jp'>去年京都へ行ったものだ</span> là sai, chỉ cần nói <span class='gd-jp'>去年京都へ行った</span> là được.<br>・「よく」có hai nghĩa: よく trong <span class='gd-jp'>よく遊んだものだ</span> là “thường xuyên”; よく trong <span class='gd-jp'>よく言えたものだ</span> là “vậy mà”. Hãy xem ngữ cảnh để phân biệt.<br>・Với chuyện nhỏ ngay trước mắt, như trời nóng hay đồ ăn ngon, chỉ cần nói <span class='gd-jp'>暑いなあ</span>, <span class='gd-jp'>おいしいね</span>. Cố thêm ものだ nghe sẽ như đang phát biểu triết lý cuộc đời.<br>・Tính từ な không được thêm 「だ」 rồi mới nối ものだ, <span class='gd-jp'>静かだものだ</span> là sai.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>ものだ (vốn dĩ ~ / nên ~)</b>: nói về lẽ thường hoặc quy tắc chung, không mang cảm xúc.<br><span class='gd-jp'>年をとると、物忘れが多くなるものだ。</span>(Người già thì vốn dĩ hay quên trước quên sau)<br><span class='gd-jp'>人の話は最後まで聞くものだ。</span>(Người khác nói thì nên nghe đến cùng)<br><b>ものだ (cảm thán)</b>: cùng một dạng, nhưng mang cảm khái.<br><span class='gd-jp'>子供が大きくなるのは本当に早いものだ。</span>(Trẻ con lớn lên nhanh thật đấy)<br><b>ものがある</b>: có thứ gì đó khiến bạn <b>cảm nhận được một phẩm chất</b>, dùng để đánh giá tác phẩm, con người, màn thể hiện.<br><span class='gd-jp'>彼の歌には人の心を打つものがある。</span>(Bài hát của anh ấy có sức mạnh lay động lòng người)</div><div class='gd-warn'>Mẹo nhỏ: nếu thêm được 「本当に」「なあ」 vào câu mà đọc lên thấy có cảm xúc thì đó là cảm thán; nói lý lẽ, quy tắc một cách bình tĩnh thì là “vốn dĩ ~”; còn nói “thứ gì đó mang cảm giác ~” thì là ものがある.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy xem tiếp <span class='gd-jp'>〜ものがある</span>, rồi quay lại ôn <span class='gd-jp'>ものだ</span> nghĩa “vốn dĩ ~”. Đặt cả ba cạnh nhau để so sánh thì khó bị lẫn nhất.</div>","n2-47":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜かける」nghĩa là <b>「làm dở, làm được nửa chừng」</b>: đọc sách dở, ăn cơm dở, nói được nửa câu. Việc đã bắt đầu nhưng chưa xong, dừng lại giữa chừng. Khi đi sau một số động từ, nó còn mang nghĩa <b>「suýt ～」「sắp ～」</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Lấy thể ます của động từ, bỏ「ます」rồi thêm「かける」hoặc「かけの」.<br><span class='gd-pair'><span class='gd-jp'>読みます</span> → <span class='gd-jp'>読みかける</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べかける</span></span><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しかける</span></span><br>Bản thân「かける」chia như động từ nhóm 2 (động từ 一段): <span class='gd-jp'>かけた</span>、<span class='gd-jp'>かけて</span>、<span class='gd-jp'>かけている</span>.<br>Khi bổ nghĩa cho danh từ, dùng <b>かけの＋danh từ</b>: <span class='gd-jp'>飲みかけのコーヒー</span> (ly cà phê uống dở).<br>Khi đặt cuối câu, dùng <b>かけだ</b>: <span class='gd-jp'>この本はまだ読みかけだ。</span> (Cuốn sách này mình vẫn đọc dở, chưa xong)</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Làm dở dang</span>Đi với những động từ chỉ hành động bạn chủ động làm như「đọc, ăn, viết, nói」, diễn tả việc đang làm thì dừng lại giữa chừng.</div><div class='gd-ex-line'>・<span class='gd-jp'>読みかけの小説が本棚に積まれている。</span> (Những cuốn tiểu thuyết đọc dở được chất đống trên giá sách)</div><div class='gd-ex-line'>・<span class='gd-jp'>何か言いかけて、やめた。</span> (Anh ấy định nói gì đó rồi lại thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>飲みかけのコーヒー、捨ててもいい？</span> (Ly cà phê uống dở này đổ đi được không?)</div><div class='gd-sec'><span class='gd-tag'>Suýt, sắp</span>Đi với những động từ chỉ sự thay đổi xảy ra trong chốc lát như「chết, chết đuối, tắt, quên」, nghĩa là「sắp sửa như thế」hoặc「suýt nữa thì như thế, nhưng rốt cuộc không」.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供のころ、海で溺れかけたことがある。</span> (Hồi nhỏ mình từng suýt chết đuối ở biển)</div><div class='gd-ex-line'>・<span class='gd-jp'>道で死にかけた猫を見つけた。</span> (Mình thấy một con mèo sắp chết ngoài đường)</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れかけていた夢を思い出した。</span> (Mình nhớ lại một giấc mơ suýt nữa đã quên mất)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>話しかける</span> không phải「nói dở câu」mà là <b>「bắt chuyện với ai đó」</b>. Muốn nói「nói dở câu」thì dùng <span class='gd-jp'>言いかける</span>. <span class='gd-jp'>呼びかける</span> (kêu gọi) và <span class='gd-jp'>出かける</span> (ra ngoài) cũng là những từ vựng cố định, không liên quan đến nghĩa「dở dang」.<br>・Khi bổ nghĩa danh từ, dạng hay dùng nhất là「かけの」: <span class='gd-jp'>食べかけのパン</span> (cái bánh mì ăn dở), đừng viết thành「食べかけパン」.<br>・Những động từ chỉ「tồn tại, trạng thái」như <span class='gd-jp'>ある</span>、<span class='gd-jp'>いる</span> không có điểm bắt đầu hay kết thúc, nên không đi với かける.<br>・Cùng một「かける」có thể là「dở dang」cũng có thể là「suýt」, phải dựa vào động từ đứng trước để phán đoán: <span class='gd-jp'>死にかける</span> chắc chắn là「suýt chết」, không thể là「chết dở」.</div><div class='gd-h'>Phân biệt với mẫu câu giống nhau</div><div class='gd-sec'>So sánh trong cùng một tình huống:<br><b>かける</b> = đã <b>gần đến bước đó</b>, hoặc dừng lại giữa chừng: <span class='gd-jp'>火が消えかけている。</span> (Lửa sắp tắt rồi, chỉ còn một chút xíu)<br><b>つつある</b> = <b>đang thay đổi dần dần</b>, nhấn vào quá trình biến đổi: <span class='gd-jp'>火が消えつつある。</span> (Lửa đang nhỏ dần)<br>Ngoài ra, <span class='gd-jp'>つつある</span> phần lớn dùng trong văn viết, bản tin; còn <span class='gd-jp'>かける</span> và <span class='gd-jp'>かけの</span> thì rất hay dùng trong lời nói hằng ngày.</div><div class='gd-warn'>Mẹo phán đoán nhanh: muốn nói「dừng giữa chừng, suýt nữa thì ～」thì dùng かける; muốn nói「đang dần dần thay đổi」thì dùng つつある.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu ngược lại với nó là <span class='gd-jp'>〜きる</span> (làm xong, làm đến cùng): <span class='gd-jp'>一晩で読みきった。</span> (Chỉ một đêm là đọc xong hết)</div>","n2-48":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ことなく」giống như lối nói trong văn viết của tiếng Việt: <b>「không hề ～」「chưa từng ～」「không một lần nào ～」</b>. Nghĩa giống「〜ないで」(không ～ mà…), chỉ là trang trọng hơn nhiều, hay xuất hiện trong bản tin, bài viết, bài phát biểu.<br>Phần đứng trước là <b>việc đã không xảy ra</b>: <span class='gd-jp'>休むことなく</span> = không nghỉ, cứ liên tục không dừng.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Thể từ điển của động từ (dạng gốc trong từ điển) thêm ことなく trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休むことなく</span></span> (không nghỉ)<br><span class='gd-pair'><span class='gd-jp'>迷う</span> → <span class='gd-jp'>迷うことなく</span></span> (không hề do dự)<br>Động từ dạng「danh từ＋する」cũng giống vậy: <span class='gd-pair'><span class='gd-jp'>遅刻する</span> → <span class='gd-jp'>遅刻することなく</span></span> (không đi trễ)<br>Thể bị động cũng ghép được: <span class='gd-pair'><span class='gd-jp'>気づかれる</span> → <span class='gd-jp'>気づかれることなく</span></span> (không bị phát hiện)<br><b>Bản thân ことなく không phân biệt quá khứ hay hiện tại</b>, thì của câu được quyết định ở cuối câu.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>一度も・一日も</span>Thêm những từ này phía trước để nhấn mạnh「một lần cũng không」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一日も休むことなく働き続けた。</span> (Anh ấy không nghỉ một ngày nào, cứ làm việc liên tục)</div><div class='gd-sec'><span class='gd-tag'>Kiên trì lâu dài</span>Nói về một việc suốt thời gian dài không thay đổi, không bị gián đoạn.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は40年間、変わることなく同じ味を守っている。</span> (Suốt 40 năm qua, quán này vẫn giữ nguyên một hương vị)</div><div class='gd-sec'><span class='gd-tag'>Thể hiện quyết tâm</span>Rất hay dùng trong bài phát biểu, lời cảm ơn khi nhận giải.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも初心を忘れることなく、頑張ってまいります。</span> (Từ nay về sau tôi cũng sẽ không quên lòng mình lúc ban đầu và tiếp tục cố gắng)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は迷うことなく、この道を選んだ。</span> (Cô ấy đã chọn con đường này mà không hề do dự)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước là thể từ điển <b>khẳng định</b>, không phải thể ない: ○<span class='gd-jp'>休むことなく</span>　×休まないことなく.<br>・Thấy「休む」đừng nghĩ là「có nghỉ」, ことなく sẽ phủ định toàn bộ việc đứng trước nó.<br>・Với động từ dạng「danh từ＋する」thì không được bỏ する: ×連絡ことなく　○<span class='gd-jp'>連絡することなく</span>.<br>・Cách nói này rất cứng. Nếu nói với bạn bè「ra khỏi nhà mà chưa ăn sáng」thì chỉ cần nói <span class='gd-jp'>食べないで出かけた</span>, dùng ことなく nghe như đang đọc văn bản hành chính.<br>・Thường dùng cho việc「lẽ ra có thể xảy ra nhưng rốt cuộc không」(mệt rồi mà vẫn không nghỉ, lẽ ra sẽ do dự nhưng không hề do dự), nên hay mang sắc thái「rất kiên trì, đáng nể」.</div><div class='gd-h'>Phân biệt với mẫu câu giống nhau</div><div class='gd-sec'>Cùng một việc「anh ấy không nghỉ, cứ làm việc liên tục」, có ba cách nói:<br><span class='gd-jp'>休まないで働いた。</span> (khẩu ngữ, dùng nhiều nhất khi trò chuyện)<br><span class='gd-jp'>休まずに働いた。</span> (trang trọng hơn một chút, nói hay viết đều được)<br><span class='gd-jp'>休むことなく働いた。</span> (văn viết nhất, nghe có sức nặng kiểu「trước sau như một」)<br>Nghĩa giống nhau, khác nhau ở <b>mức độ trang trọng</b>.</div><div class='gd-sec'>Tuy nhiên「ないで」còn một cách dùng nữa: <b>không làm A, mà làm B</b>. Trường hợp này thường không dùng ことなく.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車に乗らないで、歩いて帰った。</span> (Không đi tàu điện, mà đi bộ về nhà)</div><div class='gd-sec'>Nếu đổi câu này thành「電車に乗ることなく」thì nghe rất không tự nhiên.</div><div class='gd-warn'>Mẹo phán đoán nhanh: trò chuyện thì dùng ないで, trang trọng hơn một chút thì dùng ずに, muốn viết kiểu bản tin, bài phát biểu hoặc nhấn mạnh「một lần cũng không」thì mới dùng ことなく. Nếu là「không A mà làm B」thì để cho ないで hoặc ずに.</div>","n2-49":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようがない」nghĩa là <b>「không có cách nào ~」「muốn ~ cũng chẳng biết bắt đầu từ đâu」</b>. 「よう」ở đây có nghĩa là「方法」(cách, phương pháp), nên「ようがない」tức là <b>đến cách làm cũng không có</b>. Không phải bạn không muốn làm, cũng không phải bạn thiếu năng lực, mà là hoàn cảnh khiến bạn không tìm ra cách nào để bắt tay vào.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thiếu điều kiện, thiếu phương tiện</span>Bạn muốn làm, nhưng thiếu thứ then chốt (thông tin, công cụ, manh mối) nên hoàn toàn không biết bắt đầu từ đâu.</div><div class='gd-ex-line'>・<span class='gd-jp'>住所も電話番号も知らないので、連絡しようがない。</span>(Địa chỉ lẫn số điện thoại đều không biết, nên chẳng có cách nào liên lạc được)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部品はもう売っていないから、直しようがないね。</span>(Linh kiện này không còn bán nữa, nên không sửa được rồi)</div><div class='gd-sec'><span class='gd-tag'>ようもない</span>Chen thêm「も」ở giữa thì giọng mạnh hơn, mang cảm giác「không còn một cách nào dù chỉ một chút」.</div><div class='gd-ex-line'>・<span class='gd-jp'>道が雪で埋まっていて、進みようもなかった。</span>(Đường bị tuyết lấp kín, hoàn toàn không thể tiến lên)</div><div class='gd-sec'>Dùng được cả trong văn viết lẫn văn nói. Nói với bạn bè「<span class='gd-jp'>直しようがないよ</span>」cũng rất tự nhiên.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Lấy thể ます của động từ, bỏ ます rồi thêm「ようがない」.<br><span class='gd-pair'><span class='gd-jp'>書きます</span> → bỏ ます → <span class='gd-jp'>書きようがない</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べようがない</span></span><span class='gd-pair'><span class='gd-jp'>連絡します</span> → <span class='gd-jp'>連絡しようがない</span></span></div><div class='gd-sec'><span class='gd-tag'>Danh từ＋のしようがない</span>Những danh từ như「連絡、説明、返事」thường được nói thành「danh từ＋の＋しようがない」.<br><span class='gd-pair'><span class='gd-jp'>説明しようがない</span> → <span class='gd-jp'>説明のしようがない</span></span>(cả hai đều đúng)</div><div class='gd-sec'><span class='gd-tag'>Đặt trước danh từ</span>Thường đổi「が」thành「の」, nói thành「ようのない＋danh từ」. Dùng「ようがない＋danh từ」cũng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>言いようのない寂しさを感じた。</span>(Tôi cảm thấy một nỗi cô đơn không sao diễn tả nổi)</div><div class='gd-h'>Những dạng nghe nhiều nhất</div><div class='gd-sec'>Trong hội thoại, bạn sẽ gặp nhất mấy cách nói cố định này:<br><span class='gd-jp'>どうしようもない</span>: làm thế nào cũng hết cách; cũng có thể dùng để chê người ta là「hết thuốc chữa」.<br><span class='gd-jp'>しょうがない</span>: hết cách rồi, thôi vậy. Thực ra đây là「<span class='gd-jp'>しようがない</span>」được đọc nhanh mà thành.<br><span class='gd-jp'>言いようがない</span>: (tốt đến mức, tệ đến mức) khó mà diễn tả.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨じゃしょうがないね。</span>(Mưa thì cũng đành chịu thôi nhỉ)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Cấu trúc này nối với <b>thể ます</b>, không phải thể ý chí: đúng là <span class='gd-jp'>書きようがない</span>, không phải「書こうがない」.<br>・「しよう」trong <span class='gd-jp'>連絡しようがない</span> trông rất giống しよう nghĩa là「chúng ta cùng làm nhé」, nhưng thực ra là「し＋よう(cách)」, nghĩa hoàn toàn khác.<br>・Nó nói về <b>không có cách, không có phương tiện</b>, không phải vấn đề năng lực.「Tôi không biết bơi」phải nói là <span class='gd-jp'>泳げない</span>, không thể nói「泳ぎようがない」.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống: bị hỏi một câu mà không trả lời được.<br><b>Thể khả năng phủ định</b> = đơn thuần là「không thể」, lý do gì cũng được: <span class='gd-jp'>その質問には答えられない。</span>(Câu hỏi đó tôi không trả lời được)<br><b>ようがない</b> = không có thông tin, không có căn cứ nên <b>không biết lấy gì</b> để trả lời: <span class='gd-jp'>何も聞いていないので、答えようがない。</span>(Tôi chẳng được nghe gì cả, nên không biết trả lời thế nào)<br><b>かねる</b> = thật ra có thể trả lời, nhưng <b>vì lập trường nên không tiện</b>; nhân viên chăm sóc khách hàng, nhân viên cửa hàng dùng khi từ chối một cách lịch sự: <span class='gd-jp'>その件についてはお答えしかねます。</span>(Về việc đó, chúng tôi xin phép không thể trả lời)</div><div class='gd-warn'>Mẹo phán đoán nhanh: 「thiếu cách, không biết bắt đầu từ đâu」dùng ようがない; 「vì lập trường nên không tiện, khéo từ chối」dùng かねる; 「không thể」với bất kỳ lý do nào thì dùng thể khả năng phủ định.</div>","n2-51":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜際（に）」là <b>phiên bản trang trọng</b> của「～ khi / lúc ~」. Thông báo ở ga tàu, bảng thông báo của cửa hàng, email công ty ở Nhật dùng rất nhiều. Nghe lịch sự hơn「時」và có cảm giác giống một thông báo chính thức hơn.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thông báo・phát thanh</span>Nói với khách hàng, với công chúng, nhắc「khi làm việc này thì cần lưu ý gì」.</div><div class='gd-ex-line'>・<span class='gd-jp'>お降りの際は、足元にご注意ください。</span>(Khi xuống tàu, xin quý khách chú ý bước chân)</div><div class='gd-ex-line'>・<span class='gd-jp'>ご利用の際は、こちらのカードをお見せください。</span>(Khi sử dụng, xin vui lòng xuất trình thẻ này)</div><div class='gd-sec'><span class='gd-tag'>Công việc・trường hợp trang trọng</span>Viết thư, nói chuyện với cấp trên hoặc khách hàng.</div><div class='gd-ex-line'>・<span class='gd-jp'>先日お会いした際に、いろいろ教えていただきました。</span>(Hôm trước khi gặp, anh/chị đã chỉ cho tôi rất nhiều điều)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>: thêm「の」phía sau rồi mới nối 際.<br><span class='gd-pair'><span class='gd-jp'>入場</span> → <span class='gd-jp'>入場の際</span></span><span class='gd-pair'><span class='gd-jp'>申し込み</span> → <span class='gd-jp'>申し込みの際</span></span><br><b>Động từ</b>: thể từ điển hoặc thể た nối thẳng với 際.<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来る際</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った際</span></span></div><div class='gd-sec'>Sự khác nhau giữa thể từ điển và thể た cũng giống như「時」: thể từ điển là lúc <b>chưa làm, sắp làm</b>; thể た là <b>sau khi đã làm, đúng lần đó</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行く際に、パスポートを作りました。</span>(Khi sắp đi Nhật, tôi đã làm hộ chiếu: trước khi khởi hành)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行った際に、友達に会いました。</span>(Khi đi Nhật, tôi đã gặp bạn bè: sau khi đến nơi)</div><div class='gd-sec'>Phía sau dùng「に」là cách nói「vào lúc ~」thông thường; đổi thành「は」sẽ có sắc thái nhắc nhở kiểu「những lúc như thế này thì xin hãy…」, nên bảng thông báo hay viết「〜の際は」. Cả hai đều đúng.</div><div class='gd-h'>Những dạng nghe nhiều nhất</div><div class='gd-sec'>「お／ご＋danh từ＋の際」: お và ご phía trước là sự kính trọng dành cho khách, bạn cứ học thuộc cả cụm là được.<br><span class='gd-jp'>お帰りの際</span>(khi quý khách ra về)、<span class='gd-jp'>お降りの際</span>(khi quý khách xuống xe)、<span class='gd-jp'>ご来店の際</span>(khi quý khách đến cửa hàng)、<span class='gd-jp'>ご利用の際</span>(khi quý khách sử dụng)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ nhất định phải có「の」: đúng là <span class='gd-jp'>入場の際</span>, không phải 入場際.<br>・際 đọc là <b>さい</b>.<br>・Đừng dùng trong trò chuyện hằng ngày. Muốn nói「lúc ăn cơm hôm qua」thì cứ nói <span class='gd-jp'>昨日ご飯を食べた時</span>, nói thành「食べた際」nghe như đang viết báo cáo.<br>・際 nói về <b>thời điểm thực hiện một hành động nào đó</b>, không dùng cho một khoảng thời gian hay một trạng thái: 「Lúc còn nhỏ」là <span class='gd-jp'>子どもの時</span>, không phải 子どもの際. Tính từ nói chung cũng không nối với 際, 「lúc bận」phải nói <span class='gd-jp'>忙しい時</span>.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một tình huống: đăng nhập vào trang web.<br><b>時</b> = cách nói thông thường, trường hợp nào cũng dùng được: <span class='gd-jp'>ログインする時、パスワードを入れます。</span>(Khi đăng nhập thì nhập mật khẩu)<br><b>際</b> = cách nói trang trọng, thường gặp trong thông báo, văn bản hướng dẫn: <span class='gd-jp'>ログインの際は、パスワードを入力してください。</span>(Khi đăng nhập, vui lòng nhập mật khẩu)<br><b>場合</b> = 「trong trường hợp gặp ~」, không phải ai cũng sẽ gặp: <span class='gd-jp'>パスワードを忘れた場合は、こちらをクリックしてください。</span>(Nếu quên mật khẩu, vui lòng bấm vào đây)<br>Ai đăng nhập cũng phải nhập mật khẩu nên dùng 際; chỉ một số người mới quên mật khẩu nên dùng 場合.</div><div class='gd-warn'>Mẹo phán đoán nhanh: trò chuyện với bạn bè dùng「時」; viết thông báo, nói với khách hàng dùng「際」; 「lỡ như ~ thì」dùng「場合」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜に先立って」cũng là cách nói trang trọng, nghĩa là「trước khi ~」: <span class='gd-jp'>開会に先立って、社長が挨拶をしました。</span>(Trước khi khai mạc cuộc họp, giám đốc đã phát biểu chào mừng)</div>","n2-52":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜からすると」nghĩa là <b>“đứng từ lập trường của ～ mà nhìn”, “xét từ ～ thì”</b>. Nếu phía trước là một người, bạn đang đặt mình vào vị trí của người đó để nghĩ. Nếu phía trước là một manh mối (nét mặt, dáng vẻ, điểm số), bạn đang dựa vào manh mối đó để suy đoán.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋<span class='gd-jp'>からすると</span>／<span class='gd-jp'>からすれば</span>／<span class='gd-jp'>からしたら</span><br>Ba dạng này nghĩa giống nhau. <span class='gd-jp'>からしatら</span> mang tính khẩu ngữ hơn, nghe rất nhiều khi trò chuyện.<br><span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親からすると</span></span><span class='gd-pair'><span class='gd-jp'>彼の表情</span> → <span class='gd-jp'>彼の表情からすれば</span></span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đứng từ lập trường của ai đó</span>Phía trước là người hoặc nhóm người, ví dụ <span class='gd-jp'>親</span>、<span class='gd-jp'>子供</span>、<span class='gd-jp'>外国人</span>、<span class='gd-jp'>会社</span>. Ý là “nếu là người đó thì sẽ nhìn như vậy”, và có thể không giống cảm nhận của chính bạn.</div><div class='gd-ex-line'>・<span class='gd-jp'>親からすると、子供の将来を心配するのは自然なことだ。</span>（Đứng ở vị trí cha mẹ, lo lắng cho tương lai của con là chuyện rất tự nhiên）</div><div class='gd-ex-line'>・<span class='gd-jp'>子供からしたら、大人の話はつまらないだろう。</span>（Nhìn từ góc độ của trẻ con, chuyện của người lớn chắc là chán lắm）</div><div class='gd-ex-line'>・<span class='gd-jp'>外国人からすれば、敬語はかなり難しい。</span>（Nhìn từ góc độ người nước ngoài, kính ngữ khá là khó）</div><div class='gd-sec'><span class='gd-tag'>Phán đoán dựa trên manh mối</span>Phía trước là những manh mối nhìn thấy được, ví dụ <span class='gd-jp'>表情</span>、<span class='gd-jp'>様子</span>、<span class='gd-jp'>話し方</span>、<span class='gd-jp'>成績</span>. Cuối câu thường là <span class='gd-jp'>ようだ</span>、<span class='gd-jp'>らしい</span>、<span class='gd-jp'>はずだ</span>、<span class='gd-jp'>だろう</span>, thể hiện “mình suy đoán như vậy”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の表情からすると、何か隠しているようだ。</span>（Nhìn nét mặt anh ấy thì có vẻ như anh ấy đang giấu điều gì đó）</div><div class='gd-ex-line'>・<span class='gd-jp'>この成績からすれば、合格できるはずだ。</span>（Với điểm số này thì chắc chắn sẽ đậu）</div><div class='gd-ex-line'>・<span class='gd-jp'>空の様子からすると、午後は雨になりそうだ。</span>（Nhìn bầu trời thì chiều nay có vẻ sẽ mưa）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「から」ở đây <b>không phải nghĩa “vì”</b>. <span class='gd-jp'>親からすると</span> không phải “vì bố mẹ”, mà là “nhìn từ phía bố mẹ”. Cũng đừng nhầm với <span class='gd-jp'>からには</span> (đã ～ thì phải ～) hay <span class='gd-jp'>からこそ</span> (chính vì ～).<br>・Phía trước chỉ nối với <b>danh từ</b>. Muốn lấy một hành động làm manh mối, bạn phải biến nó thành danh từ trước, ví dụ <span class='gd-jp'>彼の話し方からすると</span>, không thể nói thẳng 「話すからすると」.<br>・<span class='gd-jp'>すれば</span>、<span class='gd-jp'>したら</span> trông giống “nếu ～”, nhưng ở đây <b>không có nghĩa giả định</b>; cả ba dạng đều là “xét từ ～”.<br>・Vế sau nói về <b>quan điểm hoặc phán đoán</b>, không đi với những câu quyết định hay yêu cầu như “tôi sẽ đi làm ～”, “hãy ～”.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b><span class='gd-jp'>にとって</span></b>＝việc này <b>đối với ai đó là gì</b>, phía sau thường là từ mang tính đánh giá (<span class='gd-jp'>大切</span>、<span class='gd-jp'>ありがたい</span>、<span class='gd-jp'>難しい</span>).</div><div class='gd-ex-line'>・<span class='gd-jp'>子供にとって、親は一番大切な存在だ。</span>（Đối với trẻ con, cha mẹ là người quan trọng nhất）</div><div class='gd-sec'><b><span class='gd-jp'>からすると</span></b>＝đặt mình vào vị trí người đó để nói họ <b>sẽ nhìn nhận, suy nghĩ thế nào</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供からすると、親の注意はうるさいだけだろう。</span>（Nhìn từ góc độ của trẻ con, lời nhắc nhở của cha mẹ chắc chỉ thấy phiền thôi）</div><div class='gd-sec'>Ngoài ra, cách dùng “phán đoán dựa trên manh mối” không thể thay bằng <span class='gd-jp'>にとって</span>; không ai nói 「<span class='gd-jp'>表情にとって</span>」 (lúc này dùng <span class='gd-jp'>からすると</span> hoặc <span class='gd-jp'>から見ると</span>).<br><br><b><span class='gd-jp'>から見ると</span></b>＝phần lớn có thể thay cho <span class='gd-jp'>からすると</span>, dùng được cả hai cách: “đứng từ lập trường của ai đó” và “phán đoán dựa trên manh mối”.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの様子から見ると、何かあったらしい。</span>（Nhìn dáng vẻ đó thì có vẻ đã xảy ra chuyện gì rồi）</div><div class='gd-warn'>Mẹo phân biệt: nói “việc này có giá trị, có ảnh hưởng gì đối với ai đó” thì dùng <span class='gd-jp'>にとって</span>; nói “nếu là người đó thì sẽ nghĩ thế nào” hoặc “suy đoán từ manh mối” thì dùng <span class='gd-jp'>からすると</span>, và lúc này thường cũng có thể đổi thành <span class='gd-jp'>から見ると</span>.</div>","n2-53":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にかけては」nghĩa là <b>“nói đến ～ thì (ai đó) đúng là cực giỏi”</b>. Trước hết bạn nêu một lĩnh vực, ví dụ nấu ăn, toán, kinh doanh, rồi phía sau là lời khen kiểu “không ai bằng”, “không thua ai”. Trọng tâm của cả câu là <b>người đó đặc biệt giỏi về mặt này</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋にかけては<br><span class='gd-pair'><span class='gd-jp'>料理</span> → <span class='gd-jp'>料理にかけては</span></span>（nói đến nấu ăn）<br>Nếu muốn nói về một hành động, hãy thêm「こと」để biến nó thành danh từ trước:<br><span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走ることにかけては</span></span>（nói đến chạy bộ）</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Khen người khác</span>Phía sau hay đi với「<span class='gd-jp'>右に出る者はいない</span>」（không ai hơn được）、「<span class='gd-jp'>かなう人はいない</span>」（không ai địch nổi）.</div><div class='gd-ex-line'>・<span class='gd-jp'>和食にかけては、彼女の右に出る者はいない。</span>（Nói đến món Nhật thì không ai hơn được cô ấy）</div><div class='gd-ex-line'>・<span class='gd-jp'>営業にかけては、彼が社内一だ。</span>（Nói đến bán hàng thì anh ấy số một trong công ty）</div><div class='gd-sec'><span class='gd-tag'>Nói về bản thân</span>Phía sau đi với「<span class='gd-jp'>誰にも負けない</span>」（không thua ai）、「<span class='gd-jp'>自信がある</span>」（rất tự tin）.</div><div class='gd-ex-line'>・<span class='gd-jp'>記憶力にかけては、誰にも負けない。</span>（Nói đến trí nhớ thì tôi không thua ai）</div><div class='gd-ex-line'>・<span class='gd-jp'>人の名前を覚えることにかけては、自信がある。</span>（Nói đến chuyện nhớ tên người thì tôi rất tự tin）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải là <b>một tài năng, một lĩnh vực sở trường</b>, phía sau phải là <b>lời đánh giá năng lực rất giỏi</b>. Những chủ đề không liên quan đến năng lực như 「<span class='gd-jp'>日本の天気にかけては</span>」 thì không dùng được.<br>・Nếu đem áp vào khuyết điểm, ví dụ “nói đến viện cớ thì anh ta đúng là thiên tài”, câu sẽ thành giọng mỉa mai, đùa cợt chứ không phải lời khen nghiêm túc.<br>・Đừng bỏ 「は」. Thiếu は thì thành 「にかけて」, và sẽ được hiểu là một mẫu ngữ pháp khác, chỉ phạm vi thời gian hay địa điểm.<br>・Cách nói này khá trang trọng, hợp khi giới thiệu người khác hoặc viết văn. Khi nói chuyện với bạn bè thì thường nói 「<span class='gd-jp'>料理なら誰にも負けない</span>」 (nấu ăn thì tôi không thua ai).</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>にかけて</b> (không có は)＝<b>phạm vi</b> từ đâu đến đâu, phía trước là thời gian hoặc địa điểm:<br><div class='gd-ex-line'>・<span class='gd-jp'>今夜から明日の朝にかけて、雨が降るでしょう。</span>（Từ tối nay đến sáng mai trời sẽ mưa）</div><b>にかけては</b>＝nói đến một <b>tài năng</b> nào đó:<br><div class='gd-ex-line'>・<span class='gd-jp'>数学にかけては、クラスで彼に勝てる人はいない。</span>（Nói đến toán thì trong lớp không ai thắng nổi cậu ấy）</div></div><div class='gd-sec'><b>に関しては</b>＝đơn thuần là “về ～”, chỉ nêu chủ đề, phía sau nói gì cũng được:<br><div class='gd-ex-line'>・<span class='gd-jp'>料理に関しては、母に聞いてください。</span>（Về chuyện nấu ăn, bạn hãy hỏi mẹ tôi）</div><b>にかけては</b>＝phía sau nhất định là khen thực lực về mặt này:<br><div class='gd-ex-line'>・<span class='gd-jp'>料理にかけては、母にかなう人はいない。</span>（Nói đến nấu ăn thì không ai địch nổi mẹ tôi）</div></div><div class='gd-warn'>Mẹo phân biệt: phía trước là thời gian, địa điểm thì dùng にかけて. Chỉ nêu chủ đề thì dùng に関しては. Muốn nói “về mặt này thì anh ấy giỏi nhất” thì mới dùng にかけては.</div>","n2-55":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にしろ／〜にせよ」tương đương với <b>「Dù là A hay B thì cũng ～」</b>, <b>「Cho dù là ～ thì cũng ～」</b> trong tiếng Việt. Phần đầu nêu ra vài khả năng, phần sau đưa ra một kết luận hoặc quan điểm <b>không vì thế mà thay đổi</b>. Hai mẫu này nghĩa giống nhau, nhưng <span class='gd-jp'>にせよ</span> trang trọng hơn, hay gặp trong văn viết và các dịp trang trọng.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Dù là A hay B</span>Đặt hai (hoặc vài) lựa chọn cạnh nhau, chọn cái nào thì kết luận cũng như nhau. Đây là cách dùng phổ biến nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにしろ行かないにしろ、早めに連絡してください。</span>（Dù đi hay không đi, cũng hãy báo sớm nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>肉にせよ魚にせよ、新鮮なものを選びたい。</span>（Dù là thịt hay cá, mình cũng muốn chọn đồ tươi）</div><div class='gd-sec'><span class='gd-tag'>Dù là gì đi nữa</span>Phía trước đặt các từ nghi vấn như 「何」「どちら」「誰」, nghĩa là 「dù là cái nào cũng vậy」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何をするにしろ、健康が一番大事だ。</span>（Dù làm gì đi nữa, sức khỏe vẫn là quan trọng nhất）</div><div class='gd-ex-line'>・<span class='gd-jp'>いずれにせよ、一度会って話しましょう。</span>（Dù sao đi nữa, mình gặp nhau nói chuyện một lần nhé）</div><div class='gd-sec'><span class='gd-jp'>いずれにせよ</span>、<span class='gd-jp'>どっちにしろ</span> gần như là cách nói cố định, nghĩa là 「tóm lại, dù sao thì」. Trong họp hành hay trò chuyện hằng ngày bạn đều nghe rất nhiều.</div><div class='gd-sec'><span class='gd-tag'>Cho dù là ～</span>Chỉ đặt một tình huống, nghĩa là 「cho dù đúng là như vậy thì cũng ～」, thường mang chút ý không đồng tình hoặc nhắc nhở.</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にしろ、そんなことを言うべきではない。</span>（Cho dù là đùa thì cũng không nên nói những lời như thế）</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいにせよ、電話ぐらいできたはずだ。</span>（Cho dù bận đến mấy, gọi một cuộc điện thoại thì vẫn làm được chứ）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: dùng thể thường (tức cách nói không có ます, khẳng định, phủ định, quá khứ đều được), nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くにしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないにしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いにせよ</span></span></div><div class='gd-sec'><b>Danh từ, tính từ な</b>: nối trực tiếp, hoặc thêm 「である」 rồi mới nối (trang trọng hơn). <b>Ở giữa không được chèn だ</b>.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生にしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便にせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便であるにせよ</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ, tính từ な <b>không được thêm だ</b>: <span class='gd-jp'>学生だにしろ</span>、<span class='gd-jp'>不便だにせよ</span> đều sai.<br>・Khi dùng 「AにしろBにしろ」, A và B phải cùng loại, ngang hàng nhau: <span class='gd-jp'>賛成にしろ反対にしろ</span>、<span class='gd-jp'>行くにしろ行かないにしろ</span>.<br>・Vế sau phần lớn là <b>quan điểm, yêu cầu hoặc lời khuyên</b> của người nói, như <span class='gd-jp'>べきだ</span>、<span class='gd-jp'>てください</span>、<span class='gd-jp'>ほうがいい</span>.<br>・<span class='gd-jp'>しろ</span>、<span class='gd-jp'>せよ</span> vốn là thể mệnh lệnh của <span class='gd-jp'>する</span>, nhưng ở đây <b>hoàn toàn không có nghĩa ra lệnh</b>. <span class='gd-jp'>勉強しろ</span> là 「đi học bài ngay cho tôi」, còn <span class='gd-jp'>勉強にしろ遊びにしろ</span> là 「dù là học hay chơi」; điểm khác nhau nằm ở chỗ có 「に」 hay không.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>にしても</b>: nghĩa gần như giống にしろ、にせよ, chỉ khác mức độ trang trọng.<br>・<span class='gd-jp'>行くにしても行かないにしても、連絡してね。</span>（Dù đi hay không cũng báo mình một tiếng nhé: giữa bạn bè）<br>・<span class='gd-jp'>出席されるにせよされないにせよ、ご連絡ください。</span>（Dù có tham dự hay không, xin vui lòng liên hệ với chúng tôi: thông báo trang trọng）<br>Từ thoải mái đến trang trọng đại khái là: <span class='gd-jp'>にしても</span> → <span class='gd-jp'>にしろ</span> → <span class='gd-jp'>にせよ</span>.</div><div class='gd-sec'><b>を問わず</b>: nghĩa là 「bất kể, không phân biệt」, phía trước chỉ nối danh từ, thường là cả một phạm vi như 「年齢」「男女」, hay dùng trong quy định, tin tuyển dụng.<br>・<span class='gd-jp'>年齢を問わず、誰でも参加できます。</span>（Không giới hạn độ tuổi, ai cũng có thể tham gia）<br>・<span class='gd-jp'>大人にしろ子どもにしろ、参加費は同じだ。</span>（Dù là người lớn hay trẻ em, phí tham gia đều như nhau）</div><div class='gd-warn'>Mẹo phân biệt: nói về phạm vi điều kiện kiểu 「không giới hạn ～」 thì dùng を問わず; liệt kê từng lựa chọn cụ thể rồi mới đưa ra kết luận thì dùng にしろ・にせよ; trò chuyện với bạn bè thì にしても tự nhiên nhất, còn viết văn hay dịp trang trọng thì dùng にせよ.</div>","n2-56":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜にほかならない」tương đương với <b>「Chính là ～」「Chẳng qua là ～」「Nói trắng ra thì là ～」</b> trong tiếng Việt. Người nói kết luận rất chắc chắn: đáp án chính là điều này, <b>không phải gì khác</b>.<br>「ほか」nghĩa là 「cái khác」, nên 「ほかならない」 theo nghĩa đen là 「không thể là thứ gì khác」, từ đó mới thành nghĩa 「chính là」. Giọng điệu rất cứng, phần lớn xuất hiện trong văn viết, diễn thuyết, bình luận trên báo.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Khẳng định bản chất</span>「A nói trắng ra chính là B」, nói thẳng bộ mặt thật của sự việc.</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は、皆さんの協力の成果にほかならない。</span>（Kết quả này chính là thành quả hợp tác của mọi người）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の説明は、言い訳にほかならない。</span>（Lời giải thích của anh ấy nói trắng ra chỉ là lời bao biện）</div><div class='gd-sec'><span class='gd-tag'>Khẳng định nguyên nhân</span>Dùng 「〜のは、〜からにほかならない」, nghĩa là 「sở dĩ ～ không phải vì gì khác, chính là vì ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が合格できたのは、毎日努力したからにほかならない。</span>（Sở dĩ anh ấy đỗ được, chính là vì ngày nào cũng nỗ lực）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故が起きたのは、安全確認を怠ったからにほかならない。</span>（Tai nạn xảy ra chẳng qua là vì đã lơ là việc kiểm tra an toàn）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>: nối trực tiếp. <span class='gd-pair'><span class='gd-jp'>努力の結果</span> → <span class='gd-jp'>努力の結果にほかならない</span></span><br><b>Khi nói về nguyên nhân</b>: sau thể thường thêm 「から」 rồi mới nối. <span class='gd-pair'><span class='gd-jp'>努力した</span> → <span class='gd-jp'>努力したからにほかならない</span></span><br><b>Khi nói về bản chất của một hành động</b>: thêm 「こと」 sau động từ thể từ điển để biến nó thành danh từ rồi nối. <span class='gd-pair'><span class='gd-jp'>逃げる</span> → <span class='gd-jp'>逃げることにほかならない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>何もしないのは、問題から逃げることにほかならない。</span>（Không làm gì cả, nói trắng ra chính là đang trốn tránh vấn đề）</div><div class='gd-sec'>Khi diễn thuyết hay ở dịp trang trọng cần lịch sự hơn, bạn nói <b>にほかなりません</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Thấy 「ならない」 đừng tưởng là phủ định hay 「không được」. Đây là <b>một sự khẳng định rất mạnh</b>: 「chính là」.<br>・Động từ không nối trực tiếp được: phải nói <span class='gd-jp'>遅れたからにほかならない</span>, không thể nói 遅れたにほかならない.<br>・Khi dùng 「〜のは」 để trả lời câu hỏi 「tại sao lại như vậy」, vế sau dùng 「〜からにほかならない」 hoặc 「〜のおかげにほかならない」 sẽ tự nhiên hơn; đặt thẳng một danh từ vào dễ làm hai vế không ăn khớp.<br>・Nói chuyện với bạn bè mà dùng mẫu này nghe cứ như đang đọc luận văn. Trong khẩu ngữ chỉ cần nói 「〜からだよ」「まさに〜だ」 là đủ.<br>・Đây là lời khẳng định chắc chắn, không phải phỏng đoán. Việc không chắc thì đừng dùng.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>にすぎない</b> = 「chỉ là ～ mà thôi」, mang cảm giác <b>coi nhẹ, xem thường</b>.<br><span class='gd-jp'>彼の成功は運がよかったからにすぎない。</span>（Anh ấy thành công chẳng qua chỉ là do may mắn thôi）<br><span class='gd-jp'>彼の成功は努力の結果にほかならない。</span>（Anh ấy thành công chính là kết quả của nỗ lực）<br>Hai mẫu trông giống nhau, nhưng một bên là hạ thấp, một bên là đưa ra kết luận.</div><div class='gd-sec'><b>からこそ</b> = nhấn mạnh 「<b>chính vì</b> lý do này mà mới có kết quả này」. Có thể đặt giữa câu, hoặc dùng 「〜のは〜からこそだ」 ở cuối câu, khẩu ngữ cũng hay nói, thường mang cảm xúc.<br><span class='gd-jp'>努力したからこそ、合格できた。</span>（Chính vì đã nỗ lực nên mới đỗ được）<br><span class='gd-jp'>合格できたのは、努力したからこそだ。</span>（Đỗ được chính là nhờ đã nỗ lực）<br><span class='gd-jp'>合格できたのは、努力したからにほかならない。</span>（Đỗ được không phải vì gì khác, chính là vì đã nỗ lực）<br>Hai câu cuối nghĩa rất gần nhau, khác ở sắc thái: からこそ là <b>nhấn mạnh nguyên nhân đó</b>; にほかならない là <b>khẳng định 「không phải gì khác」</b>, cứng hơn, mang tính văn viết hơn, giống như đang viết báo cáo và đưa ra kết luận.</div><div class='gd-warn'>Mẹo phân biệt: muốn nói 「chỉ là ～ thôi」, hơi coi thường thì dùng にすぎない; muốn nhấn mạnh 「chính vì ～ mới …」 thì dùng からこそ; muốn kết luận thật chắc chắn rằng 「không phải gì khác, chính là ～」 thì dùng にほかならない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cùng là giọng điệu 「rất chắc chắn」, bạn có thể học tiếp để so sánh <span class='gd-jp'>〜に違いない</span>、<span class='gd-jp'>〜に相違ない</span>: chúng là suy đoán mạnh kiểu 「chắc chắn là ～」, còn にほかならない là khẳng định thẳng 「chính là ～」.</div>","n2-58":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とは限らない」nghĩa là <b>「không hẳn là ～」「chưa chắc ～」</b>. Mọi người đều nghĩ \"chắc chắn là vậy\", còn bạn bước ra nói một câu: \"Chưa chắc đâu nhé, cũng có ngoại lệ đấy\". Giống câu \"đắt chưa chắc đã tốt\" mà người Việt hay nói, tiếng Nhật sẽ là <span class='gd-jp'>高いものがいいとは限らない。</span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Phá bỏ định kiến</span>Đạp phanh trước những suy nghĩ mà \"ai cũng cho là đương nhiên\".</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人がみんな寿司が好きだとは限らない。</span>（Người Nhật không hẳn ai cũng thích sushi）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の言うことがいつも正しいとは限らない。</span>（Điều thầy cô nói chưa chắc lần nào cũng đúng）</div><div class='gd-sec'><span class='gd-tag'>Nhắc về rủi ro</span>Sự việc không đảm bảo sẽ diễn ra như dự tính, nên cần chuẩn bị trước.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報が当たるとは限らないから、傘を持っていこう。</span>（Dự báo thời tiết chưa chắc đã đúng, mang theo cây dù đi）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt một câu hoàn chỉnh (thể thường, tức là cách nói không thêm です・ます), phía sau nối thẳng とは限らない.<br>Động từ：<span class='gd-pair'><span class='gd-jp'>成功する</span> → <span class='gd-jp'>成功するとは限らない</span></span><br>Tính từ い：<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いとは限らない</span></span><br>Tính từ な：<span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利だとは限らない</span></span>（だ cũng thường được lược bỏ：<span class='gd-jp'>便利とは限らない</span>）<br>Danh từ：<span class='gd-pair'><span class='gd-jp'>本物だ</span> → <span class='gd-jp'>本物だとは限らない</span></span>（cũng có thể nói <span class='gd-jp'>本物とは限らない</span>）<br>Với người trên hoặc trong hoàn cảnh trang trọng thì nói <span class='gd-jp'>とは限りません</span>.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>必ずしも〜</span>Thêm <span class='gd-jp'>必ずしも</span> (không nhất thiết) ở phía trước thì cảm giác \"chưa chắc\" rõ hơn, rất hay gặp trong văn viết.</div><div class='gd-ex-line'>・<span class='gd-jp'>有名な大学を出た人が、必ずしも仕事ができるとは限らない。</span>（Người tốt nghiệp trường danh tiếng chưa chắc đã làm việc giỏi）</div><div class='gd-sec'><span class='gd-tag'>からといって〜</span>Nghĩa là \"không thể vì ～ mà nói chắc chắn ～\", nên nhớ cả cụm cho dễ dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>安いからといって、お得だとは限らない。</span>（Không thể vì rẻ mà nói chắc chắn là hời）</div><div class='gd-sec'><span class='gd-tag'>みんな・いつも・全て</span>Phía trước hay xuất hiện những từ chỉ \"tất cả, lần nào cũng\" như thế này, vì とは限らない chính là cách chuyên dùng để bác bỏ kiểu nói \"tất cả đều như vậy\".</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nó mang nghĩa「<b>chưa chắc</b>」chứ không phải「<b>không phải</b>」. <span class='gd-jp'>高いものがいいとは限らない</span> chỉ nói đồ đắt không đảm bảo là tốt, chứ không nói đồ đắt là không tốt.<br>・Sau <span class='gd-jp'>必ずしも</span> nhất định phải là phủ định, không thể nói 「必ずしもいい」, mà phải nói <span class='gd-jp'>必ずしもいいとは限らない</span>.<br>・Cẩn thận khi gặp <span class='gd-jp'>〜ないとも限らない</span>, nghĩa sẽ đảo ngược: <span class='gd-jp'>事故が起きないとも限らない。</span> nghĩa là \"cũng không thể đảm bảo là sẽ không xảy ra tai nạn\", tức là <b>vẫn có khả năng xảy ra tai nạn</b>, dùng để nhắc nhở phải cẩn thận.<br>・限る đọc là <b>かぎる</b>, nên là かぎらない, đừng đọc thành げんらない.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng nói về chuyện \"cuối tuần có đông người không\":<br><b>に限らず</b>＝không chỉ ～ (phạm vi rộng hơn)：<span class='gd-jp'>この店は週末に限らず、いつも混んでいる。</span>（Quán này không chỉ cuối tuần mà ngày thường cũng đông）<br><b>とは限らない</b>＝chưa chắc ～ (có ngoại lệ)：<span class='gd-jp'>週末だからといって、混んでいるとは限らない。</span>（Dù là cuối tuần cũng chưa chắc đã đông）<br><b>に決まっている</b>＝chắc chắn ～ (rất tự tin)：<span class='gd-jp'>週末だから、混んでいるに決まっている。</span>（Cuối tuần mà, chắc chắn là đông rồi）</div><div class='gd-warn'>Mẹo phân biệt nhanh: <b>danh từ＋に限らず</b>＝\"không chỉ ～\"; <b>cả câu＋とは限らない</b>＝\"chưa chắc ～\". Muốn nói \"chắc chắn\" thì dùng に決まっている, muốn nói \"chưa chắc\" thì dùng とは限らない.</div>","n2-59":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「<span class='gd-jp'>〜をきっかけに</span>」nghĩa là <b>「nhân dịp ～ mà bắt đầu…」「nhân cơ hội ～ nên…」</b>. Phía trước đặt một việc đã thúc đẩy bạn, phía sau đặt <b>hành động mới hoặc sự thay đổi bắt đầu</b> từ đó. Ví dụ như \"nhờ sang Nhật mà bắt đầu tự nấu ăn\", \"sau khi bị ốm mà bắt đầu chú ý đến sức khỏe\".</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たのをきっかけに、料理を始めた。</span>（Sau khi đến Nhật, tôi bắt đầu tự nấu ăn）</div><div class='gd-ex-line'>・<span class='gd-jp'>入院をきっかけに、健康に気をつけるようになった。</span>（Sau lần nhập viện, tôi bắt đầu chú ý đến sức khỏe）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>Nối trực tiếp：<span class='gd-pair'><span class='gd-jp'>留学</span> → <span class='gd-jp'>留学をきっかけに</span></span><br><span class='gd-tag'>Động từ</span>Thêm「の」hoặc「こと」để biến nó thành một sự việc, rồi mới nối：<span class='gd-pair'><span class='gd-jp'>子どもが生まれた</span> → <span class='gd-jp'>子どもが生まれたのをきっかけに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが生まれたのをきっかけに、タバコをやめた。</span>（Từ khi con chào đời, tôi đã bỏ thuốc lá）</div><div class='gd-sec'>Phía sau thường đi với những cách nói về \"bắt đầu, thay đổi\" như「<span class='gd-jp'>始めた</span>」「<span class='gd-jp'>ようになった</span>」「<span class='gd-jp'>やめた</span>」.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>がきっかけで</span>Lấy sự việc thúc đẩy làm chủ ngữ, rất hay dùng trong khẩu ngữ.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達の一言がきっかけで、転職を考えるようになった。</span>（Chỉ một câu nói của bạn mà tôi bắt đầu nghĩ đến chuyện đổi việc）</div><div class='gd-sec'><span class='gd-tag'>きっかけは〜</span>Câu cực hay bị hỏi khi phỏng vấn và tự giới thiệu.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を始めたきっかけは何ですか。</span>（Lúc đầu bạn bắt đầu học tiếng Nhật vì lý do gì?）</div><div class='gd-ex-line'>・<span class='gd-jp'>アニメがきっかけです。</span>（Là nhờ anime）</div><div class='gd-sec'><span class='gd-tag'>をきっかけとして</span>Nghĩa giống nhau nhưng trang trọng hơn, thường thấy trong tin tức và văn bản.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trước động từ nhất định phải thêm「の」hoặc「こと」: phải nói <span class='gd-jp'>日本に来たのをきっかけに</span>, không thể nói thẳng「日本に来たをきっかけに」.<br>・「を」đi với「に」、「が」đi với「で」：<span class='gd-jp'>留学をきっかけに</span>／<span class='gd-jp'>留学がきっかけで</span>, hai cặp này đừng tách ra ghép lung tung.<br>・Mẫu này nói về việc \"thúc đẩy bạn bắt đầu một điều mới\", chứ không đơn thuần là nguyên nhân. Ví dụ kết quả do nguyên nhân trực tiếp như \"mưa to nên tàu ngừng chạy\" thì chỉ cần nói <span class='gd-jp'>大雨で電車が止まった</span>, dùng きっかけ sẽ nghe lạ.<br>・Phía trước có thể là chuyện tốt hay xấu, bị ốm, thất tình hay bị mắng đều có thể là きっかけ.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là chuyện \"chuyển nhà\":<br><b>をきっかけに</b>＝chuyển nhà <b>thúc đẩy</b> bạn bắt đầu làm một việc mới:<br><span class='gd-jp'>引っ越しをきっかけに、ジョギングを始めた。</span>（Nhân dịp chuyển nhà, tôi bắt đầu chạy bộ）<br><b>て以来</b>＝<b>kể từ</b> đó, một trạng thái cứ duy trì mãi:<br><span class='gd-jp'>引っ越して以来、毎朝ジョギングしている。</span>（Kể từ khi chuyển nhà, sáng nào tôi cũng chạy bộ）<br><b>に伴って</b>＝những việc <b>kéo theo</b> khi chuyển nhà, không phải điều bạn được truyền cảm hứng để làm:<br><span class='gd-jp'>引っ越しに伴って、住所変更の手続きをした。</span>（Vì chuyển nhà nên tôi làm luôn thủ tục đổi địa chỉ）</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"Vì chuyện đó mà tôi bắt đầu ～\" là をきっかけに; \"Từ đó đến giờ cứ ～\" là て以来; \"Việc đó xảy ra thì đương nhiên kéo theo ～\" là に伴って.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cách nói trang trọng hơn có「<span class='gd-jp'>〜を機に</span>」「<span class='gd-jp'>〜を契機に</span>」, rất hay gặp trong thông báo công ty và tin tức: <span class='gd-jp'>結婚を機に、仕事を辞めた。</span>（Nhân dịp kết hôn, tôi đã nghỉ việc）</div>","n2-60":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜あげく」nghĩa là <b>「loay hoay mãi, cuối cùng lại…」「mất công cả buổi, rốt cuộc…」</b>. Phía trước là một quá trình vừa dài vừa mệt, phía sau thường là kết quả đáng tiếc mà không ai muốn. Người nói hay mang chút than phiền, hoặc cảm giác \"công cốc\".</div><div class='gd-ex-line'>・<span class='gd-jp'>さんざん待たされたあげく、満席だと言われた。</span>（bị bắt chờ cả buổi, cuối cùng lại bảo là hết chỗ）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ dùng <b>thể た</b> (dạng quá khứ), rồi thêm <span class='gd-jp'>あげく</span>:<br><span class='gd-pair'><span class='gd-jp'>迷う</span> → <span class='gd-jp'>迷ったあげく</span></span><span class='gd-pair'><span class='gd-jp'>悩む</span> → <span class='gd-jp'>悩んだあげく</span></span><br>Danh từ thì thêm「の」rồi mới nối:<br><span class='gd-pair'><span class='gd-jp'>議論</span> → <span class='gd-jp'>議論のあげく</span></span><span class='gd-pair'><span class='gd-jp'>けんか</span> → <span class='gd-jp'>けんかのあげく</span></span><br>Phía sau thêm「に」hay không đều được, nghĩa vẫn như nhau. Chữ Hán viết là <span class='gd-jp'>挙げ句</span>, gặp thì bạn cũng nên nhận ra nhé.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Công cốc</span>Phía trước hay đi với <span class='gd-jp'>さんざん</span> (hết sức, mãi không thôi), <span class='gd-jp'>何度も</span> (nhiều lần), phía sau hay đi với <span class='gd-jp'>結局</span> (rốt cuộc).</div><div class='gd-ex-line'>・<span class='gd-jp'>さんざん迷ったあげく、結局何も買わなかった。</span>（phân vân mãi, cuối cùng chẳng mua gì cả）</div><div class='gd-ex-line'>・<span class='gd-jp'>長時間の議論のあげく、何も決まらなかった。</span>（bàn bạc rất lâu, cuối cùng chẳng quyết định được gì）</div><div class='gd-sec'><span class='gd-tag'>Quyết định bất đắc dĩ</span>Nghĩ rất lâu, cuối cùng đành đưa ra một quyết định nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>悩んだあげく、旅行には行かないことにした。</span>（trăn trở mãi, cuối cùng quyết định không đi du lịch nữa）</div><div class='gd-sec'><span class='gd-tag'>あげくの果てに</span>Cách nói cố định, nghĩa là \"đến cuối cùng thậm chí còn…\", dùng khi mọi chuyện ngày càng tệ, tệ đến mức quá đáng nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は遅刻を繰り返し、あげくの果てに無断で休んだ。</span>（anh ấy cứ đi trễ liên tục, đến cuối cùng còn nghỉ luôn mà không xin phép）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ nhất định phải dùng thể た: <span class='gd-jp'>迷うあげく</span> là sai, phải nói <span class='gd-jp'>迷ったあげく</span>.<br>・Phía trước phải là quá trình <b>kéo dài, lặp đi lặp lại</b>. Hành động xong ngay thì không dùng được: <span class='gd-jp'>ドアを開けたあげく</span>, <span class='gd-jp'>一度電話したあげく</span> đều nghe rất lạ. Phải như <span class='gd-jp'>何度も電話したあげく、やっと通じたと思ったら留守電だった。</span>（gọi điện mấy lần, tưởng cuối cùng cũng liên lạc được thì hóa ra là hộp thư thoại）thì mới tự nhiên.<br>・Phía sau là <b>kết cục đã xảy ra</b>, cuối câu phần lớn là thì quá khứ. Không đi với những điều chưa xảy ra như「chúng ta hãy ～ nhé」「xin hãy ～」.<br>・Kết quả tốt thì đừng dùng: <span class='gd-jp'>努力したあげく合格した</span> nghe rất lạ, hãy đổi sang <span class='gd-jp'>末に</span> ở dưới.</div><div class='gd-h'>Phân biệt với mẫu rất giống</div><div class='gd-sec'><b><span class='gd-jp'>末に</span></b> cũng có nghĩa là「sau một quá trình ～, cuối cùng…」và cách nối cũng giống (thể た／danh từ の＋<span class='gd-jp'>末に</span>). Khác nhau ở chỗ <span class='gd-jp'>末に</span> có sắc thái <b>trung tính hơn</b>, kết quả tốt hay xấu đều dùng được, báo chí và văn bản trang trọng dùng rất nhiều; còn <span class='gd-jp'>あげく</span> mang cảm giác than phiền kiểu \"mất công cả buổi mà rốt cuộc vẫn thế\", gần như chỉ đi với kết quả không tốt.<br>Cùng là họp rất lâu:<br><span class='gd-jp'>何度も話し合った末に、新しい計画が決まった。</span>（bàn bạc nhiều lần, cuối cùng cũng chốt được kế hoạch mới: kết quả tốt, chỉ dùng được <span class='gd-jp'>末に</span>）<br><span class='gd-jp'>何度も話し合ったあげく、結局何も決まらなかった。</span>（bàn bạc nhiều lần, cuối cùng chẳng quyết định được gì: giọng than phiền, dùng <span class='gd-jp'>あげく</span> là đúng nhất）</div><div class='gd-warn'>Mẹo phân biệt: kết quả tốt hoặc chỉ kể lại bình thường thì dùng <span class='gd-jp'>末に</span>; muốn than \"mất công cả buổi mà rốt cuộc…\" thì dùng <span class='gd-jp'>あげく</span>.</div>","n2-61":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てはじめて」nghĩa là <b>「sau khi ～ mới (hiểu／nhận ra)…」「đến khi ～ mới…」</b>. Giống câu quen thuộc \"mất đi rồi mới biết trân trọng\": phía trước là điều bạn <b>tự trải qua</b>, phía sau là điều bạn <b>mới thực sự hiểu, mới cảm nhận lần đầu</b> sau trải nghiệm đó. Điểm mấu chốt: trước đó, thật ra bạn chưa hiểu.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Thể て của động từ, rồi thêm trực tiếp「はじめて」(cũng thường viết bằng chữ Hán「初めて」).<br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なって</span> → <span class='gd-jp'>なってはじめて</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してはじめて</span></span><br><span class='gd-pair'><span class='gd-jp'>言われる</span> → <span class='gd-jp'>言われて</span> → <span class='gd-jp'>言われてはじめて</span></span><br>Phía sau thường có dấu phẩy, rồi mới đến điều bạn nhận ra.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Trải qua rồi mới hiểu</span>Phía sau hay đi với các từ chỉ \"hiểu, nhận ra\" như <span class='gd-jp'>わかる</span>, <span class='gd-jp'>気づく</span>, <span class='gd-jp'>知る</span>, <span class='gd-jp'>実感する</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>親になってはじめて、親の気持ちがわかった。</span>（tự mình làm cha mẹ rồi mới hiểu tâm trạng của cha mẹ）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしをしてはじめて、家事の大変さに気づいた。</span>（sống một mình rồi mới nhận ra làm việc nhà vất vả thế nào）</div><div class='gd-ex-line'>・<span class='gd-jp'>言われてはじめて気づきました。</span>（được người ta nói mới nhận ra）</div><div class='gd-sec'><span class='gd-tag'>Nói về lẽ thường</span>Dùng thì hiện tại, nói kiểu \"con người phải trải qua ～ mới…\".</div><div class='gd-ex-line'>・<span class='gd-jp'>病気になってはじめて、健康のありがたさがわかる。</span>（có bệnh rồi mới biết sức khỏe đáng quý thế nào）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía sau <b>không được dùng ý định của bản thân, mệnh lệnh hay lời nhờ vả</b>.<br>×<span class='gd-jp'>日本に来てはじめて、日本語を勉強しよう。</span><br>Phía sau phải là \"điều đã nhận ra, sự thay đổi đã xảy ra\", không phải \"tôi sẽ làm gì\".<br>・Đừng nhầm với「động từ thể ます＋<span class='gd-jp'>はじめる</span>」(bắt đầu ～): <span class='gd-jp'>食べはじめる</span> là \"bắt đầu ăn\"; <span class='gd-jp'>食べてはじめて</span> là \"ăn rồi mới…\". Khác nhau chỉ ở chỗ có chữ「て」ở giữa hay không.<br>・Mẫu này vốn mang cảm giác \"trước đó hoàn toàn không biết\", nên dùng cho điều vốn đã biết, hiển nhiên thì sẽ rất lạ.</div><div class='gd-h'>Phân biệt với mẫu rất giống</div><div class='gd-sec'>Cùng là \"phải làm rồi mới biết\", hãy xem hai cách nói:<br><b>てはじめて</b> = nhìn lại phía sau, <b>làm xong rồi mới hiểu</b>: <span class='gd-jp'>実際に使ってみてはじめて、よさがわかった。</span>（thực sự dùng thử rồi mới biết cái hay của nó）<br><b>ないことには</b> = nêu điều kiện hướng về phía trước, <b>không làm trước thì không có cách nào</b>, phía sau phần lớn là phủ định: <span class='gd-jp'>実際に使ってみないことには、よさはわからない。</span>（không thực sự dùng thử thì sẽ không biết nó tốt hay không）</div><div class='gd-warn'>Mẹo phân biệt: nói về việc \"trải qua rồi mới vỡ lẽ\" thì dùng てはじめて; nói \"nếu không làm ～ trước thì không thể…\" thì dùng ないことには.</div>","n2-63":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜ものがある」 gần với kiểu nói <b>“có một cái gì đó rất ~”, “quả thật khiến người ta cảm thấy ~”</b> trong tiếng Việt. Khi nghe một buổi biểu diễn hay nhìn một tấm ảnh cũ, có thứ gì đó chạm vào lòng bạn nhưng bạn không gọi tên được là gì, người Nhật sẽ dùng mẫu này: <span class='gd-jp'>彼の演奏には心を打つものがある。</span>（Phần biểu diễn của anh ấy có một sức mạnh làm lay động lòng người）<br><span class='gd-jp'>もの</span> ở đây không chỉ một vật nhìn thấy được, mà là <b>một đặc tính, một cảm giác khó diễn tả thành lời</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Đánh giá người, việc, vật</span>Dùng để khen tác phẩm, màn thể hiện hay năng lực. So với việc nói thẳng “giỏi quá”, cách này nghe sâu sắc và điềm đạm hơn, nên bạn sẽ gặp rất nhiều trong bài phê bình phim, tin tức, hay lời nhận xét của sếp.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の演奏には人を引き込むものがある。</span>（Phần biểu diễn của anh ấy có sức cuốn hút người nghe）</div><div class='gd-ex-line'>・<span class='gd-jp'>新人だが、彼女の企画には光るものがある。</span>（Tuy là người mới, kế hoạch của cô ấy có những điểm sáng đáng chú ý）</div><div class='gd-sec'><span class='gd-tag'>Nói về cảm nhận của mình</span>Một việc nào đó khiến bạn có cảm giác nhất định, tốt hay xấu đều được.</div><div class='gd-ex-line'>・<span class='gd-jp'>この古い写真にはどこか懐かしいものがある。</span>（Tấm ảnh cũ này có gì đó thật gợi nhớ）</div><div class='gd-ex-line'>・<span class='gd-jp'>この年で徹夜するのは、つらいものがある。</span>（Ở tuổi này mà còn thức trắng đêm thì đúng là hơi chịu không nổi）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ: nối trực tiếp với dạng nguyên mẫu (dạng trong từ điển)　<span class='gd-pair'><span class='gd-jp'>心を打つ</span> → <span class='gd-jp'>心を打つものがある</span></span><br>Tính từ đuôi い: nối trực tiếp　<span class='gd-pair'><span class='gd-jp'>懐かしい</span> → <span class='gd-jp'>懐かしいものがある</span></span><br>Tính từ đuôi な: phải thêm 「な」　<span class='gd-pair'><span class='gd-jp'>見事</span> → <span class='gd-jp'>見事なものがある</span></span><br>Dạng phủ định cũng dùng được: <span class='gd-pair'><span class='gd-jp'>納得できない</span> → <span class='gd-jp'>納得できないものがある</span></span>（có chút gì đó khiến người ta khó chấp nhận）<br>Phía trước thường dùng 「<span class='gd-jp'>〜には</span>」 để nêu chủ thể: <span class='gd-jp'>この映画には</span>、<span class='gd-jp'>彼の言葉には</span>……</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'>Mấy cụm này gần như là cách nói cố định, học nguyên cụm là nhanh nhất:<br><span class='gd-jp'>心を打つものがある</span>（làm lay động lòng người）<br><span class='gd-jp'>胸に迫るものがある</span>（khiến người ta xúc động sâu sắc, chạm đến trái tim）<br><span class='gd-jp'>目を見張るものがある</span>（đáng để nhìn bằng con mắt khác, rất ấn tượng）<br><span class='gd-jp'>光るものがある</span>（có điểm nổi bật, sáng giá）<br><span class='gd-jp'>見るべきものがある</span>（có chỗ đáng xem）<br><span class='gd-jp'>感慨深いものがある</span>（khiến người ta bồi hồi cảm khái）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không phải 「ものがある」 nào cũng là mẫu ngữ pháp này</b>: <span class='gd-jp'>この店にはおいしいものがある。</span> chỉ đơn giản là “quán này có món ngon”, nói về đồ ăn thật sự. Chủ thể của mẫu ngữ pháp này thường là thứ trừu tượng như tác phẩm, màn thể hiện, trải nghiệm.<br>・<b>Chia quá khứ ở ある</b>: muốn nói “lúc đó đã rất xúc động” thì nói <span class='gd-jp'>心を打つものがあった</span>, đừng viết thành 心を打ったものがある.<br>・<b>Đừng quên な ở tính từ đuôi な</b>: phải là <span class='gd-jp'>見事なものがある</span>, không phải 見事ものがある, và cũng không nối thẳng với danh từ được.<br>・<b>Đừng dùng cho sự thật khách quan</b>: phòng rộng hay không thì đo được, cứ nói <span class='gd-jp'>この部屋は広い</span> là đủ; nói 「この部屋には広いものがある」 nghe rất kỳ. Mẫu này dùng cho những đặc tính “khiến người ta có cảm giác”.<br>・Sắc thái hơi trang trọng, nhưng trong văn nói vẫn dùng, ví dụ <span class='gd-jp'>それはちょっとつらいものがあるね</span>（cái đó đúng là hơi khó chịu thật đấy）.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'><b>ものだ（cảm thán）</b> = “~ thật đấy nhỉ”, bày tỏ cảm thán về <b>lẽ thường, cuộc sống nói chung</b>:<br><span class='gd-jp'>子どもの成長は早いものだ。</span>（Trẻ con lớn nhanh thật đấy）<br><b>ものがある</b> = chỉ vào <b>một người, một việc, một vật cụ thể</b> và nói nó có một đặc tính nào đó:<br><span class='gd-jp'>彼の成長ぶりには目を見張るものがある。</span>（Sự tiến bộ của anh ấy thật đáng nể）</div><div class='gd-warn'>Mẹo phân biệt: cảm thán kiểu “cuộc đời, chuyện thế gian là vậy đó” thì dùng ものだ; còn chỉ vào người hay tác phẩm trước mắt và nói “nó có một điểm ~” thì dùng ものがある.</div>","n2-64":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜抜き」 giống như khi gọi đồ uống bạn nói “không đá”, hay khi ăn phở bạn nói “không hành ngò”: <b>bỏ đi thứ lẽ ra phải có</b>. Ở Nhật, khi ăn sushi mà nói <span class='gd-jp'>わさび抜きでお願いします</span> nghĩa là “làm ơn đừng cho wasabi”. Phía trước luôn là <b>danh từ</b>, thường viết bằng chữ Hán <span class='gd-jp'>抜き</span>, đọc là ぬき.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>抜きで＋động tác</span>Bỏ đi một thứ nào đó rồi làm việc gì đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>わさび抜きでお願いします。</span>（Làm ơn đừng cho wasabi nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は朝ごはん抜きで会社に行った。</span>（Sáng nay tôi đi làm mà không ăn sáng）</div><div class='gd-sec'><span class='gd-tag'>抜きの＋danh từ</span>Đứng trước danh từ, nghĩa là “cái đã bỏ ~ đi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>玉ねぎ抜きのハンバーガーをください。</span>（Cho tôi một cái hamburger không hành tây）</div><div class='gd-sec'><span class='gd-tag'>冗談抜きで</span>Cách nói cố định, nghĩa là “nói thật đấy, không đùa đâu”, rất hay dùng trong văn nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談抜きで、このラーメンは日本一だと思う。</span>（Nói thật, tôi nghĩ tô ramen này ngon nhất Nhật Bản）</div><div class='gd-sec'><span class='gd-tag'>抜きには〜ない</span>“Không có ~ thì không thể ~”, dùng để nhấn mạnh thứ đó rất quan trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の協力抜きには、この仕事は終わらなかった。</span>（Không có sự giúp đỡ của anh ấy thì công việc này đã không thể xong）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の夏は花火抜きには語れない。</span>（Nói về mùa hè Nhật Bản thì không thể không nhắc đến pháo hoa）</div><div class='gd-sec'><span class='gd-tag'>は抜きにして</span>“~ thì bỏ qua đi, gác ~ sang một bên”, rất hay nghe trong tiệc tùng hoặc lúc mở đầu cuộc họp.</div><div class='gd-ex-line'>・<span class='gd-jp'>堅苦しい挨拶は抜きにして、乾杯しましょう。</span>（Bỏ qua mấy lời chào khách sáo đi, cùng cạn ly nào）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chỉ nối được với <b>danh từ</b>. “Không ăn sáng” không thể nói thành 食べ抜きで, mà phải nói <span class='gd-jp'>朝ごはん抜きで</span>, hoặc đổi sang động từ <span class='gd-jp'>朝ごはんを食べないで</span>.<br>・Cảm giác của 抜き là “vốn dĩ sẽ có, nhưng cố ý bỏ đi”. Nếu thứ đó vốn không nhất thiết phải có, ví dụ ra ngoài không mang ô, thì nói <span class='gd-jp'>傘なしで出かけた</span> sẽ tự nhiên hơn.<br>・Sau 「抜きには」 gần như luôn là nghĩa phủ định hoặc “không làm được”, ví dụ <span class='gd-jp'>できない</span>、<span class='gd-jp'>語れない</span>、<span class='gd-jp'>考えられない</span>; đừng nối với câu khẳng định thông thường.<br>・<span class='gd-jp'>冗談抜きで</span> phần lớn là người nói tự nhấn mạnh “tiếp theo tôi nói nghiêm túc đấy”, chứ không phải bảo đối phương “đừng đùa nữa”. Cũng có thể nói <span class='gd-jp'>冗談抜きに</span>, nghĩa y hệt.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'><b>抜きには〜ない</b> và <b>ないことには</b>（n2-19）đều có nghĩa “nếu không có / không ~ thì không thể ~”, khác nhau ở thứ đứng phía trước:<br>・<span class='gd-jp'>社長の許可抜きには決められない。</span>（Không có sự cho phép của giám đốc thì không thể quyết định）: phía trước là danh từ<br>・<span class='gd-jp'>社長が許可しないことには決められない。</span>（Giám đốc không gật đầu thì không thể quyết định）: phía trước là động từ</div><div class='gd-sec'><b>抜きで</b> và <b>ことなく</b>（n2-48）đều có thể dịch là “làm mà không ~”:<br>・<span class='gd-jp'>休憩抜きで働いた。</span>（Làm việc không nghỉ giải lao）: bỏ đi danh từ “giờ nghỉ”<br>・<span class='gd-jp'>休むことなく働いた。</span>（Làm việc không nghỉ chút nào）: phía trước là động từ, sắc thái văn viết hơn</div><div class='gd-warn'>Mẹo phân biệt: phía trước là <b>danh từ</b> thì dùng 抜き; phía trước là <b>động từ</b> thì đổi sang ないことには hoặc ことなく.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>抜き bắt nguồn từ động từ <span class='gd-jp'>抜く</span>（bỏ đi, lược bớt）, và trong đời sống người ta cũng hay dùng thẳng động từ này: <span class='gd-jp'>忙しくて昼ごはんを抜いた。</span>（Bận quá nên tôi bỏ bữa trưa）</div>","n2-65":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜きる」tương đương với <b>“~ hết”, “~ sạch”, “~ đến cùng”</b> trong tiếng Việt: chạy hết quãng đường, tiêu sạch tiền, mệt rã rời.<br>「〜きれる」là <b>làm hết được</b>, còn「〜きれない」là <b>không làm hết được, ~ không xuể</b>. Điểm chung là “toàn bộ, triệt để, không còn lại chút nào”.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Lấy động từ ở thể ます, bỏ ます đi rồi thêm <span class='gd-jp'>きる</span>.<br><span class='gd-pair'><span class='gd-jp'>走ります</span> → bỏ ます → <span class='gd-jp'>走りきる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べきる</span></span><span class='gd-pair'><span class='gd-jp'>使います</span> → <span class='gd-jp'>使いきる</span></span><br><span class='gd-jp'>する</span> dùng với những từ như <span class='gd-jp'>説明する</span>: <span class='gd-pair'><span class='gd-jp'>説明します</span> → <span class='gd-jp'>説明しきる</span></span><br>Sau khi ghép, bản thân <span class='gd-jp'>きる</span> chia như động từ nhóm 1 (五段動詞): <span class='gd-jp'>きった</span> (đã ~ hết), <span class='gd-jp'>きれる</span> (làm hết được), <span class='gd-jp'>きれない</span> (không làm hết được).</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Làm đến cùng, làm hết sạch</span>Không bỏ cuộc giữa chừng, hoặc không còn dư chút nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>フルマラソンを走りきった。</span>(Mình đã chạy hết cự ly marathon đầy đủ rồi!)</div><div class='gd-ex-line'>・<span class='gd-jp'>給料を三日で使いきってしまった。</span>(Lương tiêu sạch chỉ trong ba ngày.)</div><div class='gd-sec'><span class='gd-tag'>Đến mức cùng cực</span>Đi sau các động từ chỉ trạng thái như <span class='gd-jp'>疲れる</span>, <span class='gd-jp'>困る</span>, mang nghĩa “hoàn toàn ~, ~ hết cỡ”.</div><div class='gd-ex-line'>・<span class='gd-jp'>残業続きで、疲れきっている。</span>(Tăng ca liên tục nên mệt rã rời.)</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな分かりきったこと、聞かないでよ。</span>(Chuyện rõ như ban ngày vậy thì đừng hỏi nữa mà.)</div><div class='gd-sec'><span class='gd-tag'>Nói rất chắc chắn</span><span class='gd-jp'>言いきる</span> = khẳng định chắc nịch, nói chết luôn, không chừa đường lui.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は「絶対に勝つ」と言いきった。</span>(Anh ấy khẳng định chắc nịch là “nhất định sẽ thắng”.)</div><div class='gd-sec'><span class='gd-tag'>きれる／きれない</span>Hỏi xem có làm hết được không, hoặc nhiều đến mức làm không xuể.</div><div class='gd-ex-line'>・<span class='gd-jp'>こんなにたくさん、一人で食べきれる？</span>(Nhiều thế này, một mình bạn ăn hết nổi không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>空に数えきれないほど星が出ている。</span>(Trên trời có nhiều sao đến mức đếm không xuể.)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日からの旅行が待ちきれない。</span>(Mình nóng lòng chờ chuyến du lịch từ ngày mai quá.)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải dùng thể ます bỏ ます, không phải thể từ điển: đúng là <span class='gd-jp'>食べきる</span>, không phải 「食べるきる」.<br>・<span class='gd-jp'>食べきれない</span> chuyên chỉ “lượng quá nhiều nên không ăn hết được”; còn <span class='gd-jp'>食べられない</span> có phạm vi rộng hơn, có thể là “không ăn được” (dị ứng, không dám ăn), cũng có thể là “không ăn nổi nữa” (<span class='gd-jp'>もうお腹いっぱいで食べられない</span>). Khi muốn nói rõ “phần nhiều quá, ăn không hết”, dùng <span class='gd-jp'>食べきれない</span> là ít bị hiểu nhầm nhất.<br>・<span class='gd-jp'>待ちきれない</span> là “không chờ nổi, nóng lòng”, không phải “chờ không hết”.<br>・<span class='gd-jp'>疲れきる</span> không phải “hết mệt”, mà là “mệt đến kiệt sức”. Dễ hiểu nhầm vì trong tiếng Việt chữ “hết” có thể nghe như “xong rồi, không còn nữa”.<br>・Viết bằng chữ Hán <span class='gd-jp'>切る</span> (<span class='gd-jp'>食べ切る</span>) cũng đúng, nhưng đây không phải <span class='gd-jp'>着る</span> (mặc quần áo).</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'><b>〜終わる</b> = hành động đó <b>đã kết thúc</b>, có làm hết sạch hay không không phải điểm chính:<br></div><div class='gd-ex-line'>・<span class='gd-jp'>もうご飯食べ終わった？</span>(Bạn ăn cơm xong chưa?: hỏi việc ăn cơm đã kết thúc chưa)</div><div class='gd-sec'><b>〜きる</b> = <b>toàn bộ, không còn lại chút nào</b>, thường mang cảm giác “nhiều lắm, không dễ dàng gì”:</div><div class='gd-ex-line'>・<span class='gd-jp'>こんなに多いのに、全部食べきったの？</span>(Nhiều thế này mà bạn ăn sạch hết luôn á?)</div><div class='gd-warn'>Mẹo phân biệt: muốn nói “làm xong, kết thúc” thì dùng <span class='gd-jp'>終わる</span>; muốn nhấn mạnh “ăn sạch, gắng đến cùng, không còn lại chút nào” thì dùng <span class='gd-jp'>きる</span>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu ngược lại là <span class='gd-jp'>〜かける</span> (làm dở chừng): <span class='gd-jp'>食べかけのパン</span> là “ổ bánh mì ăn dở”, còn <span class='gd-jp'>食べきる</span> là “ăn sạch hết”. Nhớ hai mẫu này cùng nhau thì rất dễ phân biệt.</div>","n2-66":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜に先立って」là cách nói trang trọng của <b>“trước khi ~, trước hết ~”</b>. Giống như MC nói “trước khi buổi lễ bắt đầu, xin mời đại diện ban tổ chức phát biểu”, hay bản tin nói “trước khi sản phẩm mới ra mắt, đã tổ chức họp báo”: đó là kiểu “trước khi” rất trang trọng. Những việc đời thường như “rửa tay trước khi ăn” thì không dùng mẫu này.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'>Phía trước đặt một <b>sự kiện lớn, trang trọng, có kế hoạch</b> (họp, thi công, ra mắt, khởi hành, buổi lễ), phía sau nói <b>việc chuẩn bị, thông báo hay nghi thức được làm trước đó</b>. Thường gặp nhất trong tin tức, thông báo, bài phát biểu, văn bản kinh doanh.</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品の発売に先立って、記者会見が開かれた。</span>(Trước khi sản phẩm mới ra mắt, một buổi họp báo đã được tổ chức.)</div><div class='gd-ex-line'>・<span class='gd-jp'>出発に先立ち、参加者に注意事項が説明された。</span>(Trước khi khởi hành, những điều cần lưu ý đã được giải thích cho người tham gia.)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Danh từ＋に先立って／に先立ち</b>: phổ biến nhất, danh từ thường là những từ như 「開会、工事、発売」 có thể thêm する.<br><span class='gd-pair'><span class='gd-jp'>工事</span> → <span class='gd-jp'>工事に先立って</span></span><br><b>Động từ thể từ điển＋に先立って</b>: cũng được, nhưng ít gặp hơn.<br><span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するに先立って</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>留学するに先立って、ビザの手続きを済ませた。</span>(Trước khi đi du học, mình đã làm xong thủ tục visa.)</div><div class='gd-sec'>「に先立ち」mang tính văn viết và cứng hơn「に先立って」một chút, nghĩa thì giống nhau.</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>に先立ちまして</span>Cách nói cố định khi mở đầu bài phát biểu, buổi lễ, lịch sự hơn nữa.</div><div class='gd-ex-line'>・<span class='gd-jp'>開会に先立ちまして、一言ご挨拶申し上げます。</span>(Trước khi khai mạc, cho phép tôi có đôi lời chào mừng.)</div><div class='gd-sec'><span class='gd-tag'>に先立つ＋danh từ</span>Bổ nghĩa trực tiếp cho danh từ phía sau, nghĩa là “~ được tổ chức trước ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に先立つ開会式で、選手代表が宣誓した。</span>(Tại lễ khai mạc diễn ra trước trận đấu, đại diện các vận động viên đã tuyên thệ.)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ nối thẳng với「に」, đừng thêm の: đúng là <span class='gd-jp'>開会に先立って</span>, không phải 開会の先立って.<br>・Động từ phải dùng thể từ điển, không dùng thể た: không thể nói 「決めたに先立って」.<br>・Cách đọc là <b>さきだって</b>, không phải せんだって.<br>・Đừng dùng cho chuyện nhỏ hằng ngày, nghe sẽ rất cường điệu: “đánh răng trước khi ngủ” phải nói <span class='gd-jp'>寝る前に歯を磨く</span>, nói thành 「寝るに先立って」 nghe như đang đọc thông cáo báo chí.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'><b>前に</b> = “trước khi” thông thường, dùng được trong mọi hoàn cảnh: <span class='gd-jp'>会議の前に、資料を確認しておこう。</span>(Trước buổi họp, mình xem qua tài liệu trước nhé.)<br><b>に先立って</b> = trong hoàn cảnh trang trọng, “vì sự kiện lớn đó, nên làm trước ~”: <span class='gd-jp'>会議に先立ち、資料が配布された。</span>(Trước khi cuộc họp bắt đầu, tài liệu đã được phát.)<br><b>際に</b> = “khi ~”, nói về đúng lúc đó, không phải trước đó: <span class='gd-jp'>ご使用の際は、十分ご注意ください。</span>(Khi sử dụng, xin hãy hết sức cẩn thận.)／<span class='gd-jp'>ご使用に先立ち、説明書をお読みください。</span>(Trước khi sử dụng, xin hãy đọc hướng dẫn.)</div><div class='gd-warn'>Mẹo phân biệt: nói “trước khi” thông thường thì dùng 前に; trong hoàn cảnh trang trọng, “trước khi sự kiện lớn bắt đầu, làm công tác chuẩn bị” thì dùng に先立って; “ngay lúc đang làm” thì dùng 際に.</div>","n2-67":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cả ba mẫu này đều giống kiểu <b>“～ muốn chết”, “～ không chịu nổi”, “không kìm được mà cứ ～”</b> trong tiếng Việt. Khi cảm xúc hoặc cảm giác cơ thể mạnh đến mức không nén được, bạn dùng chúng. Nghĩa gần giống nhau, khác nhau chủ yếu ở <b>mức độ trang trọng</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格の知らせを聞いて、嬉しくてたまらない。</span>（Nghe tin đậu, vui không chịu nổi）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước phải chuyển sang dạng「て」, rồi mới nối với <span class='gd-jp'>たまらない</span>／<span class='gd-jp'>ならない</span>／<span class='gd-jp'>しょうがない</span>.<br>Động từ: dùng thể て　<span class='gd-pair'><span class='gd-jp'>気になる</span> → <span class='gd-jp'>気になってしょうがない</span></span><br>Tính từ い: đổi「い」ở cuối thành「くて」　<span class='gd-pair'><span class='gd-jp'>嬉しい</span> → <span class='gd-jp'>嬉しくてたまらない</span></span><br>Tính từ な: thêm「で」phía sau　<span class='gd-pair'><span class='gd-jp'>心配</span> → <span class='gd-jp'>心配でたまらない</span></span><br>Muốn làm gì đó: <span class='gd-jp'>たい</span> cũng đổi「い」thành「くて」　<span class='gd-pair'><span class='gd-jp'>会いたい</span> → <span class='gd-jp'>会いたくてたまらない</span></span></div><div class='gd-h'>Chọn trong ba mẫu thế nào</div><div class='gd-sec'><span class='gd-tag'>たまらない</span>Chuẩn nhất, nối được với tâm trạng, cảm giác cơ thể, mong muốn, dùng thoải mái hằng ngày.</div><div class='gd-ex-line'>・<span class='gd-jp'>国の家族に会いたくてたまらない。</span>（Nhớ gia đình ở quê không chịu nổi）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暑くてたまらない。</span>（Hôm nay nóng không chịu nổi）</div><div class='gd-sec'><span class='gd-tag'>しょうがない</span>Khẩu ngữ nhất, nói chuyện với bạn bè bạn sẽ nghe rất nhiều. Cách nói trang trọng hơn một chút là <span class='gd-jp'>しかたがない</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日あまり寝てないから、眠くてしょうがない。</span>（Hôm qua ngủ không được mấy, buồn ngủ chết đi được）</div><div class='gd-sec'><span class='gd-tag'>ならない</span>Thiên về văn viết, trang trọng, mang sắc thái “cảm giác ấy cứ tự nhiên trào lên trong lòng”. Hay đi cùng những cách nói kiểu “cảm giác tự nảy ra” như <span class='gd-jp'>気がする</span>、<span class='gd-jp'>思われる</span>、<span class='gd-jp'>思い出される</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が何か隠している気がしてならない。</span>（Tôi cứ có cảm giác anh ấy đang giấu điều gì đó）</div><div class='gd-ex-line'>・<span class='gd-jp'>故郷のことが思い出されてならない。</span>（Cứ không kìm được mà nhớ về quê hương）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này nói về cảm giác của <b>chính mình</b>. Nói về người khác thì phải thêm <span class='gd-jp'>ようだ</span>、<span class='gd-jp'>らしい</span>：<span class='gd-jp'>妹は寂しくてたまらないようだ。</span>（Em gái có vẻ buồn không chịu nổi）<br>・Phía trước chỉ đặt được cảm giác, cảm xúc, không đặt được hành động do mình chủ động quyết định làm. Không thể nói “học đến mức không chịu nổi” bằng <span class='gd-jp'>勉強してたまらない</span>. Muốn nói rất muốn làm gì thì dùng <span class='gd-jp'>〜たくて</span>.<br>・Đừng nhầm <span class='gd-jp'>てならない</span> với <span class='gd-jp'>てはならない</span>. Thêm「は」vào là thành “không được phép”：<span class='gd-jp'>嘘をついてはならない。</span>（Không được nói dối）Còn <span class='gd-jp'>なくてはならない</span> là “phải”.<br>・Đừng nhầm <span class='gd-jp'>てしょうがない</span> với <span class='gd-jp'>てもしょうがない</span>. Thêm「も」vào là thành “～ cũng vô ích”：<span class='gd-jp'>今さら後悔してもしょうがない。</span>（Bây giờ mới hối hận cũng vô ích）<br>・Trong văn bản trang trọng hay bài phát biểu, dùng <span class='gd-jp'>しょうがない</span> sẽ quá suồng sã, hãy đổi sang <span class='gd-jp'>ならない</span> hoặc <span class='gd-jp'>しかたがない</span>.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Cả hai đều hay được dịch là “không kìm được”, nên rất dễ lẫn với <b>ずにはいられない</b>.<br><b>てたまらない</b> = cảm giác mạnh đến mức không chịu nổi, trọng tâm là <b>chính cảm xúc</b>：<span class='gd-jp'>母の病気が心配でたまらない。</span>（Tôi lo cho bệnh của mẹ không chịu nổi）<br><b>ずにはいられない</b> = không kìm được mà <b>làm một hành động nào đó</b>：<span class='gd-jp'>心配で、母に電話せずにはいられなかった。</span>（Lo quá, không kìm được phải gọi điện cho mẹ）</div><div class='gd-warn'>Mẹo phán đoán: nếu cái không kìm được là “cảm giác” thì dùng てたまらない; nếu không kìm được mà “làm một việc gì đó” thì dùng ずにはいられない.</div>"});
